import{t as e}from"./jsx-runtime-DHXBON9B.js";import{s as t}from"./Method-19l8_wpl.js";var n=e(),r=[{beginner:{question:(0,n.jsx)(n.Fragment,{children:`로봇이 LiDAR를 한동안 녹화하기만 하면 그것이 곧 지도가 되지 않는 이유는 무엇일까요?`}),analogy:(0,n.jsx)(n.Fragment,{children:`어두운 건물을 손전등과 수첩만으로 지도로 그린다고 상상해 보세요. 멈출 때마다 손전등에 비친 모습을 스케치하지만, 그 자리에서 어디에 서서 어느 쪽을 보고 있었는지를 함께 적어 두지 않으면 스케치 백 장은 종이 더미일 뿐입니다. 이 비유가 맞지 않는 곳이 하나 있습니다. 사람은 문틀을 눈으로 알아보지만, 로봇은 자기가 서 있던 위치를 오직 숫자로부터 계산해야 합니다.`}),story:[(0,n.jsxs)(n.Fragment,{children:[`LiDAR는 레이저 펄스를 쏘고 반사되어 돌아오는 시간을 재서 주변 표면까지의 거리를 측정하는 센서입니다. 센서가 한 바퀴 도는 동안 얻은 결과를 `,(0,n.jsx)(`strong`,{children:`스캔`}),`이라 부릅니다. 스캔은 “이 방향으로 이만큼 떨어진 곳에 표면이 있었다”는 점들의 모음입니다. Go2에 달린 Hesai XT16은 레이저 채널이 16개라서, 스캔 한 장은 층 전체의 그림이 아니라 가늘고 성긴 고리 모양의 점입니다.`]}),(0,n.jsxs)(n.Fragment,{children:[`스캔은 센서 자신의 좌표로 기록됩니다. “내 앞 3 m, 왼쪽 1 m” 같은 식입니다. 로봇이 걸어가면 다음 스캔은 새로운 “내 앞”을 기준으로 합니다. 스캔을 합치려면 모든 스캔을 하나의 공통 좌표계, 즉 `,(0,n.jsx)(`strong`,{children:`월드 좌표계`}),`로 옮겨야 합니다. 이렇게 옮기려면 스캔을 찍은 순간 로봇의 `,(0,n.jsx)(`strong`,{children:`포즈`}),`, 곧 위치와 바라보던 방향을 알아야 합니다.`]}),(0,n.jsx)(n.Fragment,{children:`문제는 아무도 로봇에게 포즈를 알려 주지 않는다는 점입니다. 로봇은 LiDAR 자체와, 회전과 가속을 느끼는 관성 센서(IMU)로부터 포즈를 추정해야 합니다. 포즈에 작은 오차가 생기면 스캔 전체가 그만큼 옮겨집니다. 방향이 1°만 틀려도 8 m 떨어진 벽의 점은 약 14 cm 비켜 나므로, 같은 벽이 조금 떨어진 두 겹으로 그려집니다.`}),(0,n.jsx)(n.Fragment,{children:`그래서 처리는 두 단계로 이루어집니다. 먼저 FAST-LIO나 LIO-SAM 같은 상태 추정기가 스캔마다 포즈를 추정합니다. 그다음 각 스캔을 자기 포즈로 변환해 지도에 더하는데, 보통 거의 겹치는 점을 솎아 내는 다운샘플링을 함께 합니다. 기록 중에 움직인 것, 예를 들어 옆을 지나간 사람은 스캔마다 다른 자리에서 보이므로 궤적처럼 누적됩니다.`}),(0,n.jsx)(n.Fragment,{children:`결과는 층 전체의 조밀한 점군입니다. 포즈가 좋으면 벽은 얇고 복도는 곧게 나옵니다. 포즈가 드리프트하면 벽이 겹치고 복도가 휩니다. 그래서 이 강좌의 나머지 대부분은 점을 그리는 방법이 아니라 포즈를 추정하는 방법을 다룹니다.`})],tryIt:(0,n.jsxs)(n.Fragment,{children:[`스캔을 몇 장만 두고 시작해 `,(0,n.jsx)(`em`,{children:`누적한 스캔 수`}),`를 늘려 보세요. 더 많은 포즈를 합칠수록 복도가 채워집니다. 다음으로 `,(0,n.jsx)(`em`,{children:`포즈 드리프트`}),`를 켜고 벽의 먼 끝이 여러 겹으로 갈라지는 모습을 보세요. 마지막으로 `,(0,n.jsx)(`em`,{children:`사람이 지나감`}),`을 켜면, 스캔마다 사람을 다른 곳에서 보았기 때문에 복도를 가로지르는 점의 줄이 남습니다.`]}),misconception:(0,n.jsx)(n.Fragment,{children:`“3D 지도는 긴 LiDAR 녹화일 뿐이다.” 녹화에는 서로 다른 센서 좌표계로 찍힌 스캔들이 들어 있을 뿐입니다. 모든 스캔에 포즈를 주고 하나의 월드 좌표계로 옮긴 뒤에야 지도가 됩니다. 포즈가 틀리면 센서가 아무리 좋아도 흐리고 겹친 지도가 나옵니다.`}),summary:[(0,n.jsx)(n.Fragment,{children:`LiDAR 스캔 한 장은 센서 자신의 좌표로 표현된 성긴 점의 모음입니다.`}),(0,n.jsx)(n.Fragment,{children:`지도는 추정한 포즈로 각각 하나의 월드 좌표계에 옮긴 수많은 스캔의 합집합입니다.`}),(0,n.jsx)(n.Fragment,{children:`포즈 오차는 벽을 겹치게 하고 움직이는 물체는 잔상을 남기므로, 포즈 추정이 지도 작성보다 먼저입니다.`})]},advanced:{objectives:[(0,n.jsx)(n.Fragment,{children:`지도를 변환된 스캔의 합집합으로 쓰고, 어떤 양이 추정값이고 어떤 양이 측정값인지 정확히 구분합니다.`}),(0,n.jsx)(n.Fragment,{children:`포즈 하나의 회전·병진 오차가 거리에 따라 지도 점을 얼마나 옮기는지 계산합니다.`}),(0,n.jsx)(n.Fragment,{children:`오도메트리, 매핑, SLAM을 구분하고 FAST-LIO와 LIO-SAM이 각각 어디에 속하는지 설명합니다.`})],model:[[`상태`,(0,n.jsxs)(n.Fragment,{children:[`스캔마다 포즈 하나, `,(0,n.jsx)(t,{children:String.raw`T_{W,k} = (R_{W,k}, t_{W,k}) \in SE(3)`}),`: 스캔 `,(0,n.jsx)(t,{children:`k`}),` 시점 센서의 월드 좌표계 W에서의 회전과 병진.`]})],[`좌표계`,(0,n.jsxs)(n.Fragment,{children:[`각 스캔 `,(0,n.jsx)(t,{children:String.raw`\mathcal{S}_k`}),`는 그 스캔 시점의 LiDAR 좌표계로 표현됩니다. W는 주행 시작에 고정되며, 건물 좌표계나 측지 좌표계가 아닙니다.`]})],[`측정`,(0,n.jsx)(n.Fragment,{children:`각 점은 알려진 빔 방향을 따른 거리입니다. 스캔 안의 점 위치는 측정값이지만, 포즈는 측정되지 않고 추정됩니다.`})],[`가정`,(0,n.jsx)(n.Fragment,{children:`장면이 정적이라고 가정합니다. 움직이는 것은 이 가정을 깨며 잔상으로 누적됩니다.`})],[`잡음`,(0,n.jsx)(n.Fragment,{children:`점마다 수 cm의 거리 잡음, 그리고 보정하지 않으면 시간에 따라 커지는 포즈 오차(드리프트). 먼 거리에서 지도가 흐려지는 주된 원인은 포즈 오차입니다.`})]],steps:[{title:`입력`,text:(0,n.jsxs)(n.Fragment,{children:[`스캔 `,(0,n.jsx)(t,{children:String.raw`\mathcal{S}_1,\dots,\mathcal{S}_N`}),`. 각 스캔은 점 `,(0,n.jsx)(t,{children:String.raw`p_L \in \mathbb{R}^3`}),`(m, LiDAR 좌표계)의 집합이며, 그 사이의 IMU 샘플이 함께 주어집니다.`]})},{title:`포즈 추정`,text:(0,n.jsxs)(n.Fragment,{children:[`LiDAR-관성 추정기가 스캔마다 `,(0,n.jsx)(t,{children:String.raw`T_{W,k}`}),`를 내놓습니다. 가장 어려운 부분이며 3–17강의 주제입니다.`]})},{title:`변환`,text:(0,n.jsx)(n.Fragment,{children:`각 점을 그 스캔의 포즈로 월드 좌표계에 옮깁니다.`}),tex:String.raw`p_W = R_{W,k}\,p_L + t_{W,k}`},{title:`누적`,text:(0,n.jsx)(n.Fragment,{children:`지도는 변환한 모든 스캔의 합집합이며, 조밀한 곳이 지배하지 않도록 보통 복셀 다운샘플링을 합니다.`}),tex:String.raw`\mathcal{M} = \bigcup_{k=1}^{N} T_{W,k}\,\mathcal{S}_k`},{title:`출력`,text:(0,n.jsxs)(n.Fragment,{children:[`좌표계 W의 점군 `,(0,n.jsx)(t,{children:String.raw`\mathcal{M}`}),`. 그 선명도는 정성적이지만 포즈 일관성을 직접 보여 줍니다.`]})}],example:(0,n.jsxs)(n.Fragment,{children:[`벽의 한 점이 `,(0,n.jsx)(t,{children:String.raw`p_L = (8, 0)`}),` m로 측정되었다고 합시다(간단히 평면으로 봅니다). 실제 포즈가 `,(0,n.jsx)(t,{children:String.raw`t = (2, 1)`}),` m, 요 90°이면 점은 `,(0,n.jsx)(t,{children:String.raw`p_W = (2 + 8\cos 90^\circ,\ 1 + 8\sin 90^\circ) = (2.000, 9.000)`}),` m에 놓입니다. 추정한 요가 91°라면 `,(0,n.jsx)(t,{children:String.raw`p_W = (2 - 0.1396,\ 1 + 7.9988) = (1.860, 8.999)`}),` m로, 점이 옆으로 0.140 m 움직입니다. 1°(0.01745 rad) 오차에 대해 `,(0,n.jsx)(t,{children:String.raw`8 \times 0.01745`}),` m입니다. 반면 병진 오차 5 cm는 거리와 상관없이 스캔의 모든 점을 똑같이 5 cm 옮깁니다. 따라서 먼 거리에서는 회전 오차가 지배적입니다.`]}),paper:(0,n.jsx)(n.Fragment,{children:`LOAM(Zhang, Singh, 2014)은 문제를 빠른 오도메트리와 느린 매핑으로 나눕니다. FAST-LIO2(Xu 외, 2022)는 반복 칼만 필터로 포즈를 추정하고 원시 점을 증분 ikd-Tree 지도에 삽입합니다. LIO-SAM(Shan 외, 2020)은 루프 클로저를 포함할 수 있는 팩터 그래프에서 포즈를 추정하므로, 이전 포즈도 나중에 바뀔 수 있습니다.`}),site:(0,n.jsx)(n.Fragment,{children:`누적 그림은 합성 포즈 40개와 2 cm 거리 잡음이 있는 광선 추적 스캔으로 만든 2D 복도입니다. “포즈 드리프트”는 추정 포즈에 서서히 커지는 방향 오차와 옆 방향 오차를 더합니다. 플레이그라운드는 같은 원리를 실시간 2D 추정기로 보여 줍니다. 어느 쪽도 FAST-LIO나 LIO-SAM을 실행하지 않습니다.`}),dataset:(0,n.jsxs)(n.Fragment,{children:[`공개한 층은 FAST-LIO(2F, 3F, 6F, 8F)와 LIO-SAM(4F)으로 매핑했습니다. 정답 포즈가 없으므로 지도 정확도를 수치로 평가할 수 없습니다. 4F의 `,(0,n.jsx)(`code`,{children:`t`}),` 필드는 그 점을 정합한 LIO-SAM 스캔의 시각(첫 포즈 기준)이며, 점마다의 측정 시각이 아닙니다. 4F의 `,(0,n.jsx)(`code`,{children:`r g b`}),` 필드는 미리 계산해 넣은 높이 무지개 색이며 카메라 색이 아닙니다. 일부 층에는 동적 잔상이 남아 있고, 원본 지도가 계속 기본값입니다.`]}),interactiveLink:(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(`em`,{children:`누적한 스캔 수`}),`는 합집합의 `,(0,n.jsx)(t,{children:`N`}),`입니다. `,(0,n.jsx)(`em`,{children:`포즈 드리프트`}),`는 실제 `,(0,n.jsx)(t,{children:String.raw`T_{W,k}`}),` 대신 `,(0,n.jsx)(t,{children:`k`}),`에 따라 방향·옆 방향 오차가 커지는 추정값을 쓰므로, 뒤쪽 스캔일수록 더 많이 어긋납니다. `,(0,n.jsx)(`em`,{children:`사람이 지나감`}),`은 정적 장면 가정을 깹니다. 사람은 스캔마다 다른 자리에서 `,(0,n.jsx)(t,{children:String.raw`\mathcal{S}_k`}),`에 들어갑니다.`]}),check:{q:`스캔 하나의 방향 오차가 0.5°입니다. 20 m 떨어진 벽의 점은 지도에서 얼마나 어긋날까요?`,options:[`약 1.7 cm`,`약 17 cm`,`약 1.7 m`,`약 0.5 m`],answer:1,explain:(0,n.jsxs)(n.Fragment,{children:[`어긋남 ≈ 거리 × 라디안 각도: `,(0,n.jsx)(t,{children:String.raw`20 \times 0.5 \times \pi/180 = 20 \times 0.00873 \approx 0.175`}),` m.`]})}}},{beginner:{question:(0,n.jsx)(n.Fragment,{children:`Go2의 LiDAR와 IMU는 정확히 무엇을 측정하며, 로봇에게는 왜 둘 다 필요할까요?`}),analogy:(0,n.jsx)(n.Fragment,{children:`몇 걸음마다 한 번씩만 눈을 깜빡 떠서 방을 보고, 그사이에는 속귀(전정기관)가 몸이 어떻게 돌고 흔들리는지 계속 알려 준다고 생각해 보세요. 눈을 뜬 순간은 방의 모양을 보여 주고, 속귀는 그 틈을 메우지만 점점 감을 잃습니다. 다만 차이가 있습니다. 속귀는 중력을 숫자로 알려 주지 않지만, IMU는 언제나 중력을 숫자로 내놓습니다.`}),story:[(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(`strong`,{children:`LiDAR`}),`(여기서는 Hesai XT16)는 회전하는 헤드에 서로 다른 고도각으로 쌓인 레이저 16개를 갖고 있습니다. 레이저 반사 하나는 알려진 방향으로의 거리(`,(0,n.jsx)(`strong`,{children:`레인지`}),`)를 줍니다. 위아래 각도는 레이저 채널이 정하고, 좌우 각도는 헤드의 회전이 정합니다. 이 셋이 3D 점 하나를 정합니다. 헤드가 돌면서 측정하므로 점마다 자기 측정 시각도 갖습니다.`]}),(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(`strong`,{children:`IMU`}),`(관성 측정 장치)에는 몸체가 얼마나 빨리 도는지(각속도, rad/s)를 재는 자이로스코프와, `,(0,n.jsx)(`strong`,{children:`비력`}),`(specific force, m/s²)을 재는 가속도계가 들어 있습니다. 비력은 가속도에서 중력을 뺀 값입니다. 그래서 가만히 놓인 IMU도 0을 읽지 않습니다. 중력에 맞서 받쳐 주는 탁자의 힘, 약 9.8 m/s²를 느끼기 때문입니다.`]}),(0,n.jsxs)(n.Fragment,{children:[`두 센서의 장점은 정반대입니다. LiDAR는 형상을 직접 보지만 완전한 스캔을 1초에 몇 번밖에 주지 못합니다. IMU는 1초에 수백 번 값을 내지만 모든 값에 `,(0,n.jsx)(`strong`,{children:`바이어스`}),`라는 작은 치우침과 잡음이 있습니다. 그래서 IMU 값만 더해 가면 몇 초 안에 실제에서 멀어지고, LiDAR가 벽을 기준으로 추정값을 붙잡아 줍니다.`]}),(0,n.jsx)(n.Fragment,{children:`이 데이터셋에서 중요한 세부 사항이 있습니다. 여기서 쓰는 IMU의 원래 좌표계는 정지 상태에서 z축에 약 −9.4 m/s²를 읽으므로, z축이 대략 아래를 향합니다. 이것은 기록 데이터의 성질이며, 센서가 실제로 어떻게 장착되었는지는 문서로 남아 있지 않습니다. 소프트웨어는 FAST-LIO에 넘기기 전에 축 부호를 바꿉니다(2강).`}),(0,n.jsx)(n.Fragment,{children:`그래서 이후 모든 단계는 두 가지 사실 위에 서 있습니다. LiDAR의 점마다 자기 시각이 있고, IMU는 그 시각들 사이의 움직임을 바이어스와 잡음을 안은 채 알려 주며, 바이어스와 잡음은 추정해야 합니다.`})],tryIt:(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(`em`,{children:`스캔 재생`}),`을 누르거나 `,(0,n.jsx)(`em`,{children:`스캔 안의 시각`}),`을 끌어 보세요. 회전하는 헤드가 측정하는 순서대로 점이 나타나며, 이른 점에서 늦은 점까지 색이 달라집니다. 한 스캔의 마지막 점이 첫 점보다 눈에 띄게 늦게 측정된다는 데 주목하세요. IMU 패널은 원래 IMU 좌표계의 정지 상태 값을 보여 줍니다. 가장 큰 성분은 음의 z축 방향 중력입니다.`]}),misconception:(0,n.jsx)(n.Fragment,{children:`“가속도계는 가속도를 재므로 정지하면 0을 읽는다.” 가속도계는 비력을 잽니다. 정지하면 중력에 맞서 약 9.8 m/s²를 읽고, 자유 낙하할 때 오히려 0을 읽습니다.`}),summary:[(0,n.jsx)(n.Fragment,{children:`XT16은 거리와 두 각도로 3D 점을 주며, 점마다 자기 측정 시각이 있습니다.`}),(0,n.jsx)(n.Fragment,{children:`IMU는 각속도와 비력을 높은 빈도로 주며, 둘 다 바이어스와 잡음이 있습니다.`}),(0,n.jsx)(n.Fragment,{children:`LiDAR는 추정값을 형상에 고정하고, IMU는 스캔 사이의 움직임을 채웁니다.`})]},advanced:{objectives:[(0,n.jsx)(n.Fragment,{children:`LiDAR 반사 (r, α, θ)를 LiDAR 좌표계의 점으로 바꾸고, 어느 양이 시각을 갖는지 말합니다.`}),(0,n.jsx)(n.Fragment,{children:`바이어스, 잡음, 중력을 포함한 IMU 측정 모델을 쓰고 정지 상태의 값을 예측합니다.`}),(0,n.jsx)(n.Fragment,{children:`설정과 기록으로 알 수 있는 것과 문서로 남지 않은 것을 구분합니다.`})],model:[[`LiDAR 측정`,(0,n.jsxs)(n.Fragment,{children:[`고도각 `,(0,n.jsx)(t,{children:String.raw`\alpha`}),`(채널마다 고정)와 방위각 `,(0,n.jsx)(t,{children:String.raw`\theta`}),`(헤드 회전) 방향의 거리 `,(0,n.jsx)(t,{children:`r`}),`(m), 점마다의 시각 `,(0,n.jsx)(t,{children:String.raw`t_j`}),`.`]})],[`IMU 측정`,(0,n.jsxs)(n.Fragment,{children:[`자이로 `,(0,n.jsx)(t,{children:String.raw`\omega_m`}),`(rad/s)와 가속도계 `,(0,n.jsx)(t,{children:String.raw`a_m`}),`(m/s²), 둘 다 IMU 몸체 좌표계.`]})],[`중력 규약`,(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t,{children:`g`}),`는 월드 좌표계의 중력 벡터로, z가 위인 월드에서는 `,(0,n.jsx)(t,{children:String.raw`(0,0,-9.81)`}),` m/s²입니다. 정지 시 `,(0,n.jsx)(t,{children:String.raw`a_W = 0`}),`이므로 `,(0,n.jsx)(t,{children:String.raw`a_m = -R^\top g`}),`.`]})],[`잡음`,(0,n.jsxs)(n.Fragment,{children:[`백색 잡음 `,(0,n.jsx)(t,{children:String.raw`n_g, n_a`}),`와 랜덤 워크로 모델링한 바이어스 `,(0,n.jsx)(t,{children:String.raw`b_g, b_a`}),`(천천히 변하며 상태와 함께 추정).`]})],[`시계`,(0,n.jsx)(n.Fragment,{children:`LiDAR와 IMU는 서로 다른 타임스탬프를 쓰며, 둘 사이의 오프셋을 알거나 추정해야 합니다(4강).`})]],steps:[{title:`입력`,text:(0,n.jsxs)(n.Fragment,{children:[`반사 하나: 거리 `,(0,n.jsx)(t,{children:`r`}),`, 채널 고도각 `,(0,n.jsx)(t,{children:String.raw`\alpha`}),`, 헤드 방위각 `,(0,n.jsx)(t,{children:String.raw`\theta`}),`, 시각 `,(0,n.jsx)(t,{children:String.raw`t_j`}),`.`]})},{title:`좌표계 L의 점`,text:(0,n.jsxs)(n.Fragment,{children:[`구면 좌표를 직교 좌표로 바꿉니다. 결과는 시각 `,(0,n.jsx)(t,{children:String.raw`t_j`}),`의 LiDAR 좌표계에서 미터 단위입니다.`]}),tex:String.raw`p_L = r\,[\cos\alpha\cos\theta,\ \cos\alpha\sin\theta,\ \sin\alpha]^\top`},{title:`자이로 모델`,text:(0,n.jsxs)(n.Fragment,{children:[`실제 몸체 각속도 `,(0,n.jsx)(t,{children:String.raw`\omega`}),`에 바이어스와 잡음이 더해집니다.`]}),tex:String.raw`\omega_m = \omega + b_g + n_g`},{title:`가속도계 모델`,text:(0,n.jsxs)(n.Fragment,{children:[`월드 가속도에서 중력을 빼고 `,(0,n.jsx)(t,{children:String.raw`R^\top`}),`(R = W에서의 몸체 자세)로 몸체 좌표계에 돌린 뒤 바이어스와 잡음을 더합니다.`]}),tex:String.raw`a_m = R^\top (a_W - g) + b_a + n_a`},{title:`출력`,text:(0,n.jsx)(n.Fragment,{children:`추정기로 들어가는 두 개의 타임스탬프 스트림: 스캔마다의 점군과 그 사이의 IMU 샘플.`})}],example:(0,n.jsxs)(n.Fragment,{children:[`거리 `,(0,n.jsx)(t,{children:String.raw`r = 10`}),` m, 예시 고도각 `,(0,n.jsx)(t,{children:String.raw`\alpha = 10^\circ`}),`, 방위각 `,(0,n.jsx)(t,{children:String.raw`\theta = 30^\circ`}),`인 반사는 `,(0,n.jsx)(t,{children:String.raw`p_L = 10\,(0.9848 \cdot 0.8660,\ 0.9848 \cdot 0.5,\ 0.1736) = (8.529,\ 4.924,\ 1.736)`}),` m가 됩니다. IMU의 경우, 원래 좌표계의 정지 상태 값 약 `,(0,n.jsx)(t,{children:String.raw`(1.84, -1.84, -9.43)`}),` m/s²의 크기는 `,(0,n.jsx)(t,{children:String.raw`\sqrt{1.84^2 + 1.84^2 + 9.43^2} = \sqrt{95.70} \approx 9.78`}),` m/s²로 중력에 가깝고, z 성분과 측정 벡터 사이 각은 `,(0,n.jsx)(t,{children:String.raw`\arccos(9.43/9.78) \approx 15^\circ`}),`입니다. 즉 z축은 대략 아래를 향하며 약 15° 기울어 있습니다.`]}),paper:(0,n.jsx)(n.Fragment,{children:`바이어스와 백색 잡음을 더하고 바이어스를 랜덤 워크로 두는 IMU 모델은 Forster 외(2017)를 따르며, FAST-LIO(Xu, Zhang, 2021)도 같은 형태로 씁니다. 두 문헌 모두 LiDAR를 순간 영상이 아니라 시각이 붙은 점들의 모음으로 다룹니다.`}),site:(0,n.jsx)(n.Fragment,{children:`스캔 그림은 예시입니다. 빔 하나가 2D 방을 훑고 시각별로 색을 입힌 것이며 XT16 기록이 아닙니다. 플레이그라운드의 LiDAR는 2D, 기본 180개 빔, 순간 측정, 가우시안 거리 잡음이며, 16개 링도 반사 강도도 없습니다. 플레이그라운드의 오도메트리가 IMU 역할을 대신하며, 자이로 바이어스를 설정할 수 있습니다.`}),dataset:(0,n.jsxs)(n.Fragment,{children:[`LiDAR 토픽은 `,(0,n.jsx)(`code`,{children:`/lidar_points`}),`이고 FAST-LIO는 `,(0,n.jsx)(`code`,{children:`/utlidar/imu_corrected`}),`를 씁니다. 튜닝 기록 하나(층 미상, 데이터셋에 포함되지 않음)에서 `,(0,n.jsx)(`code`,{children:`/lidar_points`}),`는 약 6 Hz, IMU는 약 248 Hz로 들어왔습니다. 이 값은 데이터셋 메타데이터가 아닙니다. 위 정지 상태 값은 그 기록의 처음 400개 샘플의 중앙값입니다. 설정의 잡음 값은 `,(0,n.jsx)(`code`,{children:`acc_cov 0.3`}),`, `,(0,n.jsx)(`code`,{children:`gyr_cov 0.03`}),`, `,(0,n.jsx)(`code`,{children:`b_acc_cov 1e-4`}),`, `,(0,n.jsx)(`code`,{children:`b_gyr_cov 1e-5`}),`입니다. 공개한 FAST-LIO 지도는 x y z만 저장하므로, 공개 데이터에서 원시 점별 시각을 확인할 수 없습니다.`]}),interactiveLink:(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(`em`,{children:`스캔 안의 시각`}),`은 방위각 `,(0,n.jsx)(t,{children:String.raw`\theta`}),`, 따라서 `,(0,n.jsx)(t,{children:String.raw`t_j`}),`를 움직입니다. 그려진 점 하나하나가 자기 시각의 `,(0,n.jsx)(t,{children:String.raw`p_L`}),`입니다. IMU 패널은 정지 상태의 `,(0,n.jsx)(t,{children:String.raw`a_m`}),`를 보여 주며, 그 값은 `,(0,n.jsx)(t,{children:String.raw`-R^\top g`}),`가 지배합니다.`]}),check:{q:`이상적인 IMU(바이어스·잡음 없음)가 자유 낙하하고 있습니다. 가속도계는 무엇을 읽을까요?`,options:[`수직축에 9.81 m/s²`,`모든 축에서 0`,`수직축에 −9.81 m/s²`,`장착 방향에 따라 다르다`],answer:1,explain:(0,n.jsxs)(n.Fragment,{children:[`자유 낙하에서는 `,(0,n.jsx)(t,{children:String.raw`a_W = g`}),`이므로 `,(0,n.jsx)(t,{children:String.raw`a_m = R^\top (g - g) = 0`}),`입니다. 비력이 사라지며, 가속도계가 무중력을 “느끼는” 이유가 이것입니다.`]})}}},{beginner:{question:(0,n.jsx)(n.Fragment,{children:`LiDAR가 측정한 점은 어떻게 지도의 올바른 자리에 놓일까요?`}),analogy:(0,n.jsx)(n.Fragment,{children:`“내 왼쪽으로 두 걸음” 같은 안내는 내가 어디에 서서 어느 쪽을 보는지 알아야 의미가 있습니다. 점을 LiDAR에서 IMU로, 다시 지도로 옮기는 일은 두 사람을 거쳐 길 안내를 전하는 것과 비슷합니다. 첫 번째 사람은 자기 기준의 왼쪽·오른쪽을 두 번째 사람 기준으로 바꾸고, 두 번째 사람은 그것을 거리 지도로 바꿉니다. 비유가 깨지는 지점도 있습니다. 3D 회전은 “위”를 “아래”로 바꿀 수도 있는데, 길을 알려 주는 사람은 그런 일을 하지 않습니다.`}),story:[(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(`strong`,{children:`좌표계`}),`는 원점 하나와 축 세 개(x, y, z)입니다. 여기서는 좌표계 세 개가 중요합니다. 점을 측정하는 LiDAR 좌표계 `,(0,n.jsx)(`strong`,{children:`L`}),`, FAST-LIO가 움직임을 추정하는 몸체인 IMU 좌표계 `,(0,n.jsx)(`strong`,{children:`I`}),`, 그리고 주행 시작에 고정되어 지도가 놓이는 월드 좌표계 `,(0,n.jsx)(`strong`,{children:`W`}),`입니다.`]}),(0,n.jsxs)(n.Fragment,{children:[`점을 한 좌표계에서 다른 좌표계로 옮기려면 `,(0,n.jsx)(`strong`,{children:`변환`}),`, 곧 회전과 그 뒤의 병진이 필요합니다. L에서 I로 가는 변환은 설정으로 고정되어 있으며 `,(0,n.jsx)(`strong`,{children:`외부 파라미터`}),`(extrinsic)라고 부릅니다. 여기서는 x축을 기준으로 180° 회전하고, 좌표계 I에서 원점을 앞으로 약 17 cm, 아래로 약 9 cm 옮깁니다. I에서 W로 가는 변환은 로봇의 추정 포즈이며 매 순간 바뀝니다.`]}),(0,n.jsx)(n.Fragment,{children:`방향이 중요합니다. “L에서 I로”의 변환은 “I에서 L로”의 역입니다. 하나를 써야 할 곳에 다른 하나를 쓰면 지도 전체가 거울상이 되거나 돌아갑니다. 부호 규약도 혼란을 더합니다. 이 데이터의 원래 IMU 좌표계는 z가 대략 아래를 향하므로, 소프트웨어는 두 축의 부호를 바꿔(역시 x축 기준 180° 회전) FAST-LIO에 z가 대략 위를 향하는 좌표계를 넘깁니다.`}),(0,n.jsx)(n.Fragment,{children:`솔직한 한계도 있습니다. 이 숫자들은 설정이 말하는 내용일 뿐, 센서가 실제로 어디에 달려 있는지를 말하지 않습니다. 기계 도면이나 캘리브레이션 보고서는 데이터셋에 없고, 외부 파라미터는 추정하지 않고 고정되어 있습니다.`}),(0,n.jsx)(n.Fragment,{children:`두 변환을 올바르게 적용하면 모든 스캔이 하나의 일관된 좌표계에 놓입니다. 부호나 방향이 틀리면 지도가 곧바로 거울상이 되거나, 기울거나, 뒤집혀 보입니다.`})],tryIt:(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(`em`,{children:`LiDAR 좌표계의 점 x/y/z`}),`를 움직이며 좌표계 I의 좌표를 보세요. x는 그대로이고 y와 z는 부호가 바뀌며, 설정된 오프셋이 더해집니다. 다음으로 `,(0,n.jsx)(`em`,{children:`예시 로봇 요(yaw)`}),`와 `,(0,n.jsx)(`em`,{children:`예시 로봇 x/y`}),`를 바꿔 보세요. 외부 파라미터는 고정이므로 월드 좌표만 바뀝니다. “헷갈리기 쉬운 다섯 가지” 패널을 읽고 각 숫자가 어느 층에 속하는지 확인하세요.`]}),misconception:(0,n.jsx)(n.Fragment,{children:`“지도가 뒤집혀 보이면 부호를 바꾸면 된다.” 그렇게 하면 오류를 찾는 대신 감추게 됩니다. 먼저 지도가 어느 좌표계에 있고 각 변환이 어느 방향인지 확인하세요. 엉뚱한 곳에서 부호를 바꾸면 그 뒤의 모든 것이 거울상이 됩니다.`}),summary:[(0,n.jsx)(n.Fragment,{children:`점은 LiDAR 좌표계에서 측정되고, 움직임은 IMU 좌표계에 대해 추정되며, 지도는 월드 좌표계에 놓입니다.`}),(0,n.jsx)(n.Fragment,{children:`고정된 외부 파라미터는 점을 L에서 I로, 추정 포즈는 I에서 W로 옮깁니다.`}),(0,n.jsx)(n.Fragment,{children:`설정된 외부 파라미터는 검증된 실제 장착 배치가 아니며, 변환의 방향을 바꾸면 지도가 거울상이 됩니다.`})]},advanced:{objectives:[(0,n.jsxs)(n.Fragment,{children:[`첨자 순서를 일관되게 지키며(`,(0,n.jsx)(t,{children:String.raw`T_{AB}`}),`는 B 좌표를 A 좌표로 옮김) SE(3) 강체 변환을 적용하고 역변환합니다.`]}),(0,n.jsx)(n.Fragment,{children:`이 데이터셋의 다섯 층, 곧 실제 장착, 센서의 원래 좌표계, 코드의 축 변환, FAST-LIO 좌표계 I, 설정된 외부 파라미터를 추적합니다.`}),(0,n.jsx)(n.Fragment,{children:`회전 행렬이 진회전(det = +1)인지 확인하고 거울 변환을 알아봅니다.`})],model:[[`좌표계`,(0,n.jsxs)(n.Fragment,{children:[`L: `,(0,n.jsx)(`code`,{children:`/lidar_points`}),`의 XT16 좌표계. 원래 IMU 좌표계 `,(0,n.jsx)(`code`,{children:`utlidar_imu`}),`. I: 축 변환 뒤의 FAST-LIO 입력 좌표계. W: 시작 시점에 고정한 FAST-LIO 월드.`]})],[`외부 파라미터`,(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(`code`,{children:`hesaixt16.yaml`}),`의 `,(0,n.jsx)(t,{children:String.raw`R_{IL} = \mathrm{diag}(1,-1,-1)`}),`, `,(0,n.jsx)(t,{children:String.raw`t_{IL} = (0.171,\ 0,\ -0.0908)`}),` m: 좌표계 I에서 본 LiDAR 원점. 고정값(`,(0,n.jsx)(`code`,{children:`extrinsic_est_en: false`}),`)이며, 출처는 기록되어 있지 않습니다.`]})],[`축 변환`,(0,n.jsxs)(n.Fragment,{children:[`코드는 IMU 콜백에서 자이로와 가속도에 `,(0,n.jsx)(`code`,{children:`imu_*_axis_sign [1, −1, −1]`}),`을 곱하며, 이는 x축 기준 180° 회전입니다. 원래 정지 상태 값 ≈ (1.84, −1.84, −9.43) m/s²(z 대략 아래)는 ≈ (1.84, 1.84, +9.43) m/s²(z 대략 위)가 됩니다.`]})],[`상태`,(0,n.jsxs)(n.Fragment,{children:[`추정기는 LiDAR나 로봇 몸체가 아니라 좌표계 I의 `,(0,n.jsx)(t,{children:String.raw`T_{WI} = (R_{WI}, p_{WI})`}),`를 내놓습니다.`]})],[`가정`,(0,n.jsxs)(n.Fragment,{children:[`외부 파라미터가 일정하고 정확하다고 가정합니다. 실제 장착과 대조해 검증하지 않았습니다. 기록의 정적 TF 트리에는 `,(0,n.jsx)(`code`,{children:`base_link → hesai_lidar`}),`는 있지만 `,(0,n.jsx)(`code`,{children:`utlidar_imu`}),`로 가는 변환은 없습니다.`]})]],steps:[{title:`입력`,text:(0,n.jsxs)(n.Fragment,{children:[`점 `,(0,n.jsx)(t,{children:String.raw`p_L`}),`(m, 좌표계 L), 외부 파라미터, 추정 포즈 `,(0,n.jsx)(t,{children:String.raw`T_{WI}`}),`.`]})},{title:`L → I`,text:(0,n.jsx)(n.Fragment,{children:`회전한 뒤, I에서 표현한 LiDAR 원점을 더합니다.`}),tex:String.raw`p_I = R_{IL}\,p_L + t_{IL}`},{title:`I → W`,text:(0,n.jsx)(n.Fragment,{children:`좌표계 I의 추정 포즈를 적용합니다.`}),tex:String.raw`p_W = R_{WI}\,p_I + p_{WI}`},{title:`합성`,text:(0,n.jsx)(n.Fragment,{children:`동차 행렬을 한 번 곱해도 같습니다. 안쪽 첨자가 맞아야 합니다.`}),tex:String.raw`T_{WL} = T_{WI}\,T_{IL},\qquad T = \begin{bmatrix} R & t \\ 0 & 1 \end{bmatrix}`},{title:`역변환`,text:(0,n.jsx)(n.Fragment,{children:`되돌아갈 때는 병진을 먼저 빼고, 그다음 회전을 되돌립니다.`}),tex:String.raw`T^{-1} = \begin{bmatrix} R^\top & -R^\top t \\ 0 & 1 \end{bmatrix},\qquad p_L = R_{IL}^\top (p_I - t_{IL})`},{title:`출력`,text:(0,n.jsx)(n.Fragment,{children:`지도에 넣을 준비가 된 W의 점.`})}],example:(0,n.jsxs)(n.Fragment,{children:[`인터랙티브의 기본 점 `,(0,n.jsx)(t,{children:String.raw`p_L = (4, 1.5, 0.5)`}),` m를 씁시다. `,(0,n.jsx)(t,{children:String.raw`R_{IL}p_L = (4, -1.5, -0.5)`}),`, 따라서 `,(0,n.jsx)(t,{children:String.raw`p_I = (4.171, -1.5, -0.591)`}),` m입니다. 예시 포즈 요 30°, `,(0,n.jsx)(t,{children:String.raw`p_{WI} = (2, -1, 0)`}),` m로: `,(0,n.jsx)(t,{children:String.raw`x = 4.171 \cdot 0.8660 - (-1.5) \cdot 0.5 + 2 = 6.362`}),`, `,(0,n.jsx)(t,{children:String.raw`y = 4.171 \cdot 0.5 + (-1.5) \cdot 0.8660 - 1 = -0.214`}),`, `,(0,n.jsx)(t,{children:String.raw`z = -0.591`}),` m. 역변환하면 `,(0,n.jsx)(t,{children:String.raw`R_{IL}^\top\big((4.171, -1.5, -0.591) - t_{IL}\big) = \mathrm{diag}(1,-1,-1)(4, -1.5, -0.5) = (4, 1.5, 0.5)`}),` m로 원래 점이 나옵니다. 또 `,(0,n.jsx)(t,{children:String.raw`\det R_{IL} = 1 \cdot (-1) \cdot (-1) = +1`}),`이므로 거울 변환이 아닌 진회전입니다.`]}),paper:(0,n.jsxs)(n.Fragment,{children:[`FAST-LIO2는 상태를 IMU 좌표계에 대해 정의하고, LiDAR 점을 LiDAR→IMU 외부 파라미터로 옮기며, 이 외부 파라미터를 선택적으로 온라인 추정할 수 있습니다. README는 `,(0,n.jsx)(`code`,{children:`extrinsic_R`}),`와 `,(0,n.jsx)(`code`,{children:`extrinsic_T`}),`를 IMU 좌표계에서 본 LiDAR 포즈로 설명하며, 이는 여기의 `,(0,n.jsx)(t,{children:String.raw`(R_{IL}, t_{IL})`}),`와 같습니다.`]}),site:(0,n.jsx)(n.Fragment,{children:`인터랙티브는 설정된 외부 파라미터를 그대로 쓰고, 요만 있는 자유 예시 포즈(평면 주행)를 씁니다. 그림은 좌표계 I의 좌표로 그렸으며 실제 장착 그림이 아닙니다. 플레이그라운드는 2D이고 외부 파라미터가 없으며, LiDAR가 로봇 중심에 있습니다.`}),dataset:(0,n.jsxs)(n.Fragment,{children:[`위의 모든 숫자는 코드와 그 설정, 또는 튜닝 기록 하나(층 미상, 데이터셋에 포함되지 않음)에서 나왔습니다. 실제 장착 배치는 `,(0,n.jsx)(`strong`,{children:`검증되지 않았습니다`}),`. 외부 파라미터를 어떻게 구했는지는 기록되어 있지 않으며, 설정 주석은 원래 FAST-LIO의 Hesai 설정을 따른다고 적고 있습니다. 처리 노트에는 원시 FAST-LIO 월드가 공개 좌표계에 대해 거울상이라고 기록되어 있어, FAST-LIO 층들은 “바닥 z = 0, +z 위, 거울상 없음”으로 변환했습니다. 4F는 LIO-SAM 월드에 있습니다. 층끼리는 서로 정합되어 있지 않습니다.`]}),interactiveLink:(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(`em`,{children:`점 x/y/z`}),`는 `,(0,n.jsx)(t,{children:String.raw`p_L`}),`를 정하고, 좌표계 I의 값은 `,(0,n.jsx)(t,{children:String.raw`R_{IL}p_L + t_{IL}`}),`입니다. `,(0,n.jsx)(`em`,{children:`예시 로봇 요`}),`는 `,(0,n.jsx)(t,{children:String.raw`R_{WI}`}),`(z축 회전)를, `,(0,n.jsx)(`em`,{children:`예시 로봇 x/y`}),`는 `,(0,n.jsx)(t,{children:String.raw`p_{WI}`}),`를 정하며, 월드 값만 이들에 따라 바뀝니다.`]}),check:{q:`p_I가 주어졌을 때 LiDAR 좌표계의 점을 되찾는 식은 무엇일까요?`,options:[`R_IL p_I − t_IL`,`R_ILᵀ (p_I − t_IL)`,`R_ILᵀ p_I − t_IL`,`R_IL (p_I + t_IL)`],answer:1,explain:(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t,{children:String.raw`p_I = R_{IL}p_L + t_{IL}`}),`를 거꾸로 풀면 좌표계 I에서 병진을 먼저 빼고, 그다음 회전을 되돌립니다. 여기서는 `,(0,n.jsx)(t,{children:String.raw`R_{IL}^\top = R_{IL}`}),`이지만, 회전한 뒤 `,(0,n.jsx)(t,{children:String.raw`t_{IL}`}),`를 빼면 다른 좌표계에서 빼는 셈이라 오프셋의 y, z 부호가 틀립니다.`]})}}},{beginner:{question:(0,n.jsx)(n.Fragment,{children:`IMU가 모든 움직임을 측정한다면, 로봇은 왜 그 움직임을 더하기만 해서 자기 위치를 알 수 없을까요?`}),analogy:(0,n.jsx)(n.Fragment,{children:`눈을 감고 직선으로 걸으면 처음에 아주 조금 어긋나고, 걸음마다 오차가 커집니다. IMU는 더 나쁩니다. 측정한 회전에 작은 오차가 있으면 로봇은 자신이 기울었다고 믿게 되고, 그러면 중력의 일부가 옆 방향 가속처럼 보여 오차가 눈덩이처럼 불어납니다. 이 비유도 실제보다 순합니다. 걸음 오차는 대략 거리에 비례하지만, IMU의 위치 오차는 시간의 제곱이나 세제곱으로 커집니다.`}),story:[(0,n.jsxs)(n.Fragment,{children:[`측정한 움직임을 더해 위치를 추정하는 것을 `,(0,n.jsx)(`strong`,{children:`추측 항법`}),`(dead reckoning)이라 합니다. IMU로는 적분을 세 번 합니다. 자이로의 각속도를 시간에 따라 더하면 자세가 나옵니다. 가속도계의 비력을 월드로 돌리고 중력을 다시 더하면 가속도가 나오며, 한 번 더하면 속도, 또 한 번 더하면 위치가 됩니다.`]}),(0,n.jsxs)(n.Fragment,{children:[`모든 IMU 값에는 작은 일정한 치우침, 곧 `,(0,n.jsx)(`strong`,{children:`바이어스`}),`가 있습니다. 가속도계 바이어스 0.05 m/s²는 아주 작지만, 두 번 적분하면 ½·0.05·t²의 위치 오차가 됩니다. 1초 뒤 2.5 cm, 10초 뒤 2.5 m, 1분 뒤에는 90 m입니다.`]}),(0,n.jsx)(n.Fragment,{children:`자이로 바이어스는 더 나쁩니다. 추정 자세가 서서히 기울게 만들기 때문입니다. 기울어진 추정은 중력 9.81 m/s²의 일부를 수평 방향으로 투영하고, 이렇게 새어 나온 가속이 다시 두 번 적분됩니다. 그러면 위치 오차는 시간의 세제곱으로 커집니다. 바이어스가 0.1°/s이면 1초 뒤 약 3 mm, 10초 뒤 약 2.9 m, 1분 뒤에는 600 m가 넘습니다.`}),(0,n.jsx)(n.Fragment,{children:`그래서 IMU 적분은 정확한 짧은 구간, 곧 두 LiDAR 스캔 사이에만 씁니다. 그다음 LiDAR가 벽을 기준으로 추정값을 보정하고, 추정기는 바이어스 자체도 학습해 앞으로의 값에서 뺄 수 있게 합니다.`})],tryIt:(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(`em`,{children:`자이로 바이어스 오차`}),`를 0으로 두고 `,(0,n.jsx)(`em`,{children:`가속도계 바이어스 오차`}),`를 올려 보세요. 곡선은 포물선이며, 1초·10초·60초 뒤의 값은 100배, 36배씩 커집니다. 그다음 자이로 바이어스를 더하면, 시간의 세제곱으로 커지는 그 곡선이 시간이 길어질수록 가속도계 곡선을 앞지르는 모습을 볼 수 있습니다.`]}),misconception:(0,n.jsx)(n.Fragment,{children:`“더 좋은 IMU를 쓰면 LiDAR가 필요 없다.” 더 좋은 IMU는 바이어스가 작아 드리프트를 늦출 뿐 멈추지는 못합니다. 일정한 바이어스가 조금이라도 있으면 위치 오차는 한없이 커집니다.`}),summary:[(0,n.jsx)(n.Fragment,{children:`IMU는 측정값을 적분해야만 자세, 속도, 위치를 줍니다.`}),(0,n.jsx)(n.Fragment,{children:`일정한 가속도계 바이어스는 t² 위치 오차로, 자이로 바이어스는 새어 나온 중력을 통해 t³ 오차로 커집니다.`}),(0,n.jsx)(n.Fragment,{children:`그래서 IMU 적분은 LiDAR 스캔 사이에서만 믿고, LiDAR가 이를 보정하며 바이어스 추정을 돕습니다.`})]},advanced:{objectives:[(0,n.jsx)(n.Fragment,{children:`자세, 속도, 위치에 대한 이산 스트랩다운 적분을 씁니다.`}),(0,n.jsx)(n.Fragment,{children:`일정한 바이어스로부터 t²와 t³ 오차 증가를 유도하고 주어진 값으로 계산합니다.`}),(0,n.jsx)(n.Fragment,{children:`바이어스가 추정 상태에 들어가야 하는 이유를 설명합니다.`})],model:[[`상태`,(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t,{children:String.raw`R_k \in SO(3)`}),`(몸체→월드), `,(0,n.jsx)(t,{children:String.raw`v_k, p_k \in \mathbb{R}^3`}),`(m/s, m, 월드 좌표계), 바이어스 `,(0,n.jsx)(t,{children:String.raw`b_g`}),`(rad/s), `,(0,n.jsx)(t,{children:String.raw`b_a`}),`(m/s², 몸체 좌표계).`]})],[`입력`,(0,n.jsxs)(n.Fragment,{children:[`간격 `,(0,n.jsx)(t,{children:String.raw`\Delta t`}),`의 IMU 샘플 `,(0,n.jsx)(t,{children:String.raw`\omega_m, a_m`}),`, 측정 모델은 1강과 같습니다.`]})],[`가정`,(0,n.jsxs)(n.Fragment,{children:[`샘플 하나 동안 값이 일정; 평평하고 자전하지 않는 지구; W에서 중력 `,(0,n.jsx)(t,{children:String.raw`g = (0,0,-9.81)`}),` m/s².`]})],[`오차 모델`,(0,n.jsxs)(n.Fragment,{children:[`바이어스 추정 오차 `,(0,n.jsx)(t,{children:String.raw`\delta b_a, \delta b_g`}),`는 구간 동안 일정; 잡음 무시. 기울기에는 소각 근사.`]})]],steps:[{title:`입력`,text:(0,n.jsxs)(n.Fragment,{children:[`이전 상태 `,(0,n.jsx)(t,{children:String.raw`(R_k, v_k, p_k)`}),`, 바이어스 추정값, IMU 샘플 하나.`]})},{title:`자세`,text:(0,n.jsxs)(n.Fragment,{children:[`바이어스를 뺀 각속도로 한 간격만큼 회전합니다. `,(0,n.jsx)(t,{children:String.raw`\mathrm{Exp}`}),`는 회전 벡터(rad)를 회전 행렬로 바꿉니다.`]}),tex:String.raw`R_{k+1} = R_k\,\mathrm{Exp}\big((\omega_m - b_g)\,\Delta t\big)`},{title:`속도와 위치`,text:(0,n.jsx)(n.Fragment,{children:`바이어스를 뺀 비력을 W로 돌리고 중력을 더해 월드 가속도를 얻습니다.`}),tex:String.raw`v_{k+1} = v_k + \big(R_k(a_m - b_a) + g\big)\Delta t,\quad p_{k+1} = p_k + v_k\Delta t + \tfrac12\big(R_k(a_m - b_a) + g\big)\Delta t^2`},{title:`가속도계 바이어스 오차`,text:(0,n.jsx)(n.Fragment,{children:`일정한 잔여 바이어스가 두 번 적분됩니다.`}),tex:String.raw`e_p(t) \approx \tfrac12\,\delta b_a\,t^2`},{title:`자이로 바이어스 오차`,text:(0,n.jsxs)(n.Fragment,{children:[`기울기는 `,(0,n.jsx)(t,{children:String.raw`\delta\theta = \delta b_g t`}),`로 커지고, 새어 나온 수평 가속은 `,(0,n.jsx)(t,{children:String.raw`\lVert g\rVert \delta b_g t`}),`입니다. 이를 두 번 적분하면 세제곱 법칙이 나옵니다.`]}),tex:String.raw`e_p(t) \approx \int_0^t\!\!\int_0^s \lVert g\rVert\,\delta b_g\,u\,du\,ds = \tfrac16\,\lVert g\rVert\,\delta b_g\,t^3`},{title:`출력`,text:(0,n.jsx)(n.Fragment,{children:`1초 미만에서는 정확하지만 몇 분이면 오차가 한없이 커지는 추측 항법 궤적.`})}],example:(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t,{children:String.raw`\delta b_a = 0.05`}),` m/s²이면 `,(0,n.jsx)(t,{children:String.raw`e_p = 0.025 t^2`}),`, 즉 1초에 0.025 m, 10초에 2.5 m, 60초에 90 m입니다. `,(0,n.jsx)(t,{children:String.raw`\delta b_g = 0.1^\circ/\mathrm{s} = 0.001745`}),` rad/s이면 `,(0,n.jsx)(t,{children:String.raw`e_p = 9.81 \times 0.001745 / 6 \cdot t^3 = 0.002854\,t^3`}),`, 즉 1초에 2.9 mm, 10초에 2.85 m, 60초에 616 m입니다(이때 기울기는 6°로, 소각 근사의 한계에 가깝습니다). 두 곡선은 `,(0,n.jsx)(t,{children:String.raw`0.025t^2 = 0.002854t^3`}),`, 곧 `,(0,n.jsx)(t,{children:String.raw`t \approx 8.8`}),`초에서 만납니다.`]}),paper:(0,n.jsx)(n.Fragment,{children:`Forster 외(2017)는 다양체 위의 적분과 바이어스 랜덤 워크 모델을 제시합니다. FAST-LIO(Xu, Zhang, 2021)는 같은 운동학을 프로세스 모델로 쓰고 두 바이어스를 필터 안에서 추정합니다. LIO-SAM(Shan 외, 2020)은 키프레임 사이의 IMU 샘플을 사전 적분하고 바이어스를 팩터 그래프에서 추정합니다.`}),site:(0,n.jsxs)(n.Fragment,{children:[`드리프트 그림은 `,(0,n.jsx)(t,{children:String.raw`\lVert g\rVert = 9.81`}),` m/s²로 위 두 닫힌 형태의 오차 법칙을 그린 것이며, 잡음, 바이어스 변화, 지구 자전이 없습니다. 플레이그라운드의 2D 추측 항법은 잡음 섞인 오도메트리를 중점 적분하고 자이로 바이어스를 설정할 수 있어, 시간에 비례하는 방향 드리프트가 위치 오차로 바뀌는 모습을 보여 줍니다.`]}),dataset:(0,n.jsx)(n.Fragment,{children:`데이터셋에는 IMU만으로 만든 궤적이 없습니다. LiDAR로 보정해도 오도메트리에는 오차가 쌓입니다. 같은 4F 주행에서 FAST-LIO 궤적은 시작점에서 27.77 m, LIO-SAM 궤적은 0.317 m 떨어진 곳에서 끝났습니다. 이 차이를 한 가지 원인으로 돌리지 않으며, 두 파이프라인의 정확도를 비교한다고 주장하지 않습니다. 이 페이지의 바이어스 값은 합성 값이며 Go2에서 측정한 것이 아닙니다.`}),interactiveLink:(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(`em`,{children:`가속도계 바이어스 오차`}),`는 t² 법칙의 `,(0,n.jsx)(t,{children:String.raw`\delta b_a`}),`이고, `,(0,n.jsx)(`em`,{children:`자이로 바이어스 오차`}),`는 t³ 법칙의 `,(0,n.jsx)(t,{children:String.raw`\delta b_g`}),`입니다(°/s로 입력하고 rad/s로 환산). 표시 값은 두 법칙을 1초, 10초, 60초에서 계산한 것입니다.`]}),check:{q:`시간 구간이 10초에서 20초로 두 배가 되면, 자이로 바이어스로 인한 위치 오차는 몇 배가 될까요?`,options:[`2`,`4`,`8`,`16`],answer:2,explain:(0,n.jsxs)(n.Fragment,{children:[`오차가 `,(0,n.jsx)(t,{children:String.raw`t^3`}),`에 비례하므로 `,(0,n.jsx)(t,{children:String.raw`2^3 = 8`}),`배입니다. 가속도계 바이어스 오차는 `,(0,n.jsx)(t,{children:String.raw`2^2 = 4`}),`배가 됩니다.`]})}}},{beginner:{question:(0,n.jsx)(n.Fragment,{children:`움직이는 LiDAR는 왜 곧은 벽을 휘거나 비틀린 모양으로 그리며, 이를 어떻게 바로잡을까요?`}),analogy:(0,n.jsx)(n.Fragment,{children:`걸으면서 찍은 파노라마 사진을 떠올려 보세요. 카메라가 왼쪽에서 오른쪽으로 훑는 동안 내가 움직였기 때문에 양 끝이 맞지 않고 곧은 울타리가 꺾여 보입니다. 왜곡 보정은 훑는 동안 내가 어떻게 움직였는지 정확히 알고, 조각마다 한 자리에서 찍은 것처럼 다시 그리는 일과 같습니다. 사진과 달리 LiDAR의 왜곡은 3차원이고 거리에 따라 커집니다.`}),story:[(0,n.jsxs)(n.Fragment,{children:[`XT16은 돌면서 측정합니다. 한 바퀴, 곧 한 `,(0,n.jsx)(`strong`,{children:`스윕`}),`은 1초보다 짧지만, 점마다 그 안의 서로 다른 순간에 측정됩니다. 로봇이 가만히 서 있으면 상관없습니다. 하지만 스윕 동안 로봇이 걷거나 돌면, 이른 점과 늦은 점은 서로 다른 위치에서 측정됩니다.`]}),(0,n.jsxs)(n.Fragment,{children:[`그 결과가 `,(0,n.jsx)(`strong`,{children:`왜곡된 스캔`}),`입니다. 0.1초 스윕 동안 초당 30°로 돌면 로봇은 3° 돕니다. 그러면 스윕 시작에 측정한 10 m 거리의 벽 점은 스윕 끝에 측정했을 자리에서 약 0.5 m 벗어납니다. 이 오차는 거리가 멀수록, 로봇이 빨리 돌수록 커집니다.`]}),(0,n.jsxs)(n.Fragment,{children:[`바로잡으려면 스윕 동안의 움직임을 알아야 합니다. IMU가 그것을 높은 빈도로 알려 주므로, 점마다 그 측정 시각의 포즈를 계산할 수 있습니다. `,(0,n.jsx)(`strong`,{children:`왜곡 보정`}),`(deskew, 움직임 보상)은 모든 점을 스윕 끝 같은 하나의 공통 기준 시각의 센서 좌표계로 옮깁니다.`]}),(0,n.jsx)(n.Fragment,{children:`보정 뒤에는 벽이 다시 곧아지고, 스윕의 모든 점이 하나의 포즈를 공유합니다. 다음 단계인 스캔-지도 정합에는 이것이 필요합니다. 왜곡 보정은 정확한 점별 시각과 LiDAR–IMU 사이의 시간 오프셋에 의존합니다. 움직임 추정이 틀리면 보정이 오차를 없애는 대신 더합니다.`})],tryIt:(0,n.jsxs)(n.Fragment,{children:[`회전 속도를 주고 벽까지 거리를 멀리 둔 다음 `,(0,n.jsx)(`em`,{children:`스캔 안의 시각`}),`을 끌어 보세요. 스윕이 진행될수록 원시 점이 실제 벽에서 멀어집니다. `,(0,n.jsx)(`em`,{children:`왜곡 보정 적용`}),`을 켜면 점이 벽으로 돌아옵니다. `,(0,n.jsx)(`em`,{children:`기준 시각`}),`을 “스캔 시작”과 “스캔 끝”으로 바꿔 비교해 보세요. 보정된 벽은 같지만, 가장 많이 옮겨지는 점이 스윕의 한쪽 끝에서 다른 쪽 끝으로 바뀝니다.`]}),misconception:(0,n.jsx)(n.Fragment,{children:`“왜곡 보정은 선을 곧게 펴는 영상 필터다.” 왜곡 보정은 추정한 움직임으로 계산하는 기하 변환입니다. 곧은 선을 찾지도 않으며, 움직임 추정이 틀리면 스캔을 더 나쁘게 만듭니다.`}),summary:[(0,n.jsx)(n.Fragment,{children:`LiDAR 스윕에는 시간이 걸리므로, 움직이는 로봇은 이른 점과 늦은 점을 서로 다른 포즈에서 측정합니다.`}),(0,n.jsx)(n.Fragment,{children:`왜곡은 거리, 회전 속도, 스윕 안의 시각 차이에 따라 커집니다.`}),(0,n.jsx)(n.Fragment,{children:`왜곡 보정은 IMU 움직임으로 모든 점을 하나의 기준 시각으로 옮기며, 정합에 이것이 필요합니다.`})]},advanced:{objectives:[(0,n.jsxs)(n.Fragment,{children:[`시각 `,(0,n.jsx)(t,{children:String.raw`t_j`}),`에 측정한 점을 `,(0,n.jsx)(t,{children:String.raw`t_{\mathrm{ref}}`}),`의 좌표계로 옮기는 왜곡 보정 변환을 씁니다.`]}),(0,n.jsx)(n.Fragment,{children:`거리, 회전 속도, 시각 차이로 왜곡의 크기를 추정합니다.`}),(0,n.jsx)(n.Fragment,{children:`왜곡 보정이 의존하는 입력과 각각이 실패하는 방식을 말합니다.`})],model:[[`입력`,(0,n.jsxs)(n.Fragment,{children:[`점 `,(0,n.jsx)(t,{children:String.raw`p_j`}),`(m, 시각 `,(0,n.jsx)(t,{children:String.raw`t_j`}),`의 LiDAR 좌표계), `,(0,n.jsx)(t,{children:String.raw`t_j \in [t_s, t_e]`}),`(스윕 시작과 끝).`]})],[`움직임`,(0,n.jsxs)(n.Fragment,{children:[`스윕 안의 모든 `,(0,n.jsx)(t,{children:String.raw`t`}),`에 대해 고정 좌표계에서의 센서 포즈 `,(0,n.jsx)(t,{children:String.raw`T(t) \in SE(3)`}),`, IMU 전파로부터 보간.`]})],[`가정`,(0,n.jsx)(n.Fragment,{children:`점별 타임스탬프가 정확하고, LiDAR–IMU 시간 오프셋을 알며, 스윕 동안 장면이 정적입니다.`})],[`오차 원인`,(0,n.jsx)(n.Fragment,{children:`틀린 타임스탬프, 틀린 시간 오프셋, 틀린 움직임. 각각 제거하려는 효과와 같은 크기의 잔여 왜곡을 만듭니다.`})]],steps:[{title:`입력`,text:(0,n.jsx)(n.Fragment,{children:`점별 시각이 있는 스윕 하나와 그 구간을 덮는 IMU 샘플.`})},{title:`정렬`,text:(0,n.jsxs)(n.Fragment,{children:[`포즈를 순서대로 계산할 수 있도록 점을 `,(0,n.jsx)(t,{children:String.raw`t_j`}),` 순으로 정렬합니다.`]})},{title:`시각별 포즈`,text:(0,n.jsxs)(n.Fragment,{children:[`스윕 동안 IMU를 전파하고 `,(0,n.jsx)(t,{children:String.raw`T(t_j)`}),`를 보간합니다.`]})},{title:`변환`,text:(0,n.jsx)(n.Fragment,{children:`각 점을 자기 시각의 센서 좌표계에서 기준 시각의 좌표계로 옮깁니다.`}),tex:String.raw`p_{\mathrm{ref}} = T(t_{\mathrm{ref}})^{-1}\,T(t_j)\,p_j`},{title:`크기 확인`,text:(0,n.jsxs)(n.Fragment,{children:[`각속도 `,(0,n.jsx)(t,{children:String.raw`\omega`}),`(rad/s)로 돌 때 거리 `,(0,n.jsx)(t,{children:`r`}),`인 점의 옆 방향 변위는 시각 차이에 대략 비례합니다. 병진이 최대 `,(0,n.jsx)(t,{children:String.raw`v\,|t_{\mathrm{ref}} - t_j|`}),`만큼 더해집니다.`]}),tex:String.raw`\Delta_\perp \approx r\,\omega\,(t_{\mathrm{ref}} - t_j)`},{title:`출력`,text:(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t,{children:String.raw`t_{\mathrm{ref}}`}),`의 한 좌표계로 표현한, 움직임이 보상된 스캔.`]})}],example:(0,n.jsxs)(n.Fragment,{children:[`인터랙티브 기본값: `,(0,n.jsx)(t,{children:String.raw`v = 1`}),` m/s, `,(0,n.jsx)(t,{children:String.raw`\omega = 30^\circ/\mathrm{s}`}),`, 스윕 0.1초, 벽 10 m. 스윕 동안 센서는 `,(0,n.jsx)(t,{children:String.raw`3^\circ = 0.0524`}),` rad 돌므로, 시작에 측정해 끝을 기준으로 옮긴 점은 회전만으로 `,(0,n.jsx)(t,{children:String.raw`10 \times 0.0524 \approx 0.52`}),` m 옮겨집니다. 병진은 빔 방향에 따라 최대 `,(0,n.jsx)(t,{children:String.raw`1 \times 0.1 = 0.1`}),` m를 더합니다. 스윕 한가운데에 측정한 점은 약 0.26 m 옮겨집니다. 스윕 한가운데를 기준으로 고르면 가장 큰 시각 차이가 0.05초로 반이 되지만, 그래도 왜곡 보정은 필요합니다.`]}),paper:(0,n.jsx)(n.Fragment,{children:`FAST-LIO(Xu, Zhang, 2021)는 IMU 역방향 전파로 움직임을 보상하고 모든 점을 스캔 끝 시각으로 표현합니다. LIO-SAM(Shan 외, 2020)도 IMU 사전 적분으로 왜곡을 보정합니다. LIO-SAM 구현의 기준 시각 세부 사항은 소스 코드를 공개 호스트에서 볼 수 없었기 때문에 여기서 검증하지 않았습니다.`}),site:(0,n.jsx)(n.Fragment,{children:`왜곡 보정 렌즈는 속도와 회전 속도가 일정하고 잡음이 없으며 벽이 곧은 상황으로 원리를 시뮬레이션합니다. 플레이그라운드의 스캔은 순간 측정이므로 왜곡 보정 단계가 없습니다.`}),dataset:(0,n.jsx)(n.Fragment,{children:`공개 지도는 왜곡 보정 뒤에 만들어졌으므로 그 효과를 끌 수 없고, 원시 XT16 스윕도 없습니다. 코드는 XT16의 점별 절대 타임스탬프를 FAST-LIO가 기대하는 밀리초 오프셋으로 바꿉니다. 두 FAST-LIO 파라미터 파일은 LiDAR–IMU 시간 오프셋이 서로 다르며(−0.025 대 0.0초), 어느 파일로 각 층을 만들었는지는 기록되어 있지 않습니다.`}),interactiveLink:(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(`em`,{children:`전진 속도`}),`와 `,(0,n.jsx)(`em`,{children:`회전 속도`}),`는 움직임 `,(0,n.jsx)(t,{children:String.raw`T(t)`}),`(`,(0,n.jsx)(t,{children:String.raw`v`}),`, `,(0,n.jsx)(t,{children:String.raw`\omega`}),`)를, `,(0,n.jsx)(`em`,{children:`스캔 시간`}),`은 `,(0,n.jsx)(t,{children:String.raw`t_e - t_s`}),`를, `,(0,n.jsx)(`em`,{children:`벽까지 거리`}),`는 `,(0,n.jsx)(t,{children:`r`}),`를 정합니다. `,(0,n.jsx)(`em`,{children:`스캔 안의 시각`}),`은 그려진 가장 늦은 `,(0,n.jsx)(t,{children:String.raw`t_j`}),`, `,(0,n.jsx)(`em`,{children:`기준 시각`}),`은 `,(0,n.jsx)(t,{children:String.raw`t_{\mathrm{ref}}`}),`이며, `,(0,n.jsx)(`em`,{children:`왜곡 보정 적용`}),`은 변환을 켭니다.`]}),check:{q:`기준 시각을 스캔 끝에서 스윕 한가운데로 옮겼습니다. 어떤 점에 적용되는 가장 큰 보정은 어떻게 될까요?`,options:[`그대로이다`,`대략 절반이 된다`,`두 배가 된다`,`0이 되어 왜곡 보정이 더는 필요 없다`],answer:1,explain:(0,n.jsxs)(n.Fragment,{children:[`가장 큰 보정은 가장 큰 시각 차이 `,(0,n.jsx)(t,{children:String.raw`|t_{\mathrm{ref}} - t_j|`}),`에 따라 정해지며, 이것이 스윕 전체 시간에서 그 절반으로 줄어듭니다. 양 끝의 점은 여전히 보정해야 합니다.`]})}}},{beginner:{question:(0,n.jsx)(n.Fragment,{children:`두 LiDAR 스캔 사이에서 FAST-LIO는 로봇이 어디에 있는지 어떻게 짐작하고, 그 짐작을 얼마나 확신할까요?`}),analogy:(0,n.jsx)(n.Fragment,{children:`육지가 보이지 않는 배의 항해사는 속력과 방향으로 해도에 위치를 표시하고, 그 둘레에 원을 그립니다. 작은 오차가 쌓이므로 원은 시간이 지날수록 커집니다. 등대가 보이면 원이 다시 작아집니다. 이 비유는 꽤 정확합니다. 다른 점은 FAST-LIO가 이 원을 1초에 수백 번, 여러 차원에서 동시에 다시 그린다는 것입니다.`}),story:[(0,n.jsxs)(n.Fragment,{children:[`FAST-LIO는 `,(0,n.jsx)(`strong`,{children:`상태`}),`를 유지합니다. 한 순간의 로봇을 설명하는 데 필요한 모든 것, 곧 자세, 위치, 속도, 두 IMU 바이어스, 중력 방향입니다. 또 `,(0,n.jsx)(`strong`,{children:`공분산`}),`도 유지합니다. 공분산은 상태의 각 부분이 얼마나 불확실한지, 그리고 그 불확실성들이 서로 어떻게 엮여 있는지를 담은 숫자 표입니다.`]}),(0,n.jsxs)(n.Fragment,{children:[`LiDAR 스캔 사이에서 FAST-LIO는 `,(0,n.jsx)(`strong`,{children:`전파`}),`(예측)를 합니다. IMU 샘플마다 3강의 운동 방정식을 적용해 상태를 시간 앞으로 밀어 갑니다. 동시에 공분산을 키웁니다. IMU 샘플마다 잡음이 섞여 있어 불확실성이 조금씩 더해지기 때문입니다.`]}),(0,n.jsxs)(n.Fragment,{children:[`자세는 주의가 필요합니다. 회전은 보통 숫자처럼 더해지지 않으므로, 필터는 세 각도를 단순한 벡터로 다루지 않고 회전들의 공간 자체(`,(0,n.jsx)(`strong`,{children:`다양체`}),`, manifold) 위에서 갱신합니다. 중력은 길이를 고정해 두고 방향만 다듬습니다.`]}),(0,n.jsxs)(n.Fragment,{children:[`이 단계의 출력은 `,(0,n.jsx)(`strong`,{children:`사전 추정`}),`(prior)입니다. 스윕 끝에서의 상태에 대한 최선의 추측과 그 불확실성, 그리고 왜곡 보정에 필요한 스윕 동안의 포즈입니다. 사전 추정은 최종 답이 아닙니다. LiDAR 갱신이 오면(9강) 스캔과 결합되고 불확실성은 다시 줄어듭니다.`]})],tryIt:(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(`em`,{children:`마지막 LiDAR 갱신 이후 시간`}),`을 끌어 보세요. 예측 포즈가 경로를 따라 움직이고 불확실성 타원이 넓어집니다. `,(0,n.jsx)(`em`,{children:`프로세스 잡음`}),`을 올리면 타원이 더 빨리 커집니다. `,(0,n.jsx)(`em`,{children:`지금 LiDAR 갱신`}),`을 누르면 시간이 초기화되고 타원이 처음의 작은 크기로 줄어듭니다.`]}),misconception:(0,n.jsx)(n.Fragment,{children:`“전파한 포즈가 곧 로봇의 포즈다.” 그것은 예측일 뿐이며 다음 갱신의 사전 추정입니다. LiDAR 스캔이 보정할 때까지 그 불확실성은 계속 커집니다.`}),summary:[(0,n.jsx)(n.Fragment,{children:`전파는 IMU 샘플마다 FAST-LIO의 상태를 앞으로 밀어 갑니다.`}),(0,n.jsx)(n.Fragment,{children:`IMU 잡음이 불확실성을 더하므로 공분산은 샘플마다 커집니다.`}),(0,n.jsx)(n.Fragment,{children:`그 결과가 스캔 끝의 사전 추정이며, LiDAR 갱신이 이를 보정합니다.`})]},advanced:{objectives:[(0,n.jsx)(n.Fragment,{children:`바이어스와 중력 성분을 포함한 FAST-LIO의 상태 벡터와 연속 프로세스 모델을 씁니다.`}),(0,n.jsx)(n.Fragment,{children:`선형화한 한 단계로 공분산을 전파하고, 전이 행렬이 불확실성을 어떻게 결합하는지 봅니다.`}),(0,n.jsx)(n.Fragment,{children:`갱신을 다양체 위의 오차 상태 형태로 정식화하는 이유를 설명합니다.`})],model:[[`상태`,(0,n.jsxs)(n.Fragment,{children:[`W에서 좌표계 I의 `,(0,n.jsx)(t,{children:String.raw`x = (R, p, v, b_g, b_a, g)`}),`. 확인한 구현은 LiDAR–IMU 외부 파라미터도 상태에 두지만, 여기서는 고정합니다.`]})],[`프로세스 모델`,(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t,{children:String.raw`\dot p = v`}),`, `,(0,n.jsx)(t,{children:String.raw`\dot R = R\lfloor \omega_m - b_g - n_g\rfloor_\wedge`}),`, `,(0,n.jsx)(t,{children:String.raw`\dot v = R(a_m - b_a - n_a) + g`}),`, 바이어스는 잡음으로만 변합니다.`]})],[`다양체`,(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t,{children:String.raw`R \in SO(3)`}),`; `,(0,n.jsx)(t,{children:`g`}),`는 2-구면 위(크기 고정). 필터는 작은 오차 상태와 `,(0,n.jsx)(t,{children:String.raw`\boxplus`}),` 연산자로 계산합니다.`]})],[`잡음`,(0,n.jsxs)(n.Fragment,{children:[`백색 잡음 `,(0,n.jsx)(t,{children:String.raw`w = (n_g, n_a, n_{b_g}, n_{b_a})`}),`, 공분산 `,(0,n.jsx)(t,{children:`Q`}),`는 `,(0,n.jsx)(`code`,{children:`gyr_cov`}),`, `,(0,n.jsx)(`code`,{children:`acc_cov`}),`, `,(0,n.jsx)(`code`,{children:`b_gyr_cov`}),`, `,(0,n.jsx)(`code`,{children:`b_acc_cov`}),`로 정합니다.`]})],[`출력`,(0,n.jsxs)(n.Fragment,{children:[`스캔 끝의 사전 추정 `,(0,n.jsx)(t,{children:String.raw`(\hat x, P)`}),`와 스윕 동안의 IMU 포즈.`]})]],steps:[{title:`입력`,text:(0,n.jsxs)(n.Fragment,{children:[`마지막으로 보정한 상태 `,(0,n.jsx)(t,{children:String.raw`\hat x`}),`, 공분산 `,(0,n.jsx)(t,{children:`P`}),`, 지난 스캔 이후의 모든 IMU 샘플.`]})},{title:`상태 적분`,text:(0,n.jsxs)(n.Fragment,{children:[`샘플 간격 `,(0,n.jsx)(t,{children:String.raw`\Delta t`}),`마다 프로세스 모델을 다양체 위에서 적용합니다.`]}),tex:String.raw`\hat x_{k+1} = \hat x_k \boxplus \big(f(\hat x_k, u_k)\,\Delta t\big)`},{title:`선형화`,text:(0,n.jsxs)(n.Fragment,{children:[`이산 모델의 오차 상태에 대한 야코비안(`,(0,n.jsx)(t,{children:String.raw`F_x`}),`)과 잡음에 대한 야코비안(`,(0,n.jsx)(t,{children:String.raw`F_w`}),`).`]})},{title:`공분산 전파`,text:(0,n.jsx)(n.Fragment,{children:`이전 불확실성을 옮기고 새 잡음을 더합니다.`}),tex:String.raw`P_{k+1} = F_x\,P_k\,F_x^\top + F_w\,Q\,F_w^\top`},{title:`포즈 저장`,text:(0,n.jsx)(n.Fragment,{children:`왜곡 보정의 역방향 전파(6강)를 위해 IMU 샘플마다 포즈를 저장합니다.`})},{title:`출력`,text:(0,n.jsx)(n.Fragment,{children:`스캔 끝의 사전 추정을 반복 갱신(9강)으로 넘깁니다.`})}],example:(0,n.jsxs)(n.Fragment,{children:[`상태 `,(0,n.jsx)(t,{children:String.raw`(p, v)`}),`만 있는 1차원 단면을 봅시다. `,(0,n.jsx)(t,{children:String.raw`\Delta t = 0.1`}),`초, `,(0,n.jsx)(t,{children:String.raw`F = \begin{bmatrix}1 & 0.1\\ 0 & 1\end{bmatrix}`}),`, 시작 `,(0,n.jsx)(t,{children:String.raw`P = \mathrm{diag}(10^{-4},\ 2.5\cdot10^{-3})`}),`(σ_p = 1 cm, σ_v = 5 cm/s), 예시 가속 잡음 0.3 m/s², 곧 단계마다 속도 분산 `,(0,n.jsx)(t,{children:String.raw`(0.3 \cdot 0.1)^2 = 9\cdot10^{-4}`}),`. 한 단계 뒤: `,(0,n.jsx)(t,{children:String.raw`P_{pp} = 10^{-4} + 0.01 \cdot 2.5\cdot10^{-3} = 1.25\cdot10^{-4}`}),`, `,(0,n.jsx)(t,{children:String.raw`P_{pv} = 2.5\cdot10^{-4}`}),`, `,(0,n.jsx)(t,{children:String.raw`P_{vv} = 3.4\cdot10^{-3}`}),`, 따라서 σ_p = 1.12 cm. 두 단계 뒤: `,(0,n.jsx)(t,{children:String.raw`P_{pp} = 1.25\cdot10^{-4} + 2(0.1)(2.5\cdot10^{-4}) + 0.01 \cdot 3.4\cdot10^{-3} = 2.09\cdot10^{-4}`}),`, σ_p = 1.45 cm. 위치에 잡음이 직접 들어가지 않아도 위치 불확실성이 커집니다. `,(0,n.jsx)(t,{children:String.raw`F`}),`가 속도 불확실성을 위치로 옮기기 때문입니다. 0.3 m/s²는 예제용으로 고른 값이며, 설정의 `,(0,n.jsx)(`code`,{children:`acc_cov`}),`를 환산한 값이 아닙니다.`]}),paper:(0,n.jsx)(n.Fragment,{children:`FAST-LIO(Xu, Zhang, 2021)는 운동학 모델과 반복 오차 상태 칼만 필터를 정의하고, FAST-LIO2(Xu 외, 2022)는 이를 유지하면서 ikd-Tree 지도를 더합니다. 확인한 구현은 IKFoM 툴킷을 쓰며, 중력은 S² 위에 있고 바이어스는 잡음으로만 변합니다.`}),site:(0,n.jsxs)(n.Fragment,{children:[`전파 그림은 예시입니다. 타원 반지름은 `,(0,n.jsx)(t,{children:String.raw`0.03 + 0.25\,k\,s^{1.5}`}),` m(s = 갱신 이후 시간, k = 프로세스 잡음 배율)를 따르며, 속도 랜덤 워크와 닮도록 고른 모양이지 필터 계산이 아닙니다. 플레이그라운드 필터는 가정한 오도메트리 잡음으로 3-상태(x, y, θ) 공분산을 전파하며, 실제 자이로 바이어스를 알지 못합니다.`]}),dataset:(0,n.jsxs)(n.Fragment,{children:[`설정은 `,(0,n.jsx)(`code`,{children:`acc_cov 0.3`}),`, `,(0,n.jsx)(`code`,{children:`gyr_cov 0.03`}),`, `,(0,n.jsx)(`code`,{children:`b_acc_cov 1e-4`}),`, `,(0,n.jsx)(`code`,{children:`b_gyr_cov 1e-5`}),`이며, 코드는 전파 전에 `,(0,n.jsx)(`code`,{children:`[1, −1, −1]`}),` 축 변환을 적용합니다. 전파는 공개 지도에 따로 흔적을 남기지 않지만, 2F, 3F, 6F, 8F 스캔을 놓은 모든 포즈를 만들어 냈습니다.`]}),interactiveLink:(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(`em`,{children:`마지막 LiDAR 갱신 이후 시간`}),`은 전파 구간(단계 수 × `,(0,n.jsx)(t,{children:String.raw`\Delta t`}),`)이고, `,(0,n.jsx)(`em`,{children:`프로세스 잡음`}),`은 `,(0,n.jsx)(t,{children:`Q`}),`의 역할을 키우거나 줄이며, `,(0,n.jsx)(`em`,{children:`지금 LiDAR 갱신`}),`은 `,(0,n.jsx)(t,{children:`P`}),`를 줄이는 측정 갱신을 나타냅니다.`]}),check:{q:`P_{k+1} = F_x P_k F_xᵀ + F_w Q F_wᵀ에서 Q = 0으로 둡니다. 그래도 위치 불확실성이 커질 수 있을까요?`,options:[`아니다, 잡음이 없으면 P는 일정하다`,`그렇다, F_x가 속도·자세 불확실성을 위치로 옮긴다`,`LiDAR 갱신이 올 때만 커진다`,`바이어스가 0일 때만 커진다`],answer:1,explain:(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t,{children:String.raw`Q = 0`}),`이어도 예제의 `,(0,n.jsx)(t,{children:String.raw`P_{pp}`}),`는 `,(0,n.jsx)(t,{children:String.raw`10^{-4}`}),`에서 `,(0,n.jsx)(t,{children:String.raw`1.25\cdot10^{-4}`}),`로 커집니다. 불확실한 속도가 시간이 지나며 불확실한 위치가 됩니다.`]})}}},{beginner:{question:(0,n.jsx)(n.Fragment,{children:`이 데이터셋에 쓴 FAST-LIO 소프트웨어는 스캔마다 움직임 왜곡을 없애기 위해 실제로 무엇을 할까요?`}),analogy:(0,n.jsx)(n.Fragment,{children:`달리는 차에서 조각조각 찍은 사진들을 떠올려 보세요. 조각마다 찍은 순간이 조금씩 다릅니다. 깨끗한 사진 한 장으로 맞추려면 마지막 장면을 기준으로 삼고, 조각마다 거꾸로 거슬러 가며 “이 조각을 찍을 때 차는 어디에 있었고, 지금은 어디에 있는가?”를 묻습니다. 사진과 달리 LiDAR에서는 점 하나하나가 따로 이 처리를 거칩니다.`}),story:[(0,n.jsxs)(n.Fragment,{children:[`4강에서는 왜곡 보정이 왜 필요한지 설명했습니다. 이번 강의에서는 FAST-LIO가 고른 구체적인 방식을 따라갑니다. 스윕의 모든 점을 `,(0,n.jsx)(`strong`,{children:`스윕 끝`}),` 시각의 LiDAR 좌표계로 표현하는 것입니다. 필터 상태를 예측하는 시각도 바로 그때이므로, 스캔과 상태가 같은 순간을 가리키게 됩니다.`]}),(0,n.jsx)(n.Fragment,{children:`먼저 점마다 시각이 필요합니다. XT16 드라이버는 점마다 절대 타임스탬프를 주고, 코드가 이를 FAST-LIO가 기대하는 스윕 안의 시간 오프셋으로 바꿉니다. 그다음 점을 그 오프셋 순으로 정렬합니다.`}),(0,n.jsxs)(n.Fragment,{children:[`다음은 `,(0,n.jsx)(`strong`,{children:`역방향 전파`}),`입니다. 전파(5강) 동안 필터는 IMU 샘플마다 IMU 포즈를 저장해 두었습니다. 두 샘플 사이에서는 각속도와 가속도를 일정하다고 봅니다. 소프트웨어는 스캔 끝에서 출발해 이 짧은 구간들을 거꾸로 거슬러 가며, 점마다 그 점의 시각과 스캔 끝 사이에 센서가 어떻게 움직였는지 계산합니다.`]}),(0,n.jsx)(n.Fragment,{children:`마지막으로 각 점을 변환합니다. 자기 시각의 LiDAR 좌표계에서 IMU 좌표계로, 스캔 끝까지의 움직임을 거쳐, 다시 LiDAR 좌표계로 돌아옵니다. 2강의 외부 파라미터는 들어갈 때 한 번, 나올 때 한 번, 모두 두 번 쓰입니다. 결과는 스윕 끝에 한순간에 찍은 것처럼 보이는 스캔이며, 지도와 정합할 준비가 됩니다.`})],tryIt:(0,n.jsxs)(n.Fragment,{children:[`이 버전의 왜곡 보정 렌즈는 FAST-LIO처럼 기준 시각이 스캔 끝으로 고정되어 있습니다. `,(0,n.jsx)(`em`,{children:`왜곡 보정 적용`}),`을 켜고 `,(0,n.jsx)(`em`,{children:`스캔 안의 시각`}),`을 끌어 보세요. 가장 이른 점이 가장 많이 옮겨지고, 마지막 점은 거의 움직이지 않습니다. `,(0,n.jsx)(`em`,{children:`회전 속도`}),`와 `,(0,n.jsx)(`em`,{children:`벽까지 거리`}),`를 늘리며 `,(0,n.jsx)(`em`,{children:`가장 큰 점 변위`}),`를 읽어 보세요.`]}),misconception:(0,n.jsx)(n.Fragment,{children:`“왜곡 보정의 기준 시각은 아무래도 상관없다.” 어떤 기준 시각이든 스캔은 곧게 펴지지만, 그 시각은 필터 상태의 시각과 같아야 합니다. 상태는 스캔 끝을 가리키는데 스캔 시작으로 보정하면 모든 잔차가 상태와 어긋납니다.`}),summary:[(0,n.jsx)(n.Fragment,{children:`FAST-LIO는 스윕의 모든 점을 스캔 끝 시각의 LiDAR 좌표계로 표현합니다.`}),(0,n.jsx)(n.Fragment,{children:`전파 동안 저장한 IMU 포즈를 거꾸로 거슬러 가며, IMU 간격마다 움직임을 일정하다고 봅니다.`}),(0,n.jsx)(n.Fragment,{children:`외부 파라미터는 들어갈 때와 나올 때 적용되며, 점별 시각은 코드의 타임스탬프 변환에서 옵니다.`})]},advanced:{objectives:[(0,n.jsx)(n.Fragment,{children:`스캔 끝 보상을 변환의 사슬로 쓰고 각 인자를 구분합니다.`}),(0,n.jsxs)(n.Fragment,{children:[`사이트 표기와 코드 표기(`,(0,n.jsx)(t,{children:String.raw`R_{LI}, T_{LI}`}),` 대 `,(0,n.jsx)(t,{children:String.raw`R_{IL}, t_{IL}`}),`)를 대응시킵니다.`]}),(0,n.jsx)(n.Fragment,{children:`요만 있는 예제로 보상량을 계산하고, 그것이 어떤 설정 사실에 의존하는지 판단합니다.`})],model:[[`입력`,(0,n.jsxs)(n.Fragment,{children:[`오프셋 `,(0,n.jsx)(t,{children:String.raw`t_j`}),`가 있는 스윕 점 `,(0,n.jsx)(t,{children:String.raw`p_{L,j}`}),`, 전파에서 얻은 IMU 샘플마다의 포즈 `,(0,n.jsx)(t,{children:String.raw`T_{WI}(t)`}),`, 스캔 끝 `,(0,n.jsx)(t,{children:String.raw`t_e`}),`.`]})],[`기준`,(0,n.jsxs)(n.Fragment,{children:[`필터 사전 추정의 시각인 `,(0,n.jsx)(t,{children:String.raw`t_e`}),`의 LiDAR 좌표계.`]})],[`샘플 사이의 움직임`,(0,n.jsxs)(n.Fragment,{children:[`IMU 구간마다 `,(0,n.jsx)(t,{children:String.raw`\omega`}),`와 `,(0,n.jsx)(t,{children:`a`}),`가 일정. `,(0,n.jsx)(t,{children:String.raw`t_j`}),`의 포즈는 구간 시작에서 적분합니다.`]})],[`외부 파라미터`,(0,n.jsxs)(n.Fragment,{children:[`코드 표기 `,(0,n.jsx)(t,{children:String.raw`R_{LI}, T_{LI}`}),`(“IMU에서 본 LiDAR”) = 사이트 표기 `,(0,n.jsx)(t,{children:String.raw`R_{IL}, t_{IL}`}),`. 이 설정에서는 고정.`]})],[`타임스탬프`,(0,n.jsxs)(n.Fragment,{children:[`코드는 PointCloud2 파서를 다시 작성해 XT16의 점별 절대 시각을 밀리초 오프셋으로 바꿉니다. 시각 필드가 없으면 `,(0,n.jsx)(`code`,{children:`scan_rate`}),` 기준 균일 간격으로 대체합니다.`]})]],steps:[{title:`입력`,text:(0,n.jsx)(n.Fragment,{children:`스윕 하나, 그 IMU 구간들, 저장된 IMU 포즈.`})},{title:`정렬`,text:(0,n.jsx)(n.Fragment,{children:`점을 시간 오프셋 순으로 정렬합니다. 루프는 마지막 점부터 거꾸로 돌므로 IMU 구간마다 한 번씩만 방문합니다.`})},{title:`점 시각의 포즈`,text:(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t,{children:String.raw`t_j`}),`를 포함하는 구간에서 시작점부터 일정한 `,(0,n.jsx)(t,{children:String.raw`\omega, a`}),`로 적분해 `,(0,n.jsx)(t,{children:String.raw`R_j`}),`와 스캔 끝 포즈까지의 병진 `,(0,n.jsx)(t,{children:String.raw`T_{ej}`}),`를 얻습니다.`]})},{title:`변환의 사슬`,text:(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t,{children:String.raw`t_j`}),`의 LiDAR → `,(0,n.jsx)(t,{children:String.raw`t_j`}),`의 IMU → 월드 → `,(0,n.jsx)(t,{children:String.raw`t_e`}),`의 IMU → `,(0,n.jsx)(t,{children:String.raw`t_e`}),`의 LiDAR.`]}),tex:String.raw`p_L^{\,e} = T_{IL}^{-1}\; T_{WI}(t_e)^{-1}\; T_{WI}(t_j)\; T_{IL}\; p_{L,j}`},{title:`코드 형태`,text:(0,n.jsx)(n.Fragment,{children:`같은 연산을 구현의 표기(각색)로 회전과 병진을 풀어 쓴 것입니다.`}),tex:String.raw`P' = R_{LI}^\top\Big(R_{e}^\top\big(R_j\,(R_{LI}\,P + T_{LI}) + T_{ej}\big) - T_{LI}\Big)`},{title:`출력`,text:(0,n.jsx)(n.Fragment,{children:`스캔 끝 LiDAR 좌표계로 움직임을 보상한 스캔. 스캔-지도 잔차(7–9강)에 씁니다.`})}],example:(0,n.jsxs)(n.Fragment,{children:[`초당 30°의 요 회전만 있고, 스윕은 `,(0,n.jsx)(t,{children:String.raw`t_s = 0`}),`에서 `,(0,n.jsx)(t,{children:String.raw`t_e = 0.1`}),`초까지이며, 간단히 L = I(외부 파라미터 없음)라고 합시다. `,(0,n.jsx)(t,{children:String.raw`t_j = 0.02`}),`초에 측정한 점이 x 방향 10 m에 있습니다. `,(0,n.jsx)(t,{children:String.raw`t_j`}),`와 `,(0,n.jsx)(t,{children:String.raw`t_e`}),` 사이에 센서는 `,(0,n.jsx)(t,{children:String.raw`30 \times 0.08 = 2.4^\circ`}),` 돌므로, 스캔 끝 좌표계에서 `,(0,n.jsx)(t,{children:String.raw`p^{\,e} = (10\cos 2.4^\circ,\ -10\sin 2.4^\circ) = (9.991,\ -0.419)`}),` m, 곧 0.42 m를 보정합니다. `,(0,n.jsx)(t,{children:String.raw`t_j = 0.1`}),`초에 측정한 점은 옮겨지지 않습니다. 실제 외부 파라미터를 쓰면 회전이 `,(0,n.jsx)(t,{children:String.raw`R_{IL}`}),`로 켤레 변환되고(`,(0,n.jsx)(t,{children:String.raw`+z_I`}),` 기준 요는 `,(0,n.jsx)(t,{children:String.raw`-z_L`}),` 기준 회전), 0.171 m의 레버 암이 작은 항을 더합니다.`]}),paper:(0,n.jsxs)(n.Fragment,{children:[`FAST-LIO(Xu, Zhang, 2021)가 움직임을 스캔 끝으로 보상하는 역방향 전파를 도입했고, FAST-LIO2도 이를 유지합니다. 위 식은 확인한 구현(`,(0,n.jsx)(`code`,{children:`UndistortPcl`}),`)을 사이트의 각색 표기로 쓴 것입니다.`]}),site:(0,n.jsx)(n.Fragment,{children:`그림은 기준 시각을 스캔 끝으로 고정한 왜곡 보정 렌즈입니다. 속도와 회전 속도가 일정하고, 평면 운동이며, 외부 파라미터와 잡음이 없습니다. 플레이그라운드는 2D 스캔이 순간 측정이므로 왜곡 보정이 없습니다.`}),dataset:(0,n.jsxs)(n.Fragment,{children:[`XT16 처리기는 `,(0,n.jsx)(`code`,{children:`lidar_type: 2`}),`를 재사용하지만, 코드에서 범용 PointCloud2 필드 파서로 다시 작성되었습니다. 두 FAST-LIO 파라미터 파일은 `,(0,n.jsx)(`code`,{children:`scan_rate`}),`(10.0 대 6.37)와 LiDAR–IMU 시간 오프셋(−0.025 대 0.0초)이 서로 다르며, 어느 설정으로 각 층을 만들었는지는 기록되어 있지 않습니다. 공개 지도에는 보정된 결과만 있어 보정 과정을 확인할 수 없습니다.`]}),interactiveLink:(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(`em`,{children:`회전 속도`}),`와 `,(0,n.jsx)(`em`,{children:`전진 속도`}),`는 `,(0,n.jsx)(t,{children:String.raw`T_{WI}(t)`}),`를, `,(0,n.jsx)(`em`,{children:`스캔 시간`}),`은 `,(0,n.jsx)(t,{children:String.raw`t_e - t_s`}),`를, `,(0,n.jsx)(`em`,{children:`스캔 안의 시각`}),`은 `,(0,n.jsx)(t,{children:String.raw`t_j`}),`를 정합니다. 기준은 `,(0,n.jsx)(t,{children:String.raw`t_e`}),`로 고정이므로 `,(0,n.jsx)(`em`,{children:`가장 큰 점 변위`}),`는 가장 이른 점의 값입니다.`]}),check:{q:`초당 30°로 돌고 스윕이 0.1초일 때, t_j = 0.02초에 측정한 점의 좌표계와 스캔 끝 좌표계 사이의 회전은 얼마일까요?`,options:[`0.6°`,`2.4°`,`3°`,`0.24°`],answer:1,explain:(0,n.jsxs)(n.Fragment,{children:[`시각 차이가 `,(0,n.jsx)(t,{children:String.raw`t_e - t_j = 0.08`}),`초이므로 `,(0,n.jsx)(t,{children:String.raw`30 \times 0.08 = 2.4^\circ`}),`입니다. 3° 전체는 스캔 시작에 측정한 점에만 해당합니다.`]})}}}],i=[{beginner:{question:(0,n.jsx)(n.Fragment,{children:`지도가 계속 커지는 동안, 로봇은 새 레이저 점마다 가장 가까운 지도 점 몇 개를 1초에도 여러 번 어떻게 찾아낼까요?`}),analogy:(0,n.jsxs)(n.Fragment,{children:[`목록이 잘 정리된 큰 도서관을 떠올려 보세요. 한 주제의 책을 찾을 때 모든 책을 살펴보지 않고 해당 층, 서가, 칸으로 바로 갑니다. 새 책은 들어오는 대로 꽂고, 이용자가 멀리 떠난 구역은 보관실로 옮깁니다. `,(0,n.jsx)(`strong`,{children:`비유가 맞지 않는 부분:`}),` 도서관은 주제로 정리하지만 지도는 공간 위치로 정리하며, 공간을 x, y, z 축 중 하나를 따라 계속 둘로 나눕니다.`]}),story:[(0,n.jsxs)(n.Fragment,{children:[`FAST-LIO는 새 스캔을 지금까지 만든 지도와 비교해 위치를 보정합니다. 이를 위해 스캔 점마다 가장 가까운 지도 점 다섯 개, 곧 `,(0,n.jsx)(`em`,{children:`최근접 이웃`}),`이 필요합니다. 이 다섯 점이 스캔 점이 놓여야 할 작은 표면 조각을 나타내기 때문입니다(8강). 이 탐색은 스캔마다 수천 개의 점에 대해 이루어지고, 갱신의 반복마다 다시 이루어집니다(9강).`]}),(0,n.jsx)(n.Fragment,{children:`가장 단순한 방법은 스캔 점 하나와 모든 지도 점 사이의 거리를 재서 가장 작은 다섯 개를 고르는 것입니다. 지도 점이 백만 개라면 스캔 점 하나에 거리 계산이 백만 번, 스캔 전체로는 수십억 번이 됩니다. LiDAR는 초당 약 열 개의 스캔을 보내므로 이렇게는 너무 느립니다. 어려움이 하나 더 있습니다. 지도가 고정되어 있지 않다는 것입니다. 스캔마다 새 점이 더해지고, 로봇이 떠나온 영역은 언젠가 버려야 합니다.`}),(0,n.jsxs)(n.Fragment,{children:[`이 순간 로봇이 가진 것은 두 가지입니다. 하나는 지금까지 저장한 월드 좌표계의 지도 점이고, 다른 하나는 새 스캔입니다. 새 스캔의 점들은 왜곡 보정(6강)을 거쳐 0.3 m 격자로 솎아졌고, 현재 포즈 추정값으로 월드로 옮겨졌습니다. 이 점 하나하나가 “나와 가장 가까운 저장된 점 다섯 개는?”이라는 `,(0,n.jsx)(`em`,{children:`질의`}),`입니다.`]}),(0,n.jsxs)(n.Fragment,{children:[`FAST-LIO는 지도를 증분 k-d 트리인 `,(0,n.jsx)(`strong`,{children:`ikd-Tree`}),`에 보관합니다. `,(0,n.jsx)(`em`,{children:`k-d 트리`}),`는 공간을 한 축을 따라 둘로 나누고, 각 절반을 다시 나누는 일을 반복하므로, 탐색할 때 질의 근처의 몇 개 상자만 살펴보면 됩니다. `,(0,n.jsx)(`em`,{children:`증분`}),`이란 트리 전체를 다시 만들지 않고도 점을 넣고 뺄 수 있다는 뜻이며, 한쪽으로 치우친 부분만 다시 만듭니다. 점을 넣을 때는 그 점의 0.3 m 칸(`,(0,n.jsx)(`em`,{children:`복셀`}),`)에 더 나은 점이 이미 있는지 확인해 지도가 쓸데없이 빽빽해지지 않게 합니다. 로봇이 국소 지도 상자의 가장자리에 가까워지면 멀리 있는 점들을 상자 단위로 삭제합니다.`]}),(0,n.jsx)(n.Fragment,{children:`그 결과 지도가 커져도 탐색 시간은 천천히만 늘어나며, 주행 초반이든 후반이든 스캔 하나를 처리하는 시간이 비슷하게 유지됩니다. 찾은 이웃 다섯 개는 이어서 검사를 받습니다. 이들이 0.1 m 이내에서 하나의 평면 위에 있지 않으면 그 점은 보정에 쓰지 않습니다.`})],tryIt:(0,n.jsxs)(n.Fragment,{children:[`분홍색 질의 점을 벽 가까이로 끌어 보세요. 주황색 이웃 다섯 개가 그 벽 위에 놓이고 맞춘 직선이 초록색(채택)이 됩니다. 질의 점을 방 한가운데의 빈 곳으로 옮기면 이웃이 흩어진 점들에서 오므로 평면이 거부됩니다. 이어서 `,(0,n.jsx)(`em`,{children:`로봇 위치`}),` 슬라이더를 움직이면 점선 상자가 로봇을 따라가고, 상자 밖의 점이 어둡게 바뀝니다. 국소 지도에서 삭제되어 더는 이웃이 될 수 없는 점들입니다.`]}),misconception:(0,n.jsx)(n.Fragment,{children:`“뷰어에서 보는 지도가 곧 ikd-Tree다.” 그렇지 않습니다. 트리는 FAST-LIO가 실행되는 동안 메모리에만 존재합니다. 웹 파일은 후처리한 지도를 복셀 다운샘플링한 별도 사본이며, ikd-Tree도 옥트리(octree)도 아닙니다.`}),summary:[(0,n.jsx)(n.Fragment,{children:`스캔 점마다 가장 가까운 지도 점 다섯 개가 필요하며, 이 탐색은 스캔당 수천 번 일어납니다.`}),(0,n.jsx)(n.Fragment,{children:`FAST-LIO는 지도를 ikd-Tree에 저장해, 점을 넣고 솎고 지우는 동안에도 이웃을 빠르게 찾습니다.`}),(0,n.jsx)(n.Fragment,{children:`찾은 이웃은 0.1 m 평탄도 검사를 통과해야 그 점이 포즈를 보정할 수 있습니다.`})]},advanced:{objectives:[(0,n.jsx)(n.Fragment,{children:`모든 잔차가 의존하는 k-최근접 이웃 질의를 쓰고, 그것이 스캔 처리 비용의 대부분을 차지하는 이유를 설명합니다.`}),(0,n.jsx)(n.Fragment,{children:`ikd-Tree가 제공하는 증분 연산, 즉 트리 내부 다운샘플링을 동반한 삽입, 지연 삭제, 박스 삭제, 부분 재구성을 구분합니다.`}),(0,n.jsxs)(n.Fragment,{children:[`설정값 `,(0,n.jsx)(`code`,{children:`filter_size_map`}),`, `,(0,n.jsx)(`code`,{children:`cube_side_length`}),`, `,(0,n.jsx)(`code`,{children:`det_range`}),`를 국소 지도의 동작과 연결합니다.`]}),(0,n.jsx)(n.Fragment,{children:`메모리 안의 트리와 공개된 웹 LOD 파일을 구분합니다.`})],model:[[`지도`,(0,n.jsxs)(n.Fragment,{children:[`월드 좌표계 W(미터)의 점 집합 `,(0,n.jsx)(t,{children:String.raw`\mathcal{M} \subset \mathbb{R}^3`}),`이며, ikd-Tree에 저장됩니다. 각 노드는 점 하나를 갖고 자기 하위 공간을 한 축을 따라 나눕니다.`]})],[`질의`,(0,n.jsxs)(n.Fragment,{children:[`현재 반복값으로 변환한 스캔 점 `,(0,n.jsx)(t,{children:String.raw`p_{W,j} = R_{WI}(R_{IL}\,p_{L,j} + t_{IL}) + p_{WI}`}),`. 반복값이 틀리면 이웃도 틀리게 찾으며, 갱신을 반복하는 이유 중 하나입니다(9강).`]})],[`이웃`,(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t,{children:String.raw`\mathcal{N}_5(p)`}),`: `,(0,n.jsx)(t,{children:`p`}),`까지의 유클리드 거리가 가장 작은 `,(0,n.jsx)(t,{children:String.raw`\mathcal{M}`}),`의 점 다섯 개. 확인한 소스에서 `,(0,n.jsx)(`code`,{children:`NUM_MATCH_POINTS = 5`}),`입니다(I-2).`]})],[`국소 지도`,(0,n.jsxs)(n.Fragment,{children:[`센서를 둘러싼 한 변 `,(0,n.jsx)(`code`,{children:`cube_side_length`}),`의 정육면체. 센서가 경계에 가까워지면 `,(0,n.jsx)(`code`,{children:`lasermap_fov_segment()`}),`가 정육면체를 옮기고 `,(0,n.jsx)(`code`,{children:`Delete_Point_Boxes`}),`가 밖에 남은 박스를 지웁니다(I-2).`]})],[`삽입 규칙`,(0,n.jsxs)(n.Fragment,{children:[`수렴한 스캔 점을 `,(0,n.jsx)(`code`,{children:`filter_size_map`}),` = 0.3 m 복셀의 중심과 비교해, 그 중심 근처에 이미 있는 점보다 나을 때만 추가합니다(I-2).`]})]],steps:[{title:`입력`,text:(0,n.jsxs)(n.Fragment,{children:[`다운샘플링한 스캔(`,(0,n.jsx)(`code`,{children:`filter_size_surf`}),` 0.3 m), 현재 반복값 `,(0,n.jsx)(t,{children:String.raw`(R_{WI}, p_{WI})`}),`, 트리. 각 스캔 점을 W로 변환합니다.`]}),tex:String.raw`p_{W,j} = R_{WI}\,\big(R_{IL}\,p_{L,j} + t_{IL}\big) + p_{WI}`},{title:`탐색`,text:(0,n.jsx)(n.Fragment,{children:`질의마다 가장 가까운 지도 점 다섯 개를 찾습니다. 전수 탐색은 지도 점마다 거리 하나를 계산하고, 3차원의 균형 잡힌 k-d 트리는 보통 지도 크기의 로그에 비례하는 수의 노드만 방문합니다.`}),tex:String.raw`\mathcal{N}_5(p) = \operatorname*{arg\,min}_{\{q_1..q_5\} \subset \mathcal{M}} \textstyle\sum_{i} \lVert p - q_i \rVert,\qquad O(|\mathcal{M}|)\ \text{vs}\ \approx O(\log |\mathcal{M}|)`},{title:`검사`,text:(0,n.jsx)(n.Fragment,{children:`이웃 다섯 개에 평면을 맞추고, 그 평면에서 0.1 m보다 먼 이웃이 하나라도 있으면 그 질의는 잔차를 만들지 않습니다(I-6, 자세한 내용은 8강).`}),tex:String.raw`\max_{k=1..5}\ \big|\,n^\top q_k + d\,\big| \le 0.1\ \text{m}`},{title:`삽입`,text:(0,n.jsx)(n.Fragment,{children:`포즈가 수렴한 뒤 트리 내부 다운샘플링과 함께 스캔을 삽입합니다(10강).`}),tex:String.raw`\mathcal{M} \leftarrow \mathcal{M} \cup \mathrm{voxel}_{0.3}\big(T^\ast \mathcal{S}\big)`},{title:`유지`,text:(0,n.jsx)(n.Fragment,{children:`삭제는 지연 방식으로, 먼저 삭제 라벨만 붙입니다. 하위 트리는 한쪽이 점을 지나치게 많이 차지하거나 삭제 라벨이 붙은 점이 너무 많을 때만 다시 만듭니다(ikd-Tree 프리프린트의 균형 기준과 삭제 기준). 국소 정육면체가 움직이면 박스 삭제로 영역 전체를 지웁니다.`})},{title:`출력`,text:(0,n.jsx)(n.Fragment,{children:`질의마다 이웃 다섯 개와 평면, 또는 “사용 안 함”. 트리는 다음 스캔을 받을 준비가 됩니다.`})}],example:(0,n.jsxs)(n.Fragment,{children:[`이 데이터셋의 값이 아닌 예시 크기입니다. 다운샘플링 후 2,000점짜리 스캔과 10⁶점짜리 국소 지도를 가정합니다. 전수 탐색은 반복 한 번에 2,000 × 10⁶ = 2 × 10⁹번, 세 번 반복하면 6 × 10⁹번의 거리 계산이 필요합니다. 10⁶점의 균형 트리는 깊이가 ⌈log₂ 10⁶⌉ = 20입니다. 질의마다 노드 100개를 방문한다고 해도 반복 한 번에 2 × 10⁵번이며, 약 10⁴배 적습니다. 설정에서 `,(0,n.jsx)(`code`,{children:`cube_side_length`}),`는 1000 m, `,(0,n.jsx)(`code`,{children:`det_range`}),`는 100 m로, 둘 다 건물 한 층보다 훨씬 큽니다. 따라서 이 층들에서는 박스 삭제가 거의 또는 전혀 일어나지 않았을 가능성이 크지만, 로그로 확인한 사실은 아닙니다.`]}),paper:(0,n.jsx)(n.Fragment,{children:`ikd-Tree는 FAST-LIO2와 함께 도입된 지도 구조로, 증분 삽입, 트리 내부 다운샘플링, 국소 지도 이동에 따른 박스 단위 삭제를 제공합니다(FAST-LIO2 초록, ikd-Tree 프리프린트). 프리프린트에 따르면 불균형한 하위 트리만 다시 만들어 균형을 유지하고, 라벨로 지연 삭제를 합니다.`}),site:(0,n.jsxs)(n.Fragment,{children:[`인터랙티브는 2차원 개념도입니다. 이웃 5개를 쓰고 평면 대신 `,(0,n.jsx)(`em`,{children:`직선`}),`을 맞추며, 같은 0.1 m 검사를 적용합니다. 국소 박스의 반폭은 3 m입니다. SLAM Playground의 필터는 트리를 쓰지 않습니다. 0.3 m 칸의 해시 격자에서 0.6 m 이내 이웃 5개를 찾고, λ`,(0,n.jsx)(`sub`,{children:`min`}),`/trace ≤ 0.1이면 직선 모양으로 판단합니다. 지도는 5 cm 복셀 점 지도입니다.`]}),dataset:(0,n.jsxs)(n.Fragment,{children:[`확인한 포크는 `,(0,n.jsx)(`code`,{children:`hku-mars/ikd-Tree`}),`(`,(0,n.jsx)(`code`,{children:`fast_lio`}),` 브랜치)를 포함하며, `,(0,n.jsx)(`code`,{children:`NUM_MATCH_POINTS = 5`}),`, `,(0,n.jsx)(`code`,{children:`filter_size_map: 0.3`}),`, `,(0,n.jsx)(`code`,{children:`cube_side_length: 1000`}),`, `,(0,n.jsx)(`code`,{children:`det_range: 100`}),`입니다(I-1~I-3). 패키지에 `,(0,n.jsx)(`code`,{children:`.git`}),` 메타데이터가 없어 상위 커밋은 알 수 없습니다. 공개한 각 층을 어느 파라미터 조합으로 만들었는지는 기록되어 있지 않습니다. 웹 LOD 파일은 복셀 다운샘플링한 별도 파일이며 ikd-Tree도 옥트리도 아닙니다.`]}),interactiveLink:(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(`em`,{children:`질의 점 x / y`}),`는 `,(0,n.jsx)(t,{children:`p`}),`를 옮겨 `,(0,n.jsx)(t,{children:String.raw`\mathcal{N}_5(p)`}),`를 바꿉니다. `,(0,n.jsx)(`em`,{children:`로봇 위치`}),`는 국소 박스를 옮겨 `,(0,n.jsx)(t,{children:String.raw`\mathcal{M}`}),` 자체를 바꾸며, 박스 밖의 점은 삭제됩니다. 표시값 “맞춘 직선까지 가장 먼 이웃의 거리”가 `,(0,n.jsx)(t,{children:String.raw`\max_k |n^\top q_k + d|`}),`이며, 0.1 m와 비교합니다.`]}),check:{q:`지도가 비어 있는 상태로만 본 방에 서 있는 사람에 스캔 점 하나가 맞았습니다. 이 점의 최근접 지도 점 다섯 개는 서로 다른 두 벽에서 왔습니다. 확인한 FAST-LIO 코드는 갱신 중에 이 점을 어떻게 처리할까요?`,options:[`그래도 가장 가까운 벽을 평면으로 쓴다`,`평면을 맞춘 뒤 0.1 m보다 먼 이웃을 발견하고, 이 점에서 잔차를 만들지 않는다`,`두 벽을 지도에서 지운다`,`대신 이웃 열 개를 찾는다`],answer:1,explain:(0,n.jsx)(n.Fragment,{children:`두 벽에 걸친 이웃은 한 평면 위에 있지 않으므로 0.1 m 평면 검사에서 탈락하고, 이 점은 잔차를 만들지 않습니다. 하지만 포즈가 수렴한 뒤에는 이 점도 지도에 삽입될 수 있습니다. 걸어 다니는 사람이 궤적처럼 남는 이유입니다(10강).`})}}},{beginner:{question:(0,n.jsx)(n.Fragment,{children:`레이저 점 하나가 어떻게 로봇에게 추정한 위치가 얼마나 틀렸는지 알려 줄 수 있을까요?`}),analogy:(0,n.jsxs)(n.Fragment,{children:[`액자가 벽에 딱 붙어 있는지 확인할 때, 특정 못까지의 거리를 재지 않고 액자가 벽면에서 얼마나 떠 있는지를 잽니다. `,(0,n.jsx)(`strong`,{children:`비유가 맞지 않는 부분:`}),` 로봇의 “벽”은 잡음이 섞인 지도 점 다섯 개에 맞춘 작은 평면이고, 그 점들이 정말 평평할 때만 믿으며, 점 하나는 벽을 `,(0,n.jsx)(`em`,{children:`따라`}),` 미끄러지는 움직임에 대해서는 아무것도 알려 주지 않습니다.`]}),story:[(0,n.jsxs)(n.Fragment,{children:[`7강을 거치면 스캔 점마다 지도에서 찾은 이웃 다섯 개가 생깁니다. 추정한 포즈가 완벽하다면 스캔 점은 그 이웃들과 같은 표면 위에 있을 것입니다. 벽의 점은 벽 위에, 바닥의 점은 바닥 위에 놓입니다. 따라서 점이 그 표면에서 벗어난 거리는 포즈 오차의 척도가 됩니다. 이 거리를 `,(0,n.jsx)(`em`,{children:`잔차`}),`라고 부릅니다. 현재 추정값으로 설명되지 않는 측정의 나머지 부분입니다.`]}),(0,n.jsx)(n.Fragment,{children:`왜 가장 가까운 지도 점까지의 거리를 쓰지 않을까요? LiDAR는 같은 지점을 두 번 정확히 맞히지 않기 때문입니다. 빔은 스윕마다 벽의 다른 곳에 떨어지므로, 포즈가 완벽해도 점 간격 때문에 점–점 거리가 몇 센티미터씩 나옵니다. 반면 표면은 언제나 같습니다. 그래서 FAST-LIO는 이웃 다섯 개를 지나는 작은 평면을 맞추고 그 평면까지의 거리를 잽니다.`}),(0,n.jsxs)(n.Fragment,{children:[`점마다 로봇은 (현재 추정값으로 구한) 월드 위치, 이웃 다섯 개, 그리고 센서로부터의 거리인 `,(0,n.jsx)(`em`,{children:`거리값(range)`}),`을 갖습니다. 이웃으로 평면을 계산하는데, 평면은 표면에 수직인 방향인 `,(0,n.jsx)(`em`,{children:`법선`}),`과 오프셋으로 나타냅니다. 이웃 중 하나라도 평면에서 0.1 m보다 멀면 그 조각은 충분히 평평하지 않은 것입니다. 모서리나 구석, 사람일 수 있으며, 그 점은 건너뜁니다.`]}),(0,n.jsxs)(n.Fragment,{children:[`잔차는 `,(0,n.jsx)(`em`,{children:`부호 있는`}),` 거리입니다. 평면 한쪽에서는 양수, 반대쪽에서는 음수이므로, 얼마나 떨어졌는지뿐 아니라 포즈를 어느 쪽으로 옮겨야 하는지도 알려 줍니다. 검사가 하나 더 있습니다. 1 − 0.9 × |거리| ÷ √거리값이 0.9보다 클 때만 점을 채택합니다. 말로 풀면, 가까운 점은 평면에 아주 가까워야 하고 먼 점은 거리가 조금 더 커도 됩니다.`]}),(0,n.jsx)(n.Fragment,{children:`채택된 점 하나는 수 하나와 방향 하나를 줍니다. 벽은 벽을 가로지르는 방향의 정보만, 바닥은 수직 방향의 정보만 줍니다. 법선 방향이 제각각인 벽, 바닥, 천장 위의 점 수천 개가 모여야 포즈 전체가 정해집니다. 이것을 IMU 예측과 어떻게 합치는지는 다음 강의에서 다룹니다.`})],tryIt:(0,n.jsxs)(n.Fragment,{children:[`기본값부터 보세요. 25 m 거리에서 0.05 m 떨어진 점은 점수 0.991로 채택됩니다. 거리를 1 m로 낮추고 오프셋을 약 0.11 m보다 크게 하면 점이 거부됩니다. 이웃 퍼짐을 0.1 m보다 크게 하면 오프셋과 상관없이 평면 자체가 거부됩니다. 평면을 기울이면 법선 `,(0,n.jsx)(t,{children:`n_j`}),`가 함께 돌아가는 것을 볼 수 있습니다.`]}),misconception:(0,n.jsxs)(n.Fragment,{children:[`“평면에 가까운 점은 올바른 점이고, 먼 점은 오류다.” 기준은 거리값에 따라 달라집니다. 25 m에서는 평면에서 약 0.56 m까지 떨어져도 쓰이지만, 1 m에서는 약 0.11 m까지만 쓰입니다. 잔차가 작다는 것은 그 점이 `,(0,n.jsx)(`em`,{children:`현재`}),` 추정값과 맞는다는 뜻일 뿐입니다. 그리고 잔차는 가장 가까운 지도 점이 아니라 맞춘 평면까지 잰 거리입니다.`]}),summary:[(0,n.jsx)(n.Fragment,{children:`잔차는 스캔 점에서 지도 이웃 다섯 개로 맞춘 평면까지의 부호 있는 거리입니다.`}),(0,n.jsx)(n.Fragment,{children:`이웃이 평면에서 0.1 m보다 멀면 평면을 버리고, 1 − 0.9|r|/√거리값이 0.9를 넘을 때만 점을 채택합니다.`}),(0,n.jsx)(n.Fragment,{children:`잔차 하나는 그 평면의 법선 방향으로만 포즈를 구속하므로, 방향이 서로 다른 여러 표면이 필요합니다.`})]},advanced:{objectives:[(0,n.jsx)(n.Fragment,{children:`점–평면 잔차와 회전·위치에 대한 그 야코비안을 씁니다.`}),(0,n.jsx)(n.Fragment,{children:`채택 규칙을 거리값에 따른 임계값으로 바꿔 쓰고 계산합니다.`}),(0,n.jsx)(n.Fragment,{children:`장면의 표면 법선으로부터 어떤 포즈 방향이 구속되지 않는지(퇴화) 예측합니다.`})],model:[[`좌표계`,(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t,{children:String.raw`p_{B,j}`}),`: 왜곡 보정한 몸체(IMU) 좌표계의 점, `,(0,n.jsx)(t,{children:String.raw`p_{B,j} = R_{IL}\,p_{L,j} + t_{IL}`}),`. `,(0,n.jsx)(t,{children:String.raw`p_{W,j}`}),`: 현재 반복값 `,(0,n.jsx)(t,{children:String.raw`(R, p)`}),`로 옮긴 월드 좌표계의 같은 점. 단위는 미터.`]})],[`평면`,(0,n.jsxs)(n.Fragment,{children:[`W에서의 단위 법선 `,(0,n.jsx)(t,{children:`n_j`}),`와 오프셋 `,(0,n.jsx)(t,{children:`d_j`}),`(m)로, `,(0,n.jsx)(t,{children:String.raw`\mathcal{N}_5(p_{W,j})`}),`에 최소제곱으로 맞춥니다. 평면에서 0.1 m보다 먼 이웃이 있으면 버립니다(`,(0,n.jsx)(`code`,{children:`esti_plane`}),`, I-6).`]})],[`측정 모델`,(0,n.jsxs)(n.Fragment,{children:[`이상적으로는 `,(0,n.jsx)(t,{children:String.raw`0 = n_j^\top p_{W,j}(x) + d_j + v_j`}),`입니다. 평면은 알려진 것으로 다루며, 평면 맞춤 자체의 오차는 잡음 `,(0,n.jsx)(t,{children:`v_j`}),`에 흡수됩니다.`]})],[`잡음`,(0,n.jsx)(n.Fragment,{children:`잔차 하나하나를 고정된 분산 하나를 갖는 독립 스칼라 측정으로 봅니다. 코드 속 그 수치는 이 사이트를 위해 모은 근거에 포함되지 않습니다.`})],[`가정`,(0,n.jsx)(n.Fragment,{children:`국소적으로 평평한 표면, 정적인 장면, 현재 반복값에서 올바른 대응.`})]],steps:[{title:`변환`,text:(0,n.jsx)(n.Fragment,{children:`왜곡 보정한 점을 현재 반복값으로 월드에 옮깁니다.`}),tex:String.raw`p_{W,j} = R\,p_{B,j} + p`},{title:`평면 맞춤`,text:(0,n.jsxs)(n.Fragment,{children:[`이웃 다섯 개 `,(0,n.jsx)(t,{children:`q_k`}),`를 지나는 최소제곱 평면을 구하고 0.1 m 검사를 합니다.`]}),tex:String.raw`\min_{n,\,d}\ \textstyle\sum_{k=1}^{5} \big(n^\top q_k + d\big)^2,\ \ \lVert n \rVert = 1;\qquad \text{reject if}\ \max_k |n^\top q_k + d| > 0.1\ \text{m}`},{title:`잔차`,text:(0,n.jsx)(n.Fragment,{children:`미터 단위의 부호 있는 점–평면 거리입니다.`}),tex:String.raw`r_j = n_j^\top p_{W,j} + d_j`},{title:`채택 검사`,text:(0,n.jsx)(n.Fragment,{children:`확인한 소스의 채택 규칙을 임계값 형태로 바꿔 쓴 것입니다. 미터를 미터의 제곱근과 비교한다는 점에 주의하세요. 통계적 검정이 아니라 경험 규칙입니다.`}),tex:String.raw`1 - 0.9\,\frac{|r_j|}{\sqrt{\lVert p_{B,j}\rVert}} > 0.9 \iff |r_j| < \tfrac{1}{9}\sqrt{\lVert p_{B,j} \rVert}`},{title:`선형화`,text:(0,n.jsxs)(n.Fragment,{children:[`섭동 `,(0,n.jsx)(t,{children:String.raw`R \leftarrow R\,\mathrm{Exp}(\delta\theta)`}),`, `,(0,n.jsx)(t,{children:String.raw`p \leftarrow p + \delta p`}),`를 쓰면 `,(0,n.jsx)(t,{children:`H`}),`의 한 행은 회전과 위치 성분만 0이 아닙니다. 속도, 바이어스, 중력 열은 0이고, `,(0,n.jsx)(`code`,{children:`extrinsic_est_en`}),`이 false이므로 외부 파라미터 열도 0입니다.`]}),tex:String.raw`\frac{\partial r_j}{\partial(\delta\theta,\ \delta p)} = \Big[\, -n_j^\top R\,\lfloor p_{B,j} \rfloor_\times \quad n_j^\top \,\Big] \in \mathbb{R}^{1\times 6}`},{title:`출력`,text:(0,n.jsxs)(n.Fragment,{children:[`쌓은 잔차 `,(0,n.jsx)(t,{children:`r`}),`(m × 1)와 야코비안 `,(0,n.jsx)(t,{children:`H`}),`를 반복 갱신(9강)에 넘깁니다.`]})}],example:(0,n.jsxs)(n.Fragment,{children:[`바닥 평면 `,(0,n.jsx)(t,{children:String.raw`n = (0,0,1)^\top`}),`, `,(0,n.jsx)(t,{children:`d = 0`}),`. `,(0,n.jsx)(t,{children:`R = I`}),`, `,(0,n.jsx)(t,{children:`p = 0`}),`로 두고, 측정 거리값이 4.0 m인 점 `,(0,n.jsx)(t,{children:String.raw`p_B = (2.00,\,1.00,\,0.04)`}),` m를 생각합니다. 그러면 `,(0,n.jsx)(t,{children:`r = 0.04`}),` m이고 점수는 `,(0,n.jsx)(t,{children:String.raw`1 - 0.9 \cdot 0.04/\sqrt{4} = 0.982 > 0.9`}),`이므로 채택됩니다. 4 m에서의 임계값은 `,(0,n.jsx)(t,{children:String.raw`\sqrt 4/9 = 0.222`}),` m입니다. 야코비안 행은 `,(0,n.jsx)(t,{children:String.raw`H = [\,1,\ -2,\ 0,\ 0,\ 0,\ 1\,]`}),`입니다. +0.01 rad 롤은 점을 `,(0,n.jsx)(t,{children:String.raw`0.01 \cdot y = 0.01`}),` m 올리고, +0.01 rad 피치는 `,(0,n.jsx)(t,{children:String.raw`0.01 \cdot x = 0.02`}),` m 내리며, 요와 수평 이동은 `,(0,n.jsx)(t,{children:`r`}),`를 전혀 바꾸지 않습니다. 바닥은 높이, 롤, 피치를 구속하고, x, y, 요에는 벽이 필요합니다.`]}),paper:(0,n.jsx)(n.Fragment,{children:`FAST-LIO와 FAST-LIO2는 각 LiDAR 점이 지도 이웃들이 이루는 작은 국소 평면 위에 있다고 보고, 점–평면 거리를 측정으로 씁니다. FAST-LIO2는 이를 특징 추출 없이 원시 점에 적용합니다(FAST-LIO2 초록). 0.1 m 평면 검사와 0.9 채택 규칙은 논문이 아니라 확인한 소스(I-6)에서 가져온 내용입니다.`}),site:(0,n.jsxs)(n.Fragment,{children:[`인터랙티브는 정확한 채택 규칙과 0.1 m 퍼짐 검사를 구현한 2차원 개념도입니다. SLAM Playground의 필터는 2차원 점–`,(0,n.jsx)(`em`,{children:`직선`}),` 잔차를 씁니다. 이웃이 직선 모양인지를 0.1 m 거리가 아니라 λ`,(0,n.jsx)(`sub`,{children:`min`}),`/trace ≤ 0.1로 판단하고, Huber 가중(δ = 0.1 m, σ = 0.05 m)을 적용하며, 거리값에 따른 규칙은 없습니다.`]}),dataset:(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(`code`,{children:`feature_extract_enable: false`}),`(원시 점), `,(0,n.jsx)(`code`,{children:`filter_size_surf: 0.3`}),`, `,(0,n.jsx)(`code`,{children:`extrinsic_est_en: false`}),`이고 `,(0,n.jsx)(`code`,{children:`extrinsic_R = diag(1,−1,−1)`}),`, `,(0,n.jsx)(`code`,{children:`extrinsic_T = [0.1710, 0.0, −0.0908]`}),` m입니다(I-3, I-9). 공개한 FAST-LIO 층을 만든 잔차는 저장되어 있지 않아 확인할 수 없습니다.`]}),interactiveLink:(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(`em`,{children:`평면으로부터 점의 거리`}),`가 `,(0,n.jsx)(t,{children:`r_j`}),`이고, `,(0,n.jsx)(`em`,{children:`점까지의 거리`}),`는 채택 검사의 `,(0,n.jsx)(t,{children:String.raw`\lVert p_{B,j} \rVert`}),`입니다. `,(0,n.jsx)(`em`,{children:`이웃 퍼짐`}),`은 0.1 m 검사의 `,(0,n.jsx)(t,{children:String.raw`\max_k |n^\top q_k + d|`}),`에 해당합니다. `,(0,n.jsx)(`em`,{children:`평면 기울기`}),`는 `,(0,n.jsx)(t,{children:`n_j`}),`를 돌리며, 이 잔차가 구속하는 포즈 방향도 함께 바뀝니다.`]}),check:{q:`특징 없는 긴 복도에서 스캔이 바닥(법선 +z)과 양쪽 벽(법선 ±y)만 봅니다. 점–평면 잔차가 구속하지 못하는 포즈 성분은?`,options:[`높이와 요`,`복도 방향(x)의 이동`,`롤과 피치`,`없음: 점 수천 개가 모든 것을 구속한다`],answer:1,explain:(0,n.jsxs)(n.Fragment,{children:[`모든 야코비안 행의 위치 부분은 `,(0,n.jsx)(t,{children:String.raw`n_j^\top`}),`인데, 어느 법선에도 x 성분이 없으므로 포즈가 x로 미끄러져도 잔차가 변하지 않습니다. 요는 여전히 구속됩니다. 벽 점의 회전 부분 `,(0,n.jsx)(t,{children:String.raw`-n^\top R\lfloor p_B \rfloor_\times`}),`가 그 점의 x 좌표에 의존하기 때문입니다. x는 IMU 예측만이 붙잡으며, 8강의 한계에 적은 퇴화가 바로 이것입니다.`]})}}},{beginner:{question:(0,n.jsx)(n.Fragment,{children:`FAST-LIO는 “IMU가 말하는 내 위치”와 “벽이 말하는 내 위치”를 어떻게 합칠까요? 그리고 왜 스캔마다 이를 한 번 넘게 할까요?`}),analogy:(0,n.jsxs)(n.Fragment,{children:[`판사가 대략적인 인상을 가진 증인 한 명(IMU 예측)과, 정확하지만 부분적인 단서를 가진 증인 수천 명(스캔 점)의 말을 각각의 신뢰도에 따라 저울질한다고 생각해 보세요. 첫 판단을 내린 뒤 판사는 새로운 관점에서 모든 단서를 다시 읽습니다. 단서의 의미가 어디에 있다고 가정했는지에 따라 달라지기 때문입니다. `,(0,n.jsx)(`strong`,{children:`비유가 맞지 않는 부분:`}),` 매 회차에 새 증언이 들어오는 것이 아니라 같은 스캔을 다시 평가하며, 판사는 최대 세 번에서 멈춥니다.`]}),story:[(0,n.jsxs)(n.Fragment,{children:[`스캔이 도착하기 전에, 5강의 IMU 전파는 포즈의 `,(0,n.jsx)(`em`,{children:`예측`}),`과 함께 그 예측이 얼마나 틀릴 수 있는지를 나타내는 `,(0,n.jsx)(`em`,{children:`불확실성`}),`을 줍니다. 스캔은 수백에서 수천 개의 잔차(8강)를 주는데, 각각 “벽 위에 놓이려면 이쪽으로 움직여라”라고 말합니다. 갱신은 둘을 모두 존중하는 포즈 하나를 찾아야 합니다. 스캔이 별말을 하지 않는 방향에서는 예측에 가깝게, 벽이 정확한 방향에서는 벽이 말하는 쪽에 가깝게.`]}),(0,n.jsx)(n.Fragment,{children:`칼만 필터는 모든 것이 선형이라고, 즉 포즈를 조금 움직이면 각 잔차도 비례해서 변한다고 가정한 공식으로 이 저울질을 합니다. 이는 작은 변화에서만 성립합니다. 회전은 이 관계를 휘게 만들고, 보행 로봇이 갑자기 발을 디딘 뒤에는 예측이 충분히 멀리 벗어나 있어서, 직선 근사 한 번으로는 최적 포즈에 못 미치거나 지나칠 수 있습니다.`}),(0,n.jsxs)(n.Fragment,{children:[`입력은 예측한 상태(자세, 위치, 속도, IMU 바이어스, 중력)와 그 `,(0,n.jsx)(`em`,{children:`공분산`}),`, 즉 불확실성과 그 상호 관계를 담은 표입니다. 스캔에서는 채택된 점마다 그 잔차와 `,(0,n.jsx)(`em`,{children:`야코비안`}),`이 옵니다. 야코비안은 포즈가 조금 바뀔 때 잔차가 어떻게 변하는지를 나타냅니다.`]}),(0,n.jsxs)(n.Fragment,{children:[`필터는 예측에 비해 스캔을 얼마나 믿을지를 나타내는 `,(0,n.jsx)(`em`,{children:`이득`}),`을 계산하고, 이로부터 보정량을 구합니다. 핵심은 여기서 멈추지 않는다는 것입니다. 보정한 포즈로 옮겨 가서 그 포즈에서 잔차와 야코비안을 다시 계산하고 다시 풉니다. 이때 기준은 언제나 처음의 같은 예측입니다. 보정량이 아주 작아지거나(0.001 미만) 세 번 반복할 때까지(`,(0,n.jsx)(`code`,{children:`max_iteration: 3`}),`) 이를 되풀이합니다.`]}),(0,n.jsx)(n.Fragment,{children:`결과는 이 스캔에 대해 보정된 상태와 더 작아진 불확실성입니다. 보통 첫 반복이 대부분의 일을 하고 이후 반복이 다듬습니다. 보정된 포즈는 이어서 스캔을 지도에 놓는 데 쓰입니다(10강).`})],tryIt:(0,n.jsx)(n.Fragment,{children:`“다음 반복”을 한 번씩 눌러 보세요. 회색 점선이 사전값(0.3), 초록 선이 참값(1.1)입니다. 1회 반복에서 0.300이 약 0.932로 뛰고, 2회에서 1.092, 3회에서 1.112가 됩니다. 마지막 걸음(약 0.021)이 여전히 0.001보다 크므로 표시값이 “중단: 3회 반복”이 됩니다. 4회째 반복을 하면 수렴하지만, 추정값은 약 0.00001밖에 바뀌지 않습니다.`}),misconception:(0,n.jsxs)(n.Fragment,{children:[`“반복이란 새 데이터로 필터를 여러 번 돌리는 것이다.” 모든 반복은 `,(0,n.jsx)(`em`,{children:`같은`}),` 스캔과 `,(0,n.jsx)(`em`,{children:`같은`}),` 예측을 씁니다. 바뀌는 것은 잔차를 선형화하는 기준점뿐입니다.`]}),summary:[(0,n.jsx)(n.Fragment,{children:`갱신은 IMU 예측과 스캔 잔차를 각각의 불확실성에 따라 저울질합니다.`}),(0,n.jsx)(n.Fragment,{children:`잔차가 비선형이므로 FAST-LIO는 개선된 추정값에서 다시 선형화하고 다시 풉니다.`}),(0,n.jsx)(n.Fragment,{children:`이 설정에서는 보정량이 0.001 미만이 되거나 세 번 반복하면 멈춥니다.`})]},advanced:{objectives:[(0,n.jsx)(n.Fragment,{children:`반복 갱신을 사전 항이 있는 비용에 대한 가우스–뉴턴으로 쓰고, 어느 부분이 해석인지 구분합니다.`}),(0,n.jsx)(n.Fragment,{children:`정보 형태의 이득이 스캔당 수천 개의 잔차를 감당할 수 있게 하는 이유를 보입니다.`}),(0,n.jsx)(n.Fragment,{children:`정지 규칙과 공분산 갱신을 적용합니다.`})],model:[[`상태`,(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t,{children:String.raw`x = (R, p, v, b_g, b_a, g)`}),`와 LiDAR–IMU 외부 파라미터. 확인한 코드의 오차 상태는 23차원입니다. 위치 3, 회전 3, 외부 회전 3, 외부 이동 3, 속도 3, `,(0,n.jsx)(t,{children:`b_g`}),` 3, `,(0,n.jsx)(t,{children:`b_a`}),` 3, 2-구면 위의 중력 2입니다(I-4).`]})],[`사전값`,(0,n.jsxs)(n.Fragment,{children:[`전파(5강)에서 온 `,(0,n.jsx)(t,{children:String.raw`\hat x`}),`와 공분산 `,(0,n.jsx)(t,{children:`P`}),`(23 × 23).`]})],[`측정`,(0,n.jsxs)(n.Fragment,{children:[`스칼라 잔차 `,(0,n.jsx)(t,{children:`m`}),`개 `,(0,n.jsx)(t,{children:`r_j`}),`(m), 야코비안 `,(0,n.jsx)(t,{children:`H`}),`(m × 23), 잡음 `,(0,n.jsx)(t,{children:String.raw`R = \sigma^2 I_m`}),`. 잔차들은 서로 독립입니다.`]})],[`다양체`,(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t,{children:String.raw`\boxplus`}),`는 오차 상태 증분을 적용하고(회전은 Exp로), `,(0,n.jsx)(t,{children:String.raw`\boxminus`}),`는 그 역입니다. 선형화는 이 국소 좌표에서 이루어집니다.`]})],[`가정`,(0,n.jsxs)(n.Fragment,{children:[`가우스 사전값과 잡음. 평면 대응은 현재 반복값에서 7–8강으로 구합니다. 외부 파라미터는 고정(`,(0,n.jsx)(`code`,{children:`extrinsic_est_en: false`}),`)이므로 그 `,(0,n.jsx)(t,{children:`H`}),` 열은 0입니다.`]})]],steps:[{title:`입력`,text:(0,n.jsxs)(n.Fragment,{children:[`사전값 `,(0,n.jsx)(t,{children:String.raw`\hat x, P`}),`. 반복은 `,(0,n.jsx)(t,{children:String.raw`x^0 = \hat x`}),`에서 시작합니다.`]})},{title:`선형화`,text:(0,n.jsxs)(n.Fragment,{children:[`반복값 `,(0,n.jsx)(t,{children:String.raw`x^i`}),`에서 잔차와 그 야코비안을 계산합니다.`]}),tex:String.raw`r(x^i \boxplus \delta) \approx r_i + H_i\,\delta`},{title:`이득`,text:(0,n.jsxs)(n.Fragment,{children:[`두 형태는 대수적으로 같습니다. 첫 형태는 23 × 23 행렬을 역행렬로 계산하고(`,(0,n.jsx)(t,{children:`R`}),`는 대각), 둘째 형태라면 m × m 행렬의 역행렬이 필요합니다.`]}),tex:String.raw`K = \big(H_i^\top R^{-1} H_i + P^{-1}\big)^{-1} H_i^\top R^{-1} = P H_i^\top \big(H_i P H_i^\top + R\big)^{-1}`},{title:`보정`,text:(0,n.jsxs)(n.Fragment,{children:[`새 반복값은 직전 반복값이 아니라 `,(0,n.jsx)(`em`,{children:`사전값`}),`에서 잽니다(벡터 공간 형태입니다. 다양체에서는 차이가 `,(0,n.jsx)(t,{children:String.raw`\boxminus`}),`가 되고 코드는 그 연산의 야코비안을 덧붙이지만 여기서는 생략합니다).`]}),tex:String.raw`x^{i+1} = \hat x - K\big(r_i + H_i\,(\hat x - x^i)\big)`},{title:`정지`,text:(0,n.jsx)(n.Fragment,{children:`걸음이 작아지거나 반복 한도에 이를 때까지 “선형화”부터 되풀이합니다(설정값).`}),tex:String.raw`\lVert x^{i+1} - x^{i} \rVert < \epsilon = 0.001 \quad\text{or}\quad i + 1 = 3`},{title:`출력`,text:(0,n.jsx)(n.Fragment,{children:`마지막 반복값에서의 상태와 공분산. 설명을 위한 해석: 이것은 아래 MAP 문제의 가우스–뉴턴 해이며, 코드가 배치 최적화기를 호출하지는 않습니다.`}),tex:String.raw`P^{+} = (I - K H)\,P,\qquad \delta x^\ast = \arg\min_{\delta x}\ \lVert \delta x \rVert^2_{P^{-1}} + \textstyle\sum_j \lVert r_j(\hat x \boxplus \delta x) \rVert^2_{R_j^{-1}}`}],example:(0,n.jsxs)(n.Fragment,{children:[`인터랙티브의 1차원 문제입니다. 사전값 `,(0,n.jsx)(t,{children:String.raw`\hat x = 0.3`}),`, `,(0,n.jsx)(t,{children:String.raw`P = 0.5^2`}),`, 측정 `,(0,n.jsx)(t,{children:String.raw`z = 2\sin(1.1) + 0.02 = 1.8024`}),`, `,(0,n.jsx)(t,{children:String.raw`h(x) = 2\sin x`}),`, `,(0,n.jsx)(t,{children:String.raw`R = 0.05^2`}),`. 1회 반복: `,(0,n.jsx)(t,{children:String.raw`H = 2\cos 0.3 = 1.911`}),`, `,(0,n.jsx)(t,{children:String.raw`K = 0.25 \cdot 1.911/(1.911^2 \cdot 0.25 + 0.0025) = 0.522`}),`, `,(0,n.jsx)(t,{children:String.raw`x^1 = 0.3 + 0.522\,(1.8024 - 0.5910) = 0.932`}),`. 일반 EKF라면 여기서 멈추며, 최적값보다 0.18 모자랍니다. 2회와 3회 반복은 1.0915와 1.1121을 줍니다. 걸음 0.021이 여전히 0.001보다 커서 3회 한도에서 멈춥니다. 수렴값 1.11208은 4회 반복에서 걸음 1.3 × 10⁻⁵로 도달합니다. 사후 표준편차는 0.5에서 0.056으로 줄어듭니다. 최적값이 1.1이 아닌 것은 측정에 +0.02의 잡음이 있고 사전값이 약간 끌어당기기 때문입니다.`]}),paper:(0,n.jsx)(n.Fragment,{children:`FAST-LIO는 긴밀 결합 반복 오차 상태 칼만 필터와, 측정 개수가 아니라 상태 차원에 비용이 의존하는 이득 공식을 도입했습니다(FAST-LIO 초록). FAST-LIO2는 같은 필터를 유지하며 원시 점을 입력합니다(FAST-LIO2). MAP 형식은 설명을 위한 해석이며, 이 사이트에서도 그렇게 표시합니다.`}),site:(0,n.jsxs)(n.Fragment,{children:[`인터랙티브는 다양체가 없는 벡터 공간의 스칼라 문제이며, `,(0,n.jsx)(t,{children:`P`}),`와 `,(0,n.jsx)(t,{children:`R`}),`가 고정되어 있습니다. SLAM Playground의 필터는 사전 항이 있는 가우스–뉴턴으로 (x, y, θ)를 추정합니다. 최대 4회 반복하고 1 mm / 1 mrad 미만에서 멈추며, Huber 가중 δ = 0.1 m, σ = 0.05 m를 쓰고, 가우스–뉴턴 헤시안 `,(0,n.jsx)(t,{children:`H`}),`로 `,(0,n.jsx)(t,{children:String.raw`P \leftarrow (H + P^{-1})^{-1}`}),`를 계산합니다. 자체 오도메트리 잡음을 가정하며, 시뮬레이션의 자이로 바이어스는 알지 못합니다.`]}),dataset:(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(`code`,{children:`update_iterated_dyn_share_modified`}),`(IKFoM 툴킷), `,(0,n.jsx)(`code`,{children:`max_iteration: 3`}),`, `,(0,n.jsx)(`code`,{children:`epsi = 0.001`}),`입니다(I-7). 잡음 설정 `,(0,n.jsx)(`code`,{children:`acc_cov 0.3`}),`, `,(0,n.jsx)(`code`,{children:`gyr_cov 0.03`}),`, `,(0,n.jsx)(`code`,{children:`b_acc_cov 1e-4`}),`, `,(0,n.jsx)(`code`,{children:`b_gyr_cov 1e-5`}),`가 전파를 통해 `,(0,n.jsx)(t,{children:`P`}),`를 정합니다(I-9). 저장소 설정과 실행 시점 스냅샷은 시간 오프셋과 스캔 주기가 서로 다르며(11강), 각 층에 어느 쪽을 썼는지는 기록되어 있지 않습니다.`]}),interactiveLink:(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(`em`,{children:`다음 반복`}),`이 `,(0,n.jsx)(t,{children:`i`}),`를 늘립니다. 회색 선이 `,(0,n.jsx)(t,{children:String.raw`\hat x`}),`, 곡선이 MAP 목적함수의 1차원 형태인 비용 `,(0,n.jsx)(t,{children:`J(x)`}),`입니다. 표시값 `,(0,n.jsx)(t,{children:String.raw`|\delta x|`}),`를 `,(0,n.jsx)(t,{children:String.raw`\epsilon = 0.001`}),`과 비교하고, `,(0,n.jsx)(t,{children:`i = 3`}),`(`,(0,n.jsx)(`code`,{children:`max_iteration`}),`)에서 “중단”이 나타납니다. `,(0,n.jsx)(t,{children:`P`}),`와 `,(0,n.jsx)(t,{children:`R`}),`는 `,(0,n.jsx)(t,{children:String.raw`0.5^2`}),`와 `,(0,n.jsx)(t,{children:String.raw`0.05^2`}),`로 고정입니다.`]}),check:{q:`한 스캔에서 채택된 잔차가 m = 2,000개이고 오차 상태는 23차원입니다. 정보 형태의 이득 K = (HᵀR⁻¹H + P⁻¹)⁻¹HᵀR⁻¹에서 역행렬을 구해야 하는 행렬의 크기는?`,options:[`2000 × 2000`,`23 × 23`,`2000 × 23`,`없음, R⁻¹은 대각`],answer:1,explain:(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t,{children:String.raw`H^\top R^{-1} H + P^{-1}`}),`는 23 × 23이고, 잔차가 독립이면 `,(0,n.jsx)(t,{children:String.raw`R^{-1}`}),`는 대각이라 역행렬이 간단합니다. 공분산 형태 `,(0,n.jsx)(t,{children:String.raw`P H^\top (H P H^\top + R)^{-1}`}),`라면 2000 × 2000 역행렬이 필요합니다.`]})}}},{beginner:{question:(0,n.jsx)(n.Fragment,{children:`새 스캔은 언제 지도의 일부가 될 수 있으며, 잘못된 자리에 놓으면 무엇이 잘못될까요?`}),analogy:(0,n.jsxs)(n.Fragment,{children:[`맞는 자리를 찾으면 바로 풀로 붙여 버리는 직소 퍼즐을 생각해 보세요. 먼저 조각을 이리저리 움직여 이미 놓인 조각들과 가장자리를 맞추고(`,(0,n.jsx)(`em`,{children:`정합`}),`), 그다음에야 붙입니다(`,(0,n.jsx)(`em`,{children:`삽입`}),`). 조각을 잘못된 자리에 붙이면 다음 조각들은 그 실수에 맞춰 놓이게 됩니다. `,(0,n.jsx)(`strong`,{children:`비유가 맞지 않는 부분:`}),` 지도 조각은 가장자리에서 만나는 것이 아니라 크게 겹치고, “풀”이 중복된 점을 솎아 내므로, 조금 어긋난 조각은 눈에 보이는 틈 대신 벽을 두껍게 만듭니다.`]}),story:[(0,n.jsxs)(n.Fragment,{children:[`7–9강은 `,(0,n.jsx)(`em`,{children:`스캔–지도 정합`}),`이라는 하나의 루프를 이루는 부분입니다. 이웃을 찾고, 잔차를 계산하고, 포즈를 갱신하고, 포즈가 더 바뀌지 않을 때까지 반복합니다. 정합은 “이 스캔을 찍을 때 로봇은 어디에 있었나?”라는 질문에 답합니다. 그다음 일이 `,(0,n.jsx)(`em`,{children:`삽입`}),`입니다. 그 포즈로 스캔의 점들을 월드로 옮겨 지도에 더하면, 다음 스캔은 맞춰 볼 표면을 더 많이 갖게 됩니다.`]}),(0,n.jsx)(n.Fragment,{children:`순서가 중요합니다. 포즈가 수렴하기 전에 스캔을 삽입하면 그 벽들이 실제 벽 옆에 놓이고, 지도에는 같은 벽의 사본이 둘 생기거나 두껍고 흐린 벽 하나가 생깁니다. 더 나쁜 것은 다음 스캔이 잘못된 사본에 맞춰져 오차를 되풀이할 수 있다는 점입니다. 지나가는 사람도 측정되어 삽입됩니다. 지도는 그들이 움직일 것을 알 수 없기 때문이며, 사람은 궤적처럼 남습니다.`}),(0,n.jsxs)(n.Fragment,{children:[`스캔마다 로봇은 왜곡 보정을 거쳐 0.3 m 격자로 솎은 점들(`,(0,n.jsx)(`code`,{children:`filter_size_surf`}),`)과 ikd-Tree 속 국소 지도를 갖고 있습니다. 9강의 갱신이 끝나면 월드에서의 회전과 위치, 곧 수렴한 포즈도 갖게 됩니다.`]}),(0,n.jsxs)(n.Fragment,{children:[`스캔의 모든 점을 수렴한 포즈로 월드 좌표로 변환해 지도에 제시합니다. 그 점의 0.3 m 복셀(`,(0,n.jsx)(`code`,{children:`filter_size_map`}),`)이 이미 충분히 채워져 있으면 그 점은 필요 없고, 그렇지 않으면 추가합니다. 이렇게 하면 지도의 밀도가 대체로 고르게 유지되어, 수백 번 본 벽에 중복된 점이 수백만 개씩 쌓이지 않습니다.`]}),(0,n.jsx)(n.Fragment,{children:`지도는 스캔 단위로 커지고, 새 스캔은 언제나 그 전에 삽입된 모든 것에 대해 정합됩니다. 따라서 최종 지도의 품질은 삽입에 쓴 포즈에 전적으로 달려 있습니다. FAST-LIO에는 루프 클로저가 없으므로 이미 삽입된 점을 나중에 옮기는 단계도 없습니다.`})],tryIt:(0,n.jsx)(n.Fragment,{children:`스캔(청록)은 지도(회색)에서 0.35 m, 4° 벗어난 상태로 시작하며, 잔차 제곱합은 4.81 m²입니다. 회전을 0°로 바꿔도 합은 4.00 m²입니다. x 방향 이동은 세로 벽의 잔차만 바꾸는데, 가로 벽 위의 점들은 벽을 따라 미끄러질 뿐이기 때문입니다. 이 오프셋에서 “스캔 삽입”을 누르면 주황색 사본이 이중 벽을 보여 줍니다. 지도를 초기화하고 “정합(3단계)”을 누른 뒤(합이 약 0.001 m²로 떨어짐) 다시 삽입하면, 이번에는 사본이 지도 위에 놓입니다.`}),misconception:(0,n.jsx)(n.Fragment,{children:`“지도에 점이 많을수록 좋은 지도다.” 틀린 포즈로 삽입한 점이나 움직이는 사람의 점은 지도를 나쁘게 만듭니다. 이런 점들은 나중 스캔이 맞춰지는 대상이 되기도 합니다.`}),summary:[(0,n.jsx)(n.Fragment,{children:`스캔은 먼저 정합하고(포즈를 수렴할 때까지 반복), 그 뒤에야 지도에 삽입합니다.`}),(0,n.jsx)(n.Fragment,{children:`삽입은 수렴한 포즈로 스캔을 변환하고, 0.3 m 복셀에 필요한 곳에만 점을 더합니다.`}),(0,n.jsx)(n.Fragment,{children:`FAST-LIO는 삽입된 점을 옮기지 않으므로, 틀린 포즈나 걷는 사람은 이중 벽이나 궤적으로 지도에 남습니다.`})]},advanced:{objectives:[(0,n.jsx)(n.Fragment,{children:`정합을 사전 항이 있는 스캔 포즈 최적화로, 이어서 삽입으로 씁니다.`}),(0,n.jsx)(n.Fragment,{children:`오차가 지도를 통해 앞으로는 전파되지만 뒤로는 결코 되돌려지지 않는 이유를 설명합니다.`}),(0,n.jsx)(n.Fragment,{children:`주어진 크기의 포즈 오차가 0.3 m 복셀 지도에서 어떻게 나타나는지 추정합니다.`})],model:[[`포즈`,(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t,{children:String.raw`T = (R, p) \in SE(3)`}),`: W에서의 스캔 포즈. `,(0,n.jsx)(t,{children:String.raw`T_k^\ast`}),`는 스캔 `,(0,n.jsx)(t,{children:`k`}),`에 대한 9강의 수렴 결과입니다.`]})],[`스캔`,(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t,{children:String.raw`\mathcal{S}_k`}),`: 몸체 좌표계의 왜곡 보정한 점, `,(0,n.jsx)(`code`,{children:`filter_size_surf`}),` = 0.3 m로 다운샘플링.`]})],[`지도`,(0,n.jsxs)(n.Fragment,{children:[`ikd-Tree 속의 `,(0,n.jsx)(t,{children:String.raw`\mathcal{M}_k`}),`, `,(0,n.jsx)(`code`,{children:`filter_size_map`}),` = 0.3 m의 트리 내부 다운샘플링.`]})],[`정적 세계 가정`,(0,n.jsx)(n.Fragment,{children:`측정된 모든 점은 움직이지 않는 표면에 속한다고 봅니다. 사람은 이 가정을 어기고 궤적을 남깁니다.`})],[`되먹임`,(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t,{children:String.raw`\mathcal{M}_{k+1}`}),`은 `,(0,n.jsx)(t,{children:String.raw`T_k^\ast`}),`에 의존하고, `,(0,n.jsx)(t,{children:String.raw`T_{k+1}^\ast`}),`는 `,(0,n.jsx)(t,{children:String.raw`\mathcal{M}_{k+1}`}),`에 대해 정합됩니다. 오차는 지도를 통해 앞으로 흐르고, 뒤로 보정되지는 않습니다.`]})]],steps:[{title:`입력`,text:(0,n.jsxs)(n.Fragment,{children:[`스캔 `,(0,n.jsx)(t,{children:String.raw`\mathcal{S}_k`}),`, 지도 `,(0,n.jsx)(t,{children:String.raw`\mathcal{M}_k`}),`, 전파한 사전값 `,(0,n.jsx)(t,{children:String.raw`\hat T_k, P`}),`.`]})},{title:`정합`,text:(0,n.jsx)(n.Fragment,{children:`반복 갱신(9강)으로 풉니다. 사전 항이 있으므로 순수한 스캔 매칭이 아닙니다. 장면이 퇴화한 방향에서는 IMU 예측이 결정합니다.`}),tex:String.raw`T_k^\ast = \arg\min_{T}\ \lVert T \boxminus \hat T_k \rVert^2_{P^{-1}} + \textstyle\sum_j \big(n_j^\top (T\,p_j) + d_j\big)^2 / \sigma^2`},{title:`변환`,text:(0,n.jsx)(n.Fragment,{children:`잔차를 만들지 않은 점까지 포함해 스캔의 모든 점을 변환합니다.`}),tex:String.raw`p_{W,j} = R^\ast p_j + p^\ast`},{title:`삽입`,text:(0,n.jsx)(n.Fragment,{children:`0.3 m 트리 내부 복셀 다운샘플링.`}),tex:String.raw`\mathcal{M}_{k+1} = \mathcal{M}_k \cup \mathrm{voxel}_{0.3}\big(T_k^\ast\,\mathcal{S}_k\big)`},{title:`출력`,text:(0,n.jsxs)(n.Fragment,{children:[`커진 지도 `,(0,n.jsx)(t,{children:String.raw`\mathcal{M}_{k+1}`}),`와 포즈 `,(0,n.jsx)(t,{children:String.raw`T_k^\ast`}),`(오도메트리로 발행).`]})}],example:(0,n.jsxs)(n.Fragment,{children:[`벽에 수직인 위치 오차 `,(0,n.jsx)(t,{children:`e`}),`를 생각합니다. 복셀 크기와 같은 `,(0,n.jsx)(t,{children:`e = 0.3`}),` m이면 벽의 사본이 이웃 복셀 층에 놓여 벽이 이중으로 보입니다. `,(0,n.jsx)(t,{children:`e = 0.05`}),` m이고 점들이 복셀 안에 고르게 놓여 있다면, `,(0,n.jsx)(t,{children:String.raw`0.05/0.3 \approx 17\%`}),`가 다음 복셀로 넘어가고 나머지는 이미 채워진 복셀에 떨어집니다. 이 경우 벽은 이중이 되기보다 조금 두꺼워집니다. 방향 오차의 영향은 거리에 따라 커집니다. 옆 방향 어긋남이 `,(0,n.jsx)(t,{children:String.raw`\rho \tan\delta\theta`}),`이므로 1°는 1 m에서 0.017 m, 10 m에서 0.175 m입니다. 가까운 벽은 선명하게 남고 먼 벽은 흐려지거나 이중이 됩니다. 인터랙티브(기본값 0.35 m, 4°)에서는 스캔 점 78개의 합이 4.81 m²이고, “정합”을 한 번 누르면 0.005 m, 0.06°가 남으며 합은 약 0.001 m²입니다.`]}),paper:(0,n.jsx)(n.Fragment,{children:`FAST-LIO2는 원시 점을 지도에 직접 정합하고 ikd-Tree에서 지도를 증분 갱신하며, 지난 삽입을 고치지 않습니다(FAST-LIO2 초록). FAST-LIO2에는 루프 클로저가 없고, 확인한 패키지에도 없습니다(I-10).`}),site:(0,n.jsxs)(n.Fragment,{children:[`인터랙티브의 잔차는 이웃 다섯 개로 맞춘 평면이 아니라 가장 가까운 지도 선분까지의 거리입니다. “정합”은 실제 최적화가 아니라 개념적으로 감쇠시킨 걸음입니다(오프셋과 회전이 단계마다 4분의 1로 줄어들며 3단계). “삽입”은 복셀 솎기 없이 모든 점을 더합니다. SLAM Playground의 보행자 실험은 점유 격자를 `,(0,n.jsx)(`em`,{children:`참`}),` 포즈로 만들어, 궤적과 지우기를 포즈 오차와 분리해서 보여 줍니다.`]}),dataset:(0,n.jsx)(n.Fragment,{children:`공개한 FAST-LIO 층(2F, 3F, 6F, 8F)은 매핑 후 동적 점 제거를 포함한 후처리를 거쳤습니다. 일부 층에는 궤적 같은 줄무늬가 남아 있으며, Phase 5 감사에서는 원시 스캔 없이 이를 안전하게 지울 방법을 찾지 못했습니다. 층들은 x y z만 저장하고, 서버에 궤적이 없으며, 각 층에 쓴 파라미터 조합은 기록되어 있지 않습니다. 이 FAST-LIO 빌드에는 자체 동적 객체 제거 기능이 없습니다.`}),interactiveLink:(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(`em`,{children:`스캔 x 오프셋`}),`은 x 방향 이동 오차, `,(0,n.jsx)(`em`,{children:`스캔 회전`}),`은 방향 오차입니다. 표시값은 `,(0,n.jsx)(t,{children:String.raw`\sum_j r_j^2`}),`이며, `,(0,n.jsx)(t,{children:`r_j`}),`는 가장 가까운 선분까지의 거리입니다. `,(0,n.jsx)(`em`,{children:`정합`}),`은 9강의 반복을, `,(0,n.jsx)(`em`,{children:`스캔 삽입`}),`은 `,(0,n.jsx)(t,{children:String.raw`\mathcal{M} \cup T\mathcal{S}`}),`를 나타냅니다.`]}),check:{q:`위치는 맞지만 방향이 1° 틀린 상태로 스캔을 삽입했습니다. 삽입된 사본이 기존 벽에서 가장 멀리 떨어지는 곳은?`,options:[`로봇 바로 옆`,`모든 곳에서 같다`,`로봇에서 가장 먼 벽(10 m에서 약 0.17 m)`,`어디에도 없다: 복셀 다운샘플링이 지운다`],answer:2,explain:(0,n.jsxs)(n.Fragment,{children:[`회전 오차는 점을 옆으로 `,(0,n.jsx)(t,{children:String.raw`\rho\tan\delta\theta`}),`만큼 옮깁니다. 1 m에서 0.017 m, 10 m에서 0.175 m입니다. 0.3 m 복셀에서는 가까운 사본이 대부분 이미 채워진 복셀에 합쳐지고, 먼 사본은 벽을 두껍게 하거나 이중으로 만듭니다.`]})}}},{beginner:{question:(0,n.jsx)(n.Fragment,{children:`2F, 3F, 6F, 8F의 FAST-LIO 지도로 안전하게 할 수 있는 일은 무엇이고, 이 지도로부터 결론 내릴 수 없는 것은 무엇일까요?`}),analogy:(0,n.jsxs)(n.Fragment,{children:[`카메라 설정 기록이 없는 완성된 사진을 생각해 보세요. 보고, 대략 재고, 공유할 수는 있지만, 똑같은 사진을 다시 찍을 수는 없고 다른 카메라를 평가하는 기준으로 써서도 안 됩니다. `,(0,n.jsx)(`strong`,{children:`비유가 맞지 않는 부분:`}),` 여기서는 설정 일부를 압니다. 후보 설정 파일이 두 개 있습니다. 모르는 것은 어느 층에 어느 파일을 썼는지, 그리고 원시 기록입니다.`]}),story:[(0,n.jsx)(n.Fragment,{children:`FAST-LIO의 장점은 설계에서 나옵니다. IMU와 LiDAR를 긴밀하게 결합해 모든 스캔을 IMU 예측에 대해 보정하고, IMU의 움직임으로 스윕마다 왜곡을 되돌립니다. 그래서 보행 로봇의 덜컹거림에 강합니다. 특별한 “특징” 점을 먼저 고르지 않고 원시 점을 직접 정합하므로 벽, 바닥, 잡동사니가 모두 기여합니다. 그리고 ikd-Tree와 9강의 이득 형태 덕분에 스캔당 작업량이 일정 수준을 넘지 않아 빠릅니다.`}),(0,n.jsxs)(n.Fragment,{children:[`가장 큰 한계는 FAST-LIO에 `,(0,n.jsx)(`em`,{children:`루프 클로저`}),`가 없다는 것입니다. 로봇이 이미 본 곳으로 돌아와도 두 방문이 일치하는지 확인하지 않고, 나중에 경로를 보정하지도 않습니다. 넘어질 뻔한 뒤의 약간 틀린 방향이든 지나가던 사람이든, 초기에 지도에 들어간 오차는 그대로 남습니다. 또한 이 방법은 세계가 정적이라고 가정하며, 특징 없는 긴 복도에서는 벽이 복도 방향의 움직임을 구속하지 못할 수 있습니다(8강).`]}),(0,n.jsx)(n.Fragment,{children:`이 데이터셋에 기록된 것은 다음과 같습니다. 공개한 FAST-LIO 층은 점마다 x, y, z만 저장한 정제 지도이며, 공개 서버에 궤적이 없습니다. FAST-LIO 파라미터 파일은 저장소 설정과 실행 시점 스냅샷 두 개가 있는데, 서로 다릅니다. LiDAR–IMU 시간 오프셋이 한쪽은 −0.025 s, 다른 쪽은 0.0 s이고, 스캔 주기는 한쪽이 10.0, 다른 쪽이 6.37입니다. 각 층을 어느 파일로 만들었는지는 기록되어 있지 않습니다.`}),(0,n.jsx)(n.Fragment,{children:`지도를 똑같이 재현하려면 원시 LiDAR·IMU 기록, 정확한 파라미터, 소프트웨어 버전, 같은 정제 단계가 필요합니다. 이 층들의 원시 기록은 공개 서버에 없습니다. 따라서 지도를 다시 만들거나 다른 설정으로 다시 돌려 볼 수 없습니다. 비교할 정답 데이터가 없으므로 정확도도 알 수 없습니다.`}),(0,n.jsx)(n.Fragment,{children:`FAST-LIO 층은 확인, 시각화, 교육, 정성적 재사용에 쓰세요. 예를 들어 LiDAR 지도에서 복도가 어떻게 보이는지 살펴보는 데 적합합니다. 벤치마크나 다른 방법을 평가하는 기준으로는 쓰지 마세요. 이 사이트는 FAST-LIO 층과 LIO-SAM 층의 정확도를 비교한다고 주장하지 않습니다.`})],tryIt:(0,n.jsx)(n.Fragment,{children:`근거 표를 한 줄씩 읽어 보세요. 상태 열은 세 종류의 내용을 구분합니다. 알고리즘에 관한 사실(논문), 이 데이터셋에 관한 사실(확인한 설정과 소스), 그리고 알 수 없거나 없는 것입니다. 그 아래의 불일치 표도 보고, 뷰어에서 8F를 2F, 3F, 6F와 나란히 열어 보세요. 어느 층에도 궤적 레이어가 없습니다.`}),misconception:(0,n.jsx)(n.Fragment,{children:`“선명해 보이는 지도는 정확하다.” 선명한 벽은 연속한 스캔들이 국소적으로 서로 일치한다는 것을 보여 줄 뿐, 지도가 전역적으로 옳다는 것을 보여 주지는 않습니다. 루프 클로저 없이 서서히 쌓인 드리프트는 모든 벽이 또렷한 채로 층 전체를 휘게 할 수 있습니다.`}),summary:[(0,n.jsx)(n.Fragment,{children:`FAST-LIO는 빠르고 급격한 움직임에 강하지만 루프 클로저가 없어 초기 오차가 지도에 남습니다.`}),(0,n.jsx)(n.Fragment,{children:`이 층들은 설정이 모호하고(두 파일이 서로 다름), 원시 기록도 궤적도 정답 데이터도 없습니다.`}),(0,n.jsx)(n.Fragment,{children:`이 지도는 확인과 정성적 재사용에 적합하며, 벤치마크나 다른 방법의 평가에는 적합하지 않습니다.`})]},advanced:{objectives:[(0,n.jsx)(n.Fragment,{children:`공개 지도에 대해 알고리즘의 성질, 데이터셋 근거, 알 수 없는 것을 구분합니다.`}),(0,n.jsx)(n.Fragment,{children:`LiDAR–IMU 시간 어긋남의 크기를 어림합니다.`}),(0,n.jsx)(n.Fragment,{children:`정확한 재현에 필요한 것을 나열하고, 정확도 수치를 줄 수 없는 이유를 설명합니다.`})],model:[[`함수로 본 파이프라인`,(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t,{children:String.raw`\mathcal{M} = \mathrm{post}\big(F_{\theta, v}(Z)\big)`}),`: 원시 데이터 `,(0,n.jsx)(t,{children:`Z`}),`(LiDAR + IMU), 파라미터 `,(0,n.jsx)(t,{children:String.raw`\theta`}),`, 소프트웨어 버전 `,(0,n.jsx)(t,{children:`v`}),`, 후처리 `,(0,n.jsx)(t,{children:String.raw`\mathrm{post}`}),`.`]})],[`아는 것`,(0,n.jsxs)(n.Fragment,{children:[`후보 `,(0,n.jsx)(t,{children:String.raw`\theta`}),` 두 개(저장소 설정과 실행 시점 스냅샷). 외부 파라미터 `,(0,n.jsx)(`code`,{children:`extrinsic_R = diag(1,−1,−1)`}),`, `,(0,n.jsx)(`code`,{children:`extrinsic_T = [0.1710, 0.0, −0.0908]`}),` m. 확인한 소스(I-1~I-10)이며, 상위 커밋은 알 수 없습니다(`,(0,n.jsx)(`code`,{children:`.git`}),` 없음).`]})],[`없거나 모르는 것`,(0,n.jsxs)(n.Fragment,{children:[`각 층을 만든 `,(0,n.jsx)(t,{children:String.raw`\theta`}),`, 원시 `,(0,n.jsx)(t,{children:`Z`}),`(서버에 bag 없음), 궤적, 정답 데이터.`]})],[`불일치`,(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(`code`,{children:`time_offset_lidar_to_imu`}),` −0.025 대 0.0 s, `,(0,n.jsx)(`code`,{children:`scan_rate`}),` 10.0 대 6.37.`]})],[`알고리즘의 한계`,(0,n.jsx)(n.Fragment,{children:`루프 클로저 없음(I-10), 정적 세계 가정, 특징 없는 복도에서의 퇴화.`})]],steps:[{title:`목록 작성`,text:(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t,{children:String.raw`\mathrm{post}(F_{\theta,v}(Z))`}),`의 인자마다 있는지를 적습니다. `,(0,n.jsx)(t,{children:`Z`}),`는 없음, `,(0,n.jsx)(t,{children:String.raw`\theta`}),`는 모호함, `,(0,n.jsx)(t,{children:`v`}),`는 소스는 있으나 커밋은 모름, `,(0,n.jsx)(t,{children:String.raw`\mathrm{post}`}),`는 공개 노트에 설명되어 있습니다.`]})},{title:`시간 오프셋`,text:(0,n.jsxs)(n.Fragment,{children:[`IMU와 LiDAR 타임스탬프가 `,(0,n.jsx)(t,{children:String.raw`\Delta t`}),`만큼 어긋나면 예측과 왜곡 보정에 쓰는 움직임이 약 `,(0,n.jsx)(t,{children:String.raw`\omega\,\Delta t`}),`만큼 돌아가고, 거리 `,(0,n.jsx)(t,{children:String.raw`\rho`}),`의 점이 옆으로 밀립니다. 필터가 보정 단계에서 이를 일부 흡수하므로 이것은 지도 오차가 아니라 크기의 어림입니다.`]}),tex:String.raw`\delta\theta \approx \omega\,\Delta t,\qquad \delta s \approx \rho\,\omega\,\Delta t`},{title:`스캔 주기`,text:(0,n.jsxs)(n.Fragment,{children:[`포크에서 `,(0,n.jsx)(`code`,{children:`scan_rate`}),`는 스캔에 점별 시간 필드가 없을 때 점 시간을 균등하게 배치하는 데만 쓰입니다(I-8). XT16 처리기는 점별 타임스탬프를 해석합니다. 그 필드가 없는 기록이 있었는지는 기록되어 있지 않으므로, 이 불일치의 실제 영향은 알 수 없습니다.`]})},{title:`정확도`,text:(0,n.jsx)(n.Fragment,{children:`절대 궤적 오차를 구하려면 정답 궤적이 필요합니다. 정답 궤적은 없고, FAST-LIO 층은 추정 궤적조차 저장하지 않습니다.`}),tex:String.raw`\mathrm{ATE} = \sqrt{\tfrac{1}{N}\textstyle\sum_k \lVert \hat p_k - p_k \rVert^2}\quad\text{requires}\ p_k\ (\text{ground truth})`},{title:`출력`,text:(0,n.jsx)(n.Fragment,{children:`용도 분류: 확인, 시각화, 정성적 재사용에는 적합하고, 벤치마크나 정답 데이터로는 부적합하며, 이 서버에서 재현할 수 없습니다.`})}],example:(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t,{children:String.raw`\Delta t = 0.025`}),` s이고 예시 회전 속도가 `,(0,n.jsx)(t,{children:String.raw`\omega = 1`}),` rad/s(측정값 아님)라면 `,(0,n.jsx)(t,{children:String.raw`\delta\theta = 0.025`}),` rad = 1.43°이고, 10 m 거리의 점은 옆으로 0.25 m 밀립니다. `,(0,n.jsx)(t,{children:String.raw`\omega = 0.2`}),` rad/s에서는 0.005 rad = 0.29°, 0.05 m입니다. 따라서 이 불일치는 주로 빠르게 회전할 때 문제가 됩니다. 실제 기록의 회전 속도는 없으므로, 공개 층에 미친 영향은 정량화할 수 없습니다.`]}),paper:(0,n.jsx)(n.Fragment,{children:`장점은 논문의 설계 주장입니다. 반복 오차 상태 칼만 필터를 통한 긴밀 결합과 효율적인 이득 공식(FAST-LIO), 원시 점의 직접 정합과 ikd-Tree(FAST-LIO2)입니다. 논문은 자체 데이터로 평가하며, 이 사이트는 그 정확도 수치를 이 데이터셋에 옮겨 오지 않습니다.`}),site:(0,n.jsx)(n.Fragment,{children:`인터랙티브는 설정, 확인한 소스, 공개 메타데이터로 만든 근거 표와 불일치 표입니다. SLAM Playground에서는 “루프 클로저 없음”이라는 한계를 시뮬레이션으로 볼 수 있습니다. 루프 장면에서 필터의 최종 오차는 그대로 남고 그래프 모델은 이를 보정합니다. 이것은 FAST-LIO가 아니라 2차원 교육용 모델입니다.`}),dataset:(0,n.jsx)(n.Fragment,{children:`FAST-LIO 층 네 개는 x y z만 있고 궤적이 없는 처리·정제 지도입니다. 두 파라미터 파일은 수정 없이 준비해 두었으며, 어느 쪽도 특정 층의 원본이라고 주장하지 않습니다. 공개 서버에는 원시 bag, 궤적, 상위 원본이 없습니다. FAST-LIO 층과 LIO-SAM 층 사이의 정확도 비교는 주장하지 않습니다.`}),interactiveLink:(0,n.jsxs)(n.Fragment,{children:[`슬라이더는 없습니다. 근거 표의 상태 열이 목록 작성 단계(알고리즘 / 이 데이터셋 / 알 수 없음 또는 없음)에 대응하고, 불일치 표의 두 행이 서로 다르다고 알려진 `,(0,n.jsx)(t,{children:String.raw`\theta`}),`의 두 성분입니다.`]}),check:{q:`누군가 FAST-LIO 3F 지도와 같은 층의 새 지도 사이의 클라우드 간 거리를 계산해 새 방법의 오차라고 보고했습니다. 무엇이 잘못되었을까요?`,options:[`아무 문제 없다, FAST-LIO는 충분히 정확하다`,`3F 지도 자체의 정확도를 모르므로(정답 데이터 없음), 그 거리에는 두 지도의 오차가 섞여 있다`,`x y z 지도로는 클라우드 간 거리를 계산할 수 없다`,`두 지도의 단위가 다르다`],answer:1,explain:(0,n.jsx)(n.Fragment,{children:`기준은 평가 대상보다 정확해야 하고, 그 정확도가 알려져 있어야 합니다. 3F 지도는 정답 데이터도 궤적도 없고 설정도 기록되어 있지 않습니다. 두 지도 사이의 거리는 불일치를 잴 뿐, 어느 지도의 오차도 아닙니다.`})}}},{beginner:{question:(0,n.jsx)(n.Fragment,{children:`매핑 시스템은 왜 로봇이 2분 전에 어디에 있었는지에 대한 생각을 바꾸고 싶어 할까요?`}),analogy:(0,n.jsxs)(n.Fragment,{children:[`방향 감각이 조금 틀린 채로 걸음 수를 세며 한 블록을 돌면, 출발점에 돌아왔을 때 머릿속 지도에 틈이 생깁니다. `,(0,n.jsx)(`em`,{children:`필터`}),`는 잉크로 쓰는 공책과 같아서 지금 줄만 쓸 수 있습니다. `,(0,n.jsx)(`em`,{children:`스무더`}),`는 연필 스케치와 같아서, 출발한 모퉁이를 알아보면 경로 전체를 다시 그려 닫히게 하고 각 구간을 조금씩 휩니다. `,(0,n.jsx)(`strong`,{children:`비유가 맞지 않는 부분:`}),` 다시 그리기는 눈대중이 아니라 모든 측정을 그 불확실성으로 가중하는 계산이며, 모퉁이를 잘못 알아보면 경로 전체가 잘못된 방향으로 휩니다.`]}),story:[(0,n.jsxs)(n.Fragment,{children:[`FAST-LIO는 필터입니다. 현재 상태와 그 불확실성 하나만 유지하고, 스캔을 처리하고 나면 그 포즈는 확정되어 오차가 지도 속에 굳어 버립니다. 스무더는 과거의 여러 상태를 미지수로 유지하며, 새 정보가 오면 그 모두를 조정할 수 있습니다. 4F 지도에 쓴 LIO-SAM은 `,(0,n.jsx)(`em`,{children:`팩터 그래프`}),` 위에 만든 스무더입니다.`]}),(0,n.jsxs)(n.Fragment,{children:[`IMU와 LiDAR로 움직임을 추정하는 `,(0,n.jsx)(`em`,{children:`오도메트리`}),`의 작은 오차는 경로를 따라 쌓입니다. 긴 루프를 돌고 나면, 걸음 하나하나는 거의 맞았더라도 로봇 위치의 추정이 몇 미터씩 틀릴 수 있습니다. 그러면 지도에서 로봇이 출발한 복도가 약간 어긋난 채 두 번 나타납니다. 필터는 이를 고칠 수 없습니다. 오차를 만든 포즈들이 더는 바꿀 수 있는 변수가 아니기 때문입니다.`]}),(0,n.jsxs)(n.Fragment,{children:[`LIO-SAM은 모든 스캔을 변수로 두지 않습니다. 로봇이 충분히 움직이거나 돌았을 때의 스캔인 `,(0,n.jsx)(`em`,{children:`키프레임`}),`을 골라 각 키프레임의 포즈를 저장합니다. 연속한 키프레임 사이에는 IMU 사전적분(14강)과 LiDAR 오도메트리에서 온 구속 조건, 곧 `,(0,n.jsx)(`em`,{children:`팩터`}),`를 더합니다. 로봇이 어떤 장소를 다시 찾으면, 옛 키프레임과의 스캔 매칭으로 팩터를 하나 더 추가할 수 있습니다. 이것이 `,(0,n.jsx)(`em`,{children:`루프 클로저`}),`입니다.`]}),(0,n.jsx)(n.Fragment,{children:`모든 팩터를 함께 풉니다. 최적화기는 각 구속 조건을 그 불확실성으로 가중해, 모든 조건을 한꺼번에 가장 잘 만족하는 키프레임 포즈들을 찾습니다. 루프 팩터는 “이 두 포즈는 가깝다”고 말하고, 이를 만족시키려고 오차가 루프를 따라 뒤로 나뉘며 포즈마다 조금씩 움직입니다. LIO-SAM은 iSAM2를 쓰는데, 처음부터 전부 다시 풀지 않고 해를 증분으로 갱신합니다.`}),(0,n.jsx)(n.Fragment,{children:`새 정보가 오면 과거 포즈도 움직이므로 지도가 전역적으로 일관될 수 있고, 루프의 시작과 끝이 만납니다. 4F에서는 궤적의 시작점과 끝점 표시가 가까이 있습니다. 닫힌 루프와 들어맞는 모습이지만, 실행 중에 루프 팩터가 몇 개 추가되었는지 기록되어 있지 않으므로 이 사이트는 그 원인을 루프 클로저만으로 돌리지 않습니다.`})],tryIt:(0,n.jsx)(n.Fragment,{children:`기본 방향 드리프트 20°에서 시작–끝 간격은 약 3.76 m입니다. 드리프트를 45°로 올리거나(간격 약 8.0 m) 10°로 내려 보세요(약 1.9 m). 그다음 “루프 구속 조건 추가 후 최적화”를 켜면 청록색 경로가 닫히고 점선 오도메트리가 흐려집니다. 끝에 가까운 포즈가 가장 많이 움직이고, 시작에 가까운 포즈는 거의 움직이지 않는다는 점을 보세요.`}),misconception:(0,n.jsx)(n.Fragment,{children:`“LIO-SAM은 FAST-LIO에 단계 하나를 더한 것이다.” 추정기(필터링이 아닌 팩터 그래프 스무딩)도, 프런트엔드(원시 점이 아닌 에지·평면 특징)도 다른 별개의 방법입니다. 그리고 스무딩이 저절로 더 나은 것도 아닙니다. 잘못된 루프 구속 조건은 지도 전체를 왜곡할 수 있습니다.`}),summary:[(0,n.jsx)(n.Fragment,{children:`필터는 처리한 과거 포즈를 확정하고, 스무더는 과거 키프레임을 변수로 유지합니다.`}),(0,n.jsx)(n.Fragment,{children:`LIO-SAM은 IMU, LiDAR, 루프 클로저에서 온 팩터로 키프레임을 잇고, iSAM2로 함께 최적화합니다.`}),(0,n.jsx)(n.Fragment,{children:`루프 클로저는 쌓인 오차를 경로를 따라 뒤로 나눠 주어 지도를 전역적으로 일관되게 만들 수 있습니다.`})]},advanced:{objectives:[(0,n.jsxs)(n.Fragment,{children:[`필터링 밀도 `,(0,n.jsx)(t,{children:String.raw`p(x_n \mid Z_{1:n})`}),`와 스무딩 밀도 `,(0,n.jsx)(t,{children:String.raw`p(x_0, \dots, x_n \mid Z_{1:n})`}),`를 대비합니다.`]}),(0,n.jsx)(n.Fragment,{children:`루프 팩터가 오도메트리 팩터 사슬을 따라 폐합 오차를 어떻게 나누는지 유도합니다.`}),(0,n.jsx)(n.Fragment,{children:`키프레임과 희소성이 스무딩을 감당할 수 있게 하는 이유, 그리고 잘못된 루프 팩터 하나가 위험한 이유를 설명합니다.`})],model:[[`변수`,(0,n.jsxs)(n.Fragment,{children:[`키프레임 상태 `,(0,n.jsx)(t,{children:String.raw`X = \{x_0, \dots, x_n\}`}),`: 포즈이며, IMU 사전적분 부분에서는 속도와 IMU 바이어스도 포함합니다(14강).`]})],[`팩터`,(0,n.jsx)(n.Fragment,{children:`IMU 사전적분, LiDAR 오도메트리(하위 키프레임 슬라이딩 윈도와의 스캔 매칭), 루프 클로저(기준 구현에서는 ICP 기반), 그리고 여기서는 쓰지 않는 선택적 GPS 팩터.`})],[`잡음 모델`,(0,n.jsxs)(n.Fragment,{children:[`팩터 `,(0,n.jsx)(t,{children:`i`}),`마다 공분산 `,(0,n.jsx)(t,{children:String.raw`\Sigma_i`}),`의 가우스 잔차 `,(0,n.jsx)(t,{children:String.raw`r_i(X_i)`}),`를 가지며, 팩터끼리 독립입니다. 팩터 하나가 몇 개의 변수만 건드리므로 문제가 희소합니다.`]})],[`필터 대 스무더`,(0,n.jsxs)(n.Fragment,{children:[`필터는 단계 `,(0,n.jsx)(t,{children:`k`}),` 이후 `,(0,n.jsx)(t,{children:String.raw`x_{k}`}),`를 주변화하며, 주변화된 상태는 더는 바뀔 수 없습니다. 스무더는 이를 변수로 유지합니다.`]})],[`풀이기`,(0,n.jsx)(n.Fragment,{children:`iSAM2는 Bayes tree를 통해 해를 증분 갱신하고, 새 팩터의 영향을 받는 변수만 다시 선형화합니다.`})]],steps:[{title:`입력`,text:(0,n.jsx)(n.Fragment,{children:`움직임 임계값으로 고른 키프레임과 그 사이의 팩터.`})},{title:`정식화`,text:(0,n.jsx)(n.Fragment,{children:`가우스 팩터의 최대 사후 추정은 가중 최소제곱이 됩니다.`}),tex:String.raw`X^\ast = \arg\min_{X}\ \textstyle\sum_i \lVert r_i(X_i) \rVert^2_{\Sigma_i^{-1}}`},{title:`1차원 사슬`,text:(0,n.jsxs)(n.Fragment,{children:[`포즈 `,(0,n.jsx)(t,{children:String.raw`x_0 = 0`}),`(고정), …, `,(0,n.jsx)(t,{children:`x_n`}),`(m). 표준편차 `,(0,n.jsx)(t,{children:String.raw`\sigma`}),`의 오도메트리 측정 `,(0,n.jsx)(t,{children:`u_k`}),`, 그리고 `,(0,n.jsx)(t,{children:String.raw`x_n - x_0`}),`에 대한 표준편차 `,(0,n.jsx)(t,{children:String.raw`\sigma_L`}),`의 루프 측정 `,(0,n.jsx)(t,{children:`z`}),` 하나.`]}),tex:String.raw`\min_{x_1..x_n}\ \sum_{k=1}^{n} \frac{(x_k - x_{k-1} - u_k)^2}{\sigma^2} + \frac{(x_n - x_0 - z)^2}{\sigma_L^2}`},{title:`해`,text:(0,n.jsxs)(n.Fragment,{children:[`대칭성 때문에 모든 오도메트리 잔차가 같은 값 `,(0,n.jsx)(t,{children:`a`}),`를 갖고, 도함수를 0으로 두면 결과가 나옵니다. 포즈 `,(0,n.jsx)(t,{children:`k`}),`는 `,(0,n.jsx)(t,{children:String.raw`k\,a`}),`만큼 움직이므로, 루프 후반의 포즈가 가장 많이 움직입니다.`]}),tex:String.raw`e = \textstyle\sum_k u_k - z,\qquad a = -\dfrac{e\,\sigma^2}{n\,\sigma^2 + \sigma_L^2},\qquad x_k = \textstyle\sum_{m \le k} u_m + k\,a`},{title:`출력`,text:(0,n.jsx)(n.Fragment,{children:`보정된 키프레임 포즈. 지도는 키프레임 스캔들을 새 포즈에 놓아 다시 만듭니다.`})}],example:(0,n.jsxs)(n.Fragment,{children:[`1차원에서 갔다가 돌아오는 걸음 `,(0,n.jsx)(t,{children:`n = 4`}),`개, `,(0,n.jsx)(t,{children:String.raw`u = (5,\ 5,\ -5,\ -4.5)`}),` m를 생각합니다. 로봇은 실제로 출발점에 돌아왔고 루프 측정은 `,(0,n.jsx)(t,{children:`z = 0`}),`이므로 `,(0,n.jsx)(t,{children:`e = 0.5`}),` m입니다. `,(0,n.jsx)(t,{children:String.raw`\sigma_L = \sigma`}),`이면 `,(0,n.jsx)(t,{children:String.raw`a = -0.5/5 = -0.1`}),` m이고, `,(0,n.jsx)(t,{children:String.raw`x = (4.9,\ 9.8,\ 4.7,\ 0.1)`}),`가 됩니다. 0.5 m가 팩터 다섯 개에 0.1 m씩 나뉘고, 가중 비용은 `,(0,n.jsx)(t,{children:String.raw`0.25/\sigma^2`}),`에서 `,(0,n.jsx)(t,{children:String.raw`0.05/\sigma^2`}),`로 떨어집니다. 루프가 열 배 확실하면(`,(0,n.jsx)(t,{children:String.raw`\sigma_L = \sigma/10`}),`) `,(0,n.jsx)(t,{children:String.raw`a = -0.5/4.01 = -0.1247`}),` m이고 `,(0,n.jsx)(t,{children:String.raw`x_4 = 0.0012`}),` m입니다. 인터랙티브의 선형 재분배(60개 중 포즈 `,(0,n.jsx)(t,{children:`i`}),`가 3.76 m 간격의 `,(0,n.jsx)(t,{children:String.raw`i/60`}),`만큼 움직이므로 포즈 30은 1.88 m 이동)는 `,(0,n.jsx)(t,{children:String.raw`\sigma_L \to 0`}),`인 극한입니다.`]}),paper:(0,n.jsx)(n.Fragment,{children:`LIO-SAM은 상대·절대 측정과 루프 클로저를 팩터로 더할 수 있도록 LiDAR-관성 오도메트리를 팩터 그래프 위에 구성합니다. IMU 사전적분이 스캔의 왜곡을 보정하고 초기 추정을 주며, 키프레임을 하위 키프레임의 슬라이딩 윈도와 매칭하고, 그래프를 iSAM2로 증분 풀이합니다(LIO-SAM, iSAM2). README에 따르면 루프 클로저는 LeGO-LOAM에서 가져온 ICP 기반 방식입니다.`}),site:(0,n.jsxs)(n.Fragment,{children:[`인터랙티브는 최적화를 하지 않습니다. 폐합 간격을 루프를 따라 선형으로 나누는 단순화한 완화로, 위의 `,(0,n.jsx)(t,{children:String.raw`\sigma_L \to 0`}),` 극한에 해당하며 회전은 무시합니다. SLAM Playground의 그래프 모델은 실제로 최적화합니다. 0.6 m 또는 0.35 rad마다 키프레임을 두고, 오도메트리 팩터의 정보 행렬은 diag(400, 400, 900)이며, 15개 이상 이전 키프레임 중 2.5 m 이내의 가장 가까운 것에서 루프를 찾습니다. 루프는 검증을 통과해야 채택됩니다(50 % 이상 매칭, RMS 0.06 m 미만, 보정량 2 m 미만). 그다음 조밀 콜레스키로 SE(2) 가우스–뉴턴을 풀며, IMU 사전적분이나 iSAM2는 쓰지 않습니다.`]}),dataset:(0,n.jsxs)(n.Fragment,{children:[`4F는 루프 클로저를 켠 채(`,(0,n.jsx)(`code`,{children:`loopClosureEnableFlag`}),`) 0.5배속 재생으로 LIO-SAM으로 매핑했고, 매핑 후 후처리 필터를 적용했습니다. 추가된 루프 팩터의 수는 기록되어 있지 않으며, 약 0.317 m의 시작–끝 폐합을 루프 클로저만의 결과로 돌리지 않습니다. 공개 서버에는 LIO-SAM 소스 코드가 없었으므로, 이 내용은 논문과 저자의 README에 근거합니다. FAST-LIO 층과의 정확도 비교는 주장하지 않습니다.`]}),interactiveLink:(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(`em`,{children:`방향 드리프트`}),`는 60걸음 동안 쌓이는 전체 방향 오차(걸음당 드리프트/60)를 정하며, 이것이 시작–끝 간격으로 표시되는 폐합 오차 `,(0,n.jsx)(t,{children:`e`}),`를 만듭니다. `,(0,n.jsx)(`em`,{children:`루프 구속 조건 추가 후 최적화`}),`는 포즈 `,(0,n.jsx)(t,{children:`k`}),`에 `,(0,n.jsx)(t,{children:String.raw`a = -e/n`}),`인 보정 `,(0,n.jsx)(t,{children:String.raw`k\,a`}),`를 적용하고, 루프 잔차인 간격 표시값은 0이 됩니다.`]}),check:{q:`오도메트리 팩터 n = 4개(각각 σ)와 σ_L = σ인 루프 팩터로 이루어진 1차원 사슬에서 폐합 오차가 e = 0.5 m입니다. 마지막 포즈 x₄는 얼마나 움직일까요?`,options:[`0.5 m`,`0.4 m`,`0.1 m`,`0.125 m`],answer:1,explain:(0,n.jsxs)(n.Fragment,{children:[`팩터마다 `,(0,n.jsx)(t,{children:String.raw`a = -e/(n+1) = -0.1`}),` m이므로 `,(0,n.jsx)(t,{children:`x_4`}),`는 `,(0,n.jsx)(t,{children:String.raw`4a = -0.4`}),` m 움직입니다. 루프 측정도 정확하다고 보지 않으므로 나머지 0.1 m는 루프 팩터 자신의 잔차로 남습니다.`]})}}}],a=String.raw,o=[{beginner:{question:(0,n.jsx)(n.Fragment,{children:`LiDAR 스캔에서 정합할 가치가 있는 점은 어느 것이고, 컴퓨터는 벽이나 문이 무엇인지 모르면서 그 점들을 어떻게 고를까요?`}),analogy:(0,n.jsx)(n.Fragment,{children:`어둠 속에서 손가락으로 어떤 모양의 윤곽을 따라간다고 해 봅시다. 윤곽이 급하게 꺾이는 곳은 바로 느껴지지만, 곧은 구간에서는 어디나 똑같이 느껴집니다. 손가락은 “여기서 선이 얼마나 급하게 꺾이는가?”만 판단할 뿐 “이것이 문인가?”는 판단하지 않습니다. 이 비유가 맞지 않는 지점도 있습니다. LiDAR는 같은 링 위의 이웃 점과만 비교하므로, 잡음이 크거나 아주 먼 점은 우연히 “날카롭게” 보일 수 있습니다.`}),story:[(0,n.jsxs)(n.Fragment,{children:[`XT16에는 레이저 빔 16개가 위아래로 쌓여 있습니다. 헤드가 회전하면 빔마다 점들이 원 하나를 그리는데, 이것을 `,(0,n.jsx)(`strong`,{children:`링`}),`이라고 합니다. 한 링에서 이웃한 점들은 1도도 안 되는 간격으로 측정되었으므로 대개 같은 면, 즉 같은 벽·같은 바닥·같은 문틀 위에 있습니다. 이번 강의의 방법은 바로 이 순서 덕분에 가능합니다.`]}),(0,n.jsx)(n.Fragment,{children:`XT16의 한 회전(스윕)은 공칭 약 32,000개의 점을 돌려주고, 새 스윕은 1초에 약 10번 들어옵니다. 이 점을 모두 지도와 정합하면 계산이 비싸고, 대부분은 같은 정보를 되풀이합니다. 평평한 벽의 모든 점은 “여기 이 방향을 향한 벽이 있다”는 같은 말을 하기 때문입니다. 잘 고른 몇몇 점만으로도 훨씬 적은 비용으로 포즈를 거의 같은 정도로 구속할 수 있습니다.`}),(0,n.jsxs)(n.Fragment,{children:[`방법은 각 점마다 링을 따라 양옆의 이웃 몇 개를 보고 그 점과의 차이를 모두 더합니다. 평평한 벽에서는 왼쪽과 오른쪽 차이가 서로 상쇄되어 합, 곧 `,(0,n.jsx)(`strong`,{children:`곡률`}),`(거칠기) 점수가 작아지고, 그 점은 `,(0,n.jsx)(`strong`,{children:`평면 특징`}),`이 됩니다. 모서리나 문틀에서는 차이가 상쇄되지 않아 점수가 커지며, 그 점은 `,(0,n.jsx)(`strong`,{children:`에지 특징`}),`이 됩니다. 거리로 나누어 주기 때문에 가까운 점과 먼 점을 같은 기준으로 비교할 수 있습니다.`]}),(0,n.jsx)(n.Fragment,{children:`그다음 점수가 가장 큰 점들을 에지로, 가장 작은 점들을 평면으로 남깁니다. 모서리 하나가 모든 자리를 차지하지 않도록 링 전체에 고르게 퍼뜨리고, LOAM에서는 신뢰하기 어려운 점, 예를 들어 비스듬히 스치듯 보인 면이나 가리는 물체의 경계에 있는 점도 버립니다.`}),(0,n.jsx)(n.Fragment,{children:`이후 에지 점은 지도의 선에, 평면 점은 지도의 평면에 정합됩니다. 이 작은 특징 집합 두 개 덕분에 LIO-SAM의 LiDAR 오도메트리가 빨라집니다. 다만 이 데이터셋에서는 특징을 볼 수 없습니다. 4F 지도는 필터링을 거친 전체 스캔의 누적이고, 주행 당시의 특징 클라우드는 저장되지 않았습니다.`})],tryIt:(0,n.jsx)(n.Fragment,{children:`그림에서 링 하나가 모서리와 작은 문틀 오목부를 지나갑니다. 에지 임계값을 낮추면 모서리와 오목부 근처의 점이 더 많이 에지가 됩니다. 평면 임계값을 높이면 모서리에서 먼 점들이 평면으로 분류되기 시작합니다. 두 개수를 지켜보세요. 임계값이 너무 느슨하면 약한 특징이 많이 남고, 너무 엄격하면 거의 남지 않습니다.`}),misconception:(0,n.jsx)(n.Fragment,{children:`“특징은 문 같은 물체다.” 특징은 링을 따라 본 주변이 급하게 꺾였거나(에지) 평평한(평면) 개별 점입니다. 문틀은 에지 점을 몇 개 만들지만, 방법은 그것이 문이라는 사실을 결코 알지 못합니다.`}),summary:[(0,n.jsx)(n.Fragment,{children:`LiDAR 링에서 이웃한 점들은 대개 같은 면 위에 있으므로, 그 차이가 면이 얼마나 급하게 꺾이는지를 드러냅니다.`}),(0,n.jsx)(n.Fragment,{children:`곡률 점수가 크면 에지 점, 작으면 평면 점이며, 각각 몇 개만 링 전체에 퍼지도록 남깁니다.`}),(0,n.jsx)(n.Fragment,{children:`에지는 선에, 평면은 평면에 정합되며, 4F 주행의 특징 클라우드와 임계값은 공개 데이터셋에 포함되어 있지 않습니다.`})]},advanced:{objectives:[(0,n.jsxs)(n.Fragment,{children:[`곡률 점수 `,(0,n.jsx)(t,{children:a`c_k`}),`를 계산하고, 거리로 정규화하는 이유를 설명한다.`]}),(0,n.jsx)(n.Fragment,{children:`임계값에 의한 선택과 링 전체로의 분산, 신뢰하기 어려운 점을 버리는 이유를 설명한다.`}),(0,n.jsx)(n.Fragment,{children:`점–선 거리와 점–평면 거리를 유도하고, 각각이 어떤 움직임을 구속하는지 말한다.`})],model:[[`입력`,(0,n.jsxs)(n.Fragment,{children:[`링별로 정리된 왜곡 보정 스캔. 점 `,(0,n.jsx)(t,{children:a`r_k \in \mathbb{R}^3`}),`는 LiDAR 좌표계(m)에 있습니다. LIO-SAM은 IMU로 왜곡을 보정하지만, 사용하는 기준 시각은 이 사이트에서 검증하지 않았습니다.`]})],[`이웃`,(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t,{children:a`S_k`}),`: 같은 링 위의 연속한 점들로, `,(0,n.jsx)(t,{children:`k`}),`의 양쪽에 절반씩 있습니다(교구는 한쪽에 4개씩 사용).`]})],[`가정`,(0,n.jsx)(n.Fragment,{children:`가림 경계나 스치는 각도가 링을 끊지 않는 한, 이웃은 국소적으로 매끈한 같은 면 위에 있습니다. LOAM은 그런 경우를 버립니다.`})],[`잡음`,(0,n.jsxs)(n.Fragment,{children:[`거리 잡음 `,(0,n.jsx)(t,{children:a`\sigma_r`}),`는 평평한 면에서도 `,(0,n.jsx)(t,{children:a`c_k`}),`를 대략 `,(0,n.jsx)(t,{children:a`\sigma_r / \lVert r_k \rVert`}),`만큼 올리므로, 평면 임계값은 이 바닥값보다 커야 합니다.`]})],[`정합 모델`,(0,n.jsxs)(n.Fragment,{children:[`에지 점 → 근처 지도 에지 점 두 개 `,(0,n.jsx)(t,{children:`a, b`}),`를 지나는 선, 평면 점 → 근처 지도 평면 점들에 맞춘 평면 `,(0,n.jsx)(t,{children:a`(n, q)`}),`. 두 잔차 모두 단위는 m입니다.`]})]],steps:[{title:`입력`,text:(0,n.jsx)(n.Fragment,{children:`왜곡 보정한 스캔의 링 하나. 점들은 LiDAR 좌표계에 발사 순서대로 있습니다.`}),tex:a`\{ r_k \}_{k=1}^{K},\quad r_k \in \mathbb{R}^3\ \text{(LiDAR frame, m)}`},{title:`점수`,text:(0,n.jsx)(n.Fragment,{children:`이웃과의 차이를 더하고, 이웃 수와 거리로 나눕니다. 결과는 무차원입니다.`}),tex:a`c_k = \frac{1}{|S_k|\,\lVert r_k \rVert}\Big\lVert \textstyle\sum_{m \in S_k} (r_m - r_k) \Big\rVert`},{title:`분류와 분산`,text:(0,n.jsx)(n.Fragment,{children:`점수에 임계값을 적용하고, 링을 구역으로 나누어 구역마다 특징 수에 상한을 두어 시야 전체에 고르게 퍼뜨립니다.`}),tex:a`\mathcal{E} = \{ k : c_k > c_{\mathcal{E}} \},\qquad \mathcal{P} = \{ k : c_k < c_{\mathcal{P}} \}`},{title:`잔차`,text:(0,n.jsxs)(n.Fragment,{children:[`각 특징을 포즈 추정 `,(0,n.jsx)(t,{children:`T`}),`로 변환하고, 대응하는 지도의 선이나 평면까지의 거리를 잽니다.`]}),tex:a`d_{\mathcal{E}} = \frac{\lVert (p - a)\times(p - b) \rVert}{\lVert a - b \rVert},\qquad d_{\mathcal{P}} = n^\top (p - q),\qquad p = T r_k`},{title:`출력`,text:(0,n.jsx)(n.Fragment,{children:`하위 키프레임 국소 지도에 대해 거리 제곱합을 최소화하는 포즈가 LiDAR 오도메트리 추정값이 됩니다.`}),tex:a`T^\ast = \arg\min_T \textstyle\sum_{k \in \mathcal{E}} d_{\mathcal{E}}(T r_k)^2 + \sum_{k \in \mathcal{P}} d_{\mathcal{P}}(T r_k)^2`}],example:(0,n.jsxs)(n.Fragment,{children:[`점수를 스칼라 거리 형태(벡터 대신 거리)로 계산해 봅시다. 5.00 m 거리의 평평한 벽 위 점이 양쪽에 이웃 4개씩, 거리 5.02, 5.01, 5.01, 5.00 | 5.00, 5.01, 5.01, 5.02 m를 가지면 차이의 합은 0.08 m이고 `,(0,n.jsx)(t,{children:a`c = 0.08 / (8 \cdot 5.00) = 0.002`}),`로 교구의 기본 평면 임계값 0.004보다 작습니다. 안쪽 모서리에서는 5.00 m의 모서리 점이 양쪽에 4.6, 4.7, 4.8, 4.9 m의 이웃을 가지므로 차이의 합은 −2.0 m이고 `,(0,n.jsx)(t,{children:a`c = 2.0 / (8 \cdot 5.00) = 0.05`}),`로 기본 에지 임계값 0.025보다 큽니다. 정합에서는 `,(0,n.jsx)(t,{children:a`a = (0,0,0)`}),`, `,(0,n.jsx)(t,{children:a`b = (1,0,0)`}),`, `,(0,n.jsx)(t,{children:a`p = (0.5, 0.1, 0)`}),`일 때 `,(0,n.jsx)(t,{children:a`(p-a)\times(p-b) = (0, 0, 0.1)`}),`, `,(0,n.jsx)(t,{children:a`\lVert a-b \rVert = 1`}),`이므로 `,(0,n.jsx)(t,{children:a`d_{\mathcal{E}} = 0.1`}),` m입니다.`]}),paper:(0,n.jsx)(n.Fragment,{children:`LOAM(Zhang & Singh)이 곡률 기반 에지/평면 구분, 구역별 선택, 신뢰하기 어려운 점의 제거를 도입했습니다. LIO-SAM은 이 프런트엔드를 채택하고, 특징을 전역 지도 대신 하위 키프레임의 슬라이딩 윈도와 정합합니다(LIO-SAM 초록과 특징 추출 절).`}),site:(0,n.jsx)(n.Fragment,{children:`교구는 개념도입니다. 합성 기하를 지나는 평면 링 하나, 잡음 없음, 한쪽 4개 이웃을 쓰는 벡터 형태 점수, 자유로운 임계값이며, 구역 분할과 가림 검사는 없습니다. Playground의 필터 모델과 그래프 모델은 특징을 전혀 쓰지 않습니다. 다운샘플한 모든 스캔 점을 가장 가까운 지도 점 5개에 맞춘 선과 정합합니다(2-D 점–선).`}),dataset:(0,n.jsx)(n.Fragment,{children:`4F는 LIO-SAM으로 만들었지만, 특징 클라우드·임계값·전체 파라미터 파일은 배포 호스트에 없습니다. 4F 지도는 필터링을 거친 전체 스캔의 누적이며 스윕마다 약 20 %만 남았으므로, 이 사이트는 그 안의 어떤 점도 에지나 평면으로 표시할 수 없습니다.`}),interactiveLink:(0,n.jsxs)(n.Fragment,{children:[`에지 임계값 슬라이더가 `,(0,n.jsx)(t,{children:a`c_{\mathcal{E}}`}),`, 평면 임계값 슬라이더가 `,(0,n.jsx)(t,{children:a`c_{\mathcal{P}}`}),`입니다. 색칠된 점이 집합 `,(0,n.jsx)(t,{children:a`\mathcal{E}`}),`와 `,(0,n.jsx)(t,{children:a`\mathcal{P}`}),`, 개수가 그 크기이며, 고정된 링 기하가 `,(0,n.jsx)(t,{children:a`r_k`}),`와 `,(0,n.jsx)(t,{children:a`S_k`}),`를 정합니다.`]}),check:{q:`벽이 매끈하고 모서리가 거의 없는 긴 복도에서 가장 먼저 생기는 문제는 무엇일까요?`,options:[`에지 특징이 너무 많아 정합이 느려진다`,`에지 특징이 너무 적어 복도 방향 움직임이 잘 구속되지 않는다`,`평면 특징이 사라진다`],answer:1,explain:(0,n.jsx)(n.Fragment,{children:`벽과 바닥의 법선이 모두 복도 축에 수직이므로, 복도를 따라 미끄러져도 어떤 점–평면 거리도 변하지 않습니다. 그 방향은 에지나 가로지르는 구조만 구속합니다. 8강의 퇴화 문제입니다.`})}}},{beginner:{question:(0,n.jsx)(n.Fragment,{children:`두 키프레임 사이의 IMU 측정 수백 개를, 최적화기가 키프레임을 움직일 때마다 다시 계산하지 않아도 되는 구속 하나로 어떻게 바꿀 수 있을까요?`}),analogy:(0,n.jsx)(n.Fragment,{children:`그날 아침 출발한 곳을 기준으로 쓴 여행 일지를 생각해 보세요. “북동쪽으로 2 km, 그다음 왼쪽으로”. 나중에 누군가 출발 위치를 바로잡아도 일지 내용은 여전히 맞고, 길을 다시 걸을 필요가 없습니다. 이 비유는 보정에서 한계가 있습니다. 나중에 만보계가 조금 틀렸다는 것(바이어스)을 알게 되면 일지도 조금 틀립니다. 사전적분은 모든 걸음을 다시 읽는 대신 빠른 보정으로 이를 고치는데, 이 방법은 보정량이 작을 때만 통합니다.`}),story:[(0,n.jsxs)(n.Fragment,{children:[`IMU(관성 측정 장치)는 각속도와 가속도를 1초에 수백 번 보고합니다. 그림은 200 Hz에서 시작합니다. 이 샘플을 적분하면 회전·속도·위치의 변화를 얻습니다. 모든 샘플에는 `,(0,n.jsx)(`strong`,{children:`바이어스`}),`라는 작은 일정한 오프셋이 있고, 오차는 빠르게 커집니다. 일정한 가속도 바이어스 `,(0,n.jsx)(t,{children:`b`}),`는 `,(0,n.jsx)(t,{children:a`\tfrac12 b\,t^2`}),`의 위치 오차를 만듭니다.`]}),(0,n.jsxs)(n.Fragment,{children:[`팩터 그래프에서 키프레임 상태는 최적화기가 몇 번이고 움직이는 변수입니다. 일반 적분은 절대 포즈에서 출발해 월드 좌표계에서 중력을 뺍니다. 그러면 키프레임 `,(0,n.jsx)(t,{children:`i`}),`가 움직일 때마다 그 뒤의 모든 샘플을 다시 적분해야 합니다.`]}),(0,n.jsxs)(n.Fragment,{children:[`요령은 키프레임 `,(0,n.jsx)(t,{children:`i`}),`의 좌표계에서 0부터 적분하는 것입니다. 결과는 세 가지 요약값, ΔR(회전 변화), Δv(속도 변화), Δp(위치 변화)입니다. 이 값들은 샘플과 바이어스 추정값에만 의존하고, 키프레임 `,(0,n.jsx)(t,{children:`i`}),`가 월드의 어디에 있는지에는 의존하지 않습니다. 중력과 시작 속도는 요약값을 상태와 비교할 때에만 다시 더합니다.`]}),(0,n.jsx)(n.Fragment,{children:`최적화기는 바이어스도 추정합니다. 추정값이 조금 바뀌면, 저장한 요약값을 다시 적분하는 대신 미리 계산한 민감도, 곧 야코비안으로 보정합니다. 이 1차 보정은 변화가 작은 동안 정확합니다.`}),(0,n.jsxs)(n.Fragment,{children:[`결과는 키프레임 `,(0,n.jsx)(t,{children:`i`}),`와 `,(0,n.jsx)(t,{children:`j`}),` 사이의 `,(0,n.jsx)(`strong`,{children:`IMU 팩터`}),` 하나이며, 수백 개의 샘플을 대신합니다. LIO-SAM은 같은 IMU 데이터를 스캔 왜곡 보정과 LiDAR 오도메트리의 초기 추정에도 사용합니다.`]})],tryIt:(0,n.jsx)(n.Fragment,{children:`가속도계 바이어스를 키우고 구간을 늘려 보세요. 끝점 오차는 Δt의 제곱으로 커지므로 1 s에서 2 s로 늘리면 약 네 배가 됩니다. 자이로 바이어스를 더하고 방향 오차를 보세요. 자세를 1° 기울이면 중력이 수평 가속도로 새어 들어오는 것이 보입니다. 이어서 바이어스 갱신을 켜면, 보정한 끝점이 전체 재적분 결과와 거의 일치하고, 남는 작은 차이가 1차 보정의 대가입니다.`}),misconception:(0,n.jsx)(n.Fragment,{children:`“사전적분은 IMU를 더 정확하게 만든다.” 정보는 같고, 최적화가 저렴해지도록 재배열했을 뿐입니다. 바이어스·잡음·잘못된 자세는 여전히 오차를 만들며, 바뀌는 것은 계산 방식뿐입니다.`}),summary:[(0,n.jsx)(n.Fragment,{children:`사전적분은 두 키프레임 사이의 IMU 샘플을 첫 키프레임 좌표계의 ΔR, Δv, Δp로 요약합니다.`}),(0,n.jsx)(n.Fragment,{children:`요약값이 절대 시작 포즈에 의존하지 않으므로 키프레임을 옮겨도 재적분이 필요 없고, 작은 바이어스 변화는 1차로 반영합니다.`}),(0,n.jsx)(n.Fragment,{children:`그래프 최적화를 효율적으로 만들 뿐, 바이어스나 잡음을 없애지는 않습니다.`})]},advanced:{objectives:[(0,n.jsx)(n.Fragment,{children:`사전적분량 ΔR, Δv, Δp를 쓰고 키프레임 상태와의 관계를 세운다.`}),(0,n.jsx)(n.Fragment,{children:`1차 바이어스 보정을 적용하고, 언제 무너지는지 안다.`}),(0,n.jsx)(n.Fragment,{children:`바이어스와 기울어진 자세(중력 누설)로 인한 오차 증가를 추정한다.`}),(0,n.jsx)(n.Fragment,{children:`키프레임 사이 팩터를 FAST-LIO의 샘플별 전파와 비교한다.`})],model:[[`상태`,(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t,{children:a`x_i = (R_i, p_i, v_i, b_i)`}),`: 동체→월드 회전 `,(0,n.jsx)(t,{children:a`R_i \in SO(3)`}),`, 월드 좌표계 W의 위치(m)와 속도(m/s), 바이어스 `,(0,n.jsx)(t,{children:a`b = (b_g, b_a)`}),`(rad/s, m/s²).`]})],[`측정`,(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t,{children:a`\omega_m = \omega + b_g + n_g`}),`, `,(0,n.jsx)(t,{children:a`a_m = R^\top (a - g) + b_a + n_a`}),`. 둘 다 동체(IMU) 좌표계이며, 중력 부호는 1강의 규약을 따릅니다.`]})],[`가정`,(0,n.jsxs)(n.Fragment,{children:[`키프레임 사이에서 바이어스는 일정, 각 샘플은 구간 `,(0,n.jsx)(t,{children:a`\Delta t`}),` 동안 일정, LiDAR–IMU 외부 파라미터는 알려져 있음.`]})],[`잡음`,(0,n.jsxs)(n.Fragment,{children:[`백색 측정 잡음 `,(0,n.jsx)(t,{children:a`n_g, n_a`}),`와 바이어스 랜덤 워크. Forster 등은 요약값의 공분산 `,(0,n.jsx)(t,{children:a`\Sigma_{ij}`}),`를 전파하며, 이 사이트에서는 생략합니다.`]})],[`팩터`,(0,n.jsxs)(n.Fragment,{children:[`요약값과, `,(0,n.jsx)(t,{children:a`x_i, x_j`}),`로 예측한 같은 양 사이의 잔차를 `,(0,n.jsx)(t,{children:a`\Sigma_{ij}^{-1}`}),`로 가중합니다.`]})]],steps:[{title:`입력`,text:(0,n.jsxs)(n.Fragment,{children:[`두 키프레임 사이의 샘플과 현재 바이어스 추정값 `,(0,n.jsx)(t,{children:a`\bar b`}),`.`]}),tex:a`\{ \omega_k, a_k \}_{k=i}^{j-1},\qquad \bar b = (\bar b_g, \bar b_a)`},{title:`좌표계 i에서 적분`,text:(0,n.jsxs)(n.Fragment,{children:[`키프레임 `,(0,n.jsx)(t,{children:`i`}),`의 좌표계에서 0부터 시작합니다. 중력도 월드 포즈도 들어가지 않습니다.`]}),tex:a`\begin{aligned} \Delta R_{ij} &= \textstyle\prod_{k=i}^{j-1} \mathrm{Exp}\big((\omega_k - \bar b_g)\,\Delta t\big) \\ \Delta v_{ij} &= \textstyle\sum_{k=i}^{j-1} \Delta R_{ik}\,(a_k - \bar b_a)\,\Delta t \\ \Delta p_{ij} &= \textstyle\sum_{k=i}^{j-1} \big[\Delta v_{ik}\,\Delta t + \tfrac12 \Delta R_{ik}\,(a_k - \bar b_a)\,\Delta t^2\big] \end{aligned}`},{title:`상태와의 관계`,text:(0,n.jsx)(n.Fragment,{children:`중력과 초기 속도는 여기에서만 들어가므로, 상태가 움직여도 요약값 자체는 변하지 않습니다.`}),tex:a`\Delta R_{ij} \approx R_i^\top R_j,\quad \Delta v_{ij} \approx R_i^\top (v_j - v_i - g\,\Delta t_{ij}),\quad \Delta p_{ij} \approx R_i^\top \big(p_j - p_i - v_i \Delta t_{ij} - \tfrac12 g\,\Delta t_{ij}^2\big)`},{title:`바이어스 갱신`,text:(0,n.jsxs)(n.Fragment,{children:[`바이어스 추정값이 `,(0,n.jsx)(t,{children:a`\delta b`}),`만큼 바뀌면, 재적분 대신 저장한 야코비안으로 요약값을 보정합니다.`]}),tex:a`\Delta p_{ij}(\bar b + \delta b) \approx \Delta p_{ij}(\bar b) + \frac{\partial \Delta p_{ij}}{\partial b_a}\,\delta b_a + \frac{\partial \Delta p_{ij}}{\partial b_g}\,\delta b_g`},{title:`출력: IMU 팩터`,text:(0,n.jsxs)(n.Fragment,{children:[`양마다(회전·속도·위치) 잔차가 하나씩 생겨 상태 `,(0,n.jsx)(t,{children:`i`}),`와 `,(0,n.jsx)(t,{children:`j`}),` 사이에서 그래프에 들어갑니다. 아래는 위치 부분입니다.`]}),tex:a`r_{\Delta p} = R_i^\top\big(p_j - p_i - v_i \Delta t_{ij} - \tfrac12 g\,\Delta t_{ij}^2\big) - \Delta p_{ij}(\bar b + \delta b)`}],example:(0,n.jsxs)(n.Fragment,{children:[`200 Hz, `,(0,n.jsx)(t,{children:a`\Delta t_{ij} = 1`}),` s이면 샘플 200개가 팩터 하나가 됩니다. 보정하지 않은 가속도계 바이어스 0.1 m/s²는 `,(0,n.jsx)(t,{children:a`\tfrac12 \cdot 0.1 \cdot 1^2 = 0.05`}),` m, 2 s에서는 `,(0,n.jsx)(t,{children:a`\tfrac12 \cdot 0.1 \cdot 2^2 = 0.20`}),` m의 오차를 냅니다. 자이로 바이어스 1 °/s(0.0175 rad/s)는 1 s 뒤 1°의 방향 오차를 냅니다. 1° 기울기는 `,(0,n.jsx)(t,{children:a`9.81 \sin 1^\circ \approx 0.171`}),` m/s²의 중력을 수평 가속도에 남기고, 1 s 동안 `,(0,n.jsx)(t,{children:a`\tfrac12 \cdot 0.171 \cdot 1^2 \approx 0.086`}),` m로 0.1 m/s² 바이어스보다 큰 오차가 됩니다. 그림의 끝점 오차는 이 항들(그리고 방향 오차로 생기는 옆 방향 오차)이 합쳐진 값이므로 위의 어느 한 줄과도 같지 않습니다.`]}),paper:(0,n.jsx)(n.Fragment,{children:`사전적분은 Lupton과 Sukkarieh가 도입했고, Forster 등이 회전 다양체 위에서 닫힌 형태의 야코비안, 공분산 전파, 1차 바이어스 갱신으로 다시 정식화했습니다. LIO-SAM은 사전적분 IMU 팩터를 그래프에 넣고, IMU로 스캔 왜곡을 보정하고 LiDAR 오도메트리의 초기값을 주며, LiDAR 오도메트리로 IMU 바이어스를 추정합니다(LIO-SAM 초록).`}),site:(0,n.jsxs)(n.Fragment,{children:[`그림은 평면(요만), 잡음 없음, 일정한 가속도와 요 각속도입니다. 바이어스 야코비안은 유한 차분으로 수치 계산하고, 기울기는 전진 가속도에 `,(0,n.jsx)(t,{children:a`g \sin(\text{tilt})`}),`를 더합니다. Playground에는 IMU 사전적분이 없습니다. 그래프 모델은 대신 오도메트리 팩터(정보 행렬 diag(400, 400, 900))로 키프레임을 잇습니다.`]}),dataset:(0,n.jsx)(n.Fragment,{children:`4F 궤적에는 포즈가 4,013개 있습니다. 키프레임 수, IMU 잡음 파라미터, 전체 LIO-SAM 파라미터 파일은 배포 호스트에 기록되어 있지 않습니다. FAST-LIO(다른 층)는 이 팩터를 쓰지 않고, 필터 안에서 IMU 샘플 하나하나를 전파합니다(5강).`}),interactiveLink:(0,n.jsxs)(n.Fragment,{children:[`속도(rate) 슬라이더는 합에 들어가는 샘플 수 `,(0,n.jsx)(t,{children:a`n = f \cdot \Delta t_{ij}`}),`, 구간 슬라이더는 `,(0,n.jsx)(t,{children:a`\Delta t_{ij}`}),`, 바이어스 슬라이더는 `,(0,n.jsx)(t,{children:a`a_k - b_a`}),`와 `,(0,n.jsx)(t,{children:a`\omega_k - b_g`}),` 안의 `,(0,n.jsx)(t,{children:a`b_a`}),`와 `,(0,n.jsx)(t,{children:a`b_g`}),`입니다. 기울기는 `,(0,n.jsx)(t,{children:a`R_i`}),`의 오차이고, 토글은 `,(0,n.jsx)(t,{children:a`\delta b`}),` 항을 적용하며, 표시되는 차이가 그 선형화 오차입니다.`]}),check:{q:`최적화기가 키프레임 i를 0.3 m 옮기고 2° 회전시켰고, 바이어스 추정값은 그대로입니다. i와 j 사이의 IMU 팩터에는 무슨 일이 일어날까요?`,options:[`모든 샘플을 다시 적분해야 한다`,`ΔR, Δv, Δp는 그대로이고, 새 상태로 잔차만 다시 계산한다`,`1차 바이어스 보정을 적용해야 한다`],answer:1,explain:(0,n.jsxs)(n.Fragment,{children:[`요약값은 키프레임 `,(0,n.jsx)(t,{children:`i`}),`의 좌표계로 표현되어 있고 그 월드 포즈를 담고 있지 않습니다. 요약값 자체를 바꾸는 것은 바이어스 변화뿐입니다.`]})}}},{beginner:{question:(0,n.jsx)(n.Fragment,{children:`LIO-SAM은 자신이 아는 모든 것(IMU, LiDAR, 재방문)을 어떻게 풀 수 있는 하나의 문제로 적을까요?`}),analogy:(0,n.jsx)(n.Fragment,{children:`판 위의 핀들이 고무줄로 이어져 있다고 상상해 보세요. 핀은 키프레임 위치이고, 고무줄 하나하나는 두 핀이 얼마나 떨어져야 하는지 말하는 측정입니다. 팽팽한 고무줄은 신뢰도가 높은 측정입니다. 손을 놓으면 핀들은 전체 장력이 가장 작은 곳에 자리 잡습니다. 이 비유는 세부에서 한계가 있습니다. 실제 팩터는 3-D 회전과 이동(그리고 속도와 바이어스)을 구속하고, 그 “장력”은 측정 불확실성으로 가중한 제곱 오차입니다.`}),story:[(0,n.jsxs)(n.Fragment,{children:[`LIO-SAM은 모든 스캔을 미지수로 두지 않습니다. 직전 키프레임 이후 로봇이 충분히 이동하거나 회전했을 때 고른 `,(0,n.jsx)(`strong`,{children:`키프레임`}),`만 남깁니다. 키프레임마다 알 수 없는 상태가 있는데, 포즈이며 논문 정식화에서는 속도와 IMU 바이어스도 포함합니다. 이 상태들이 그래프의 `,(0,n.jsx)(`strong`,{children:`변수`}),`입니다.`]}),(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(`strong`,{children:`팩터`}),`는 변수 하나 또는 몇 개를 잇고 그들이 어떤 관계여야 하는지를 불확실성과 함께 말하는 측정 하나입니다. 사전(prior) 팩터는 첫 키프레임을 고정합니다. 그렇지 않으면 지도 전체가 자유롭게 미끄러질 수 있습니다. IMU 사전적분 팩터와 LiDAR 오도메트리 팩터는 연속한 키프레임을 잇고, 루프 팩터는 시간상 멀리 떨어진 두 키프레임을 이으며, GPS 팩터는 키프레임을 절대 위치 쪽으로 당깁니다.`]}),(0,n.jsxs)(n.Fragment,{children:[`팩터마다 변수 몇 개만 건드리므로 그래프는 `,(0,n.jsx)(`strong`,{children:`희소`}),`합니다. 대부분의 키프레임 쌍은 직접 연결되어 있지 않습니다. 해법은 이 점을 활용하며, 그래서 키프레임이 수천 개인 그래프도 빠르게 최적화할 수 있습니다.`]}),(0,n.jsx)(n.Fragment,{children:`모든 팩터의 잡음이 가우시안이면, 가장 가능성 높은 상태 집합은 각 오차를 분산으로 나눈 제곱 오차의 합을 최소화하는 집합입니다. 따라서 그래프를 구성하면 SLAM은 가중 최소제곱 문제가 되고, 16강에서 이를 풉니다.`}),(0,n.jsx)(n.Fragment,{children:`4F 주행은 LiDAR와 IMU를 사용했고 루프 클로저를 켰습니다. GPS는 알고리즘이 지원하지만 사용하지 않았습니다. 실내에서 기록한 데이터이기 때문입니다. 4F의 궤적 포즈 4,013개가 이런 그래프의 출력입니다.`})],tryIt:(0,n.jsx)(n.Fragment,{children:`그림에서 팩터 종류를 켜고 꺼 보세요. 사전 팩터가 없으면 그래프를 월드에 묶어 두는 것이 없습니다. 루프 클로저를 켜면 멀리 떨어진 키프레임 사이에 긴 간선이 생깁니다. GPS는 4F에서 사용하지 않아 회색으로 비활성입니다. 알고리즘에는 있지만 4F 주행에서는 쓰지 않았습니다.`}),misconception:(0,n.jsx)(n.Fragment,{children:`“알고리즘이 지원하는 팩터는 모두 사용되었다.” 4F 주행은 GPS를 사용하지 않았고, 추가된 루프 팩터 수는 기록되지 않았습니다.`}),summary:[(0,n.jsx)(n.Fragment,{children:`팩터 그래프에는 변수(키프레임 상태)와 팩터(그중 몇 개를 잇고 각자 불확실성을 가진 측정)가 있습니다.`}),(0,n.jsx)(n.Fragment,{children:`잡음이 가우시안이면 가장 가능성 높은 상태를 찾는 일은 희소한 가중 최소제곱 문제가 됩니다.`}),(0,n.jsx)(n.Fragment,{children:`LIO-SAM은 사전·IMU·LiDAR 오도메트리·루프·GPS 팩터를 지원하며, 4F 주행은 LiDAR와 IMU에 루프 클로저를 켜고 GPS 없이 진행했습니다.`})]},advanced:{objectives:[(0,n.jsx)(n.Fragment,{children:`LIO-SAM의 변수와 팩터 종류, 각 상태의 차원을 말한다.`}),(0,n.jsx)(n.Fragment,{children:`가우시안 팩터의 곱에서 최소제곱 비용을 유도한다.`}),(0,n.jsx)(n.Fragment,{children:`정보 행렬의 희소성과 사전 팩터의 역할(게이지 자유도)을 설명한다.`})],model:[[`변수`,(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t,{children:a`X = \{x_0, \dots, x_N\}`}),`, 키프레임마다 하나. 논문에서는 `,(0,n.jsx)(t,{children:a`x_i = (R_i, p_i, v_i, b_i)`}),`, 즉 3 + 3 + 3 + 6 = 15 자유도입니다.`]})],[`좌표계`,(0,n.jsx)(n.Fragment,{children:`월드 좌표계 W(지도), 동체 좌표계 B = IMU. LiDAR–IMU 외부 파라미터는 알려져 있고 고정이라고 가정합니다.`})],[`팩터`,(0,n.jsxs)(n.Fragment,{children:[`사전 `,(0,n.jsx)(t,{children:a`\phi_0`}),`, IMU 사전적분 `,(0,n.jsx)(t,{children:a`\phi^{\mathrm{IMU}}_{i,i+1}`}),`(14강), 하위 키프레임 윈도와의 특징 정합으로 얻은 상대 포즈인 LiDAR 오도메트리 `,(0,n.jsx)(t,{children:a`\phi^{L}_{i,i+1}`}),`(13강), 루프 `,(0,n.jsx)(t,{children:a`\phi^{\mathrm{loop}}_{ab}`}),`(17강), GPS `,(0,n.jsx)(t,{children:a`\phi^{\mathrm{GPS}}_i`}),`(LIO-SAM이 지원하지만 4F에서는 사용하지 않음).`]})],[`잡음`,(0,n.jsxs)(n.Fragment,{children:[`각 팩터는 공분산 `,(0,n.jsx)(t,{children:a`\Sigma_i`}),`의 가우시안이며, `,(0,n.jsx)(t,{children:`X`}),`가 주어지면 팩터들은 조건부 독립입니다.`]})],[`게이지`,(0,n.jsx)(n.Fragment,{children:`모든 키프레임을 같은 강체 변환(3-D에서 6 자유도)으로 옮겨도 상대 팩터는 변하지 않으므로, 해를 하나로 정하려면 사전 팩터가 필요합니다.`})]],steps:[{title:`키프레임 선택`,text:(0,n.jsx)(n.Fragment,{children:`포즈가 충분히 바뀌면 새 키프레임을 만듭니다. 4F 주행의 임계값은 기록되지 않았고, Playground는 0.6 m와 0.35 rad를 씁니다.`}),tex:a`\lVert p_k - p_{\text{last}} \rVert > d_{\min}\ \ \lor\ \ \angle\big(R_{\text{last}}^\top R_k\big) > \theta_{\min}`},{title:`팩터 추가`,text:(0,n.jsxs)(n.Fragment,{children:[`사후 확률은 팩터의 곱이며, 집합 `,(0,n.jsx)(t,{children:a`\mathcal{L}`}),`는 검증된 루프를 담습니다.`]}),tex:a`p(X \mid Z) \propto \phi_0(x_0) \textstyle\prod_i \phi^{\mathrm{IMU}}_{i,i+1}\, \phi^{L}_{i,i+1} \prod_{(a,b) \in \mathcal{L}} \phi^{\mathrm{loop}}_{ab}`},{title:`가우시안 팩터`,text:(0,n.jsx)(n.Fragment,{children:`각 팩터는 마할라노비스 거리 제곱의 지수 함수입니다.`}),tex:a`\phi_i(X_i) \propto \exp\!\big(-\tfrac12 \lVert r_i(X_i) \rVert^2_{\Sigma_i^{-1}}\big),\qquad \lVert r \rVert^2_{\Sigma^{-1}} = r^\top \Sigma^{-1} r`},{title:`음의 로그`,text:(0,n.jsx)(n.Fragment,{children:`곱을 최대화하는 것은 합을 최소화하는 것과 같습니다.`}),tex:a`-\log p(X \mid Z) = \tfrac12 \textstyle\sum_i \lVert r_i(X_i) \rVert^2_{\Sigma_i^{-1}} + \mathrm{const}`},{title:`출력: 희소 구조`,text:(0,n.jsx)(n.Fragment,{children:`정보 행렬의 블록은 어떤 팩터가 두 변수를 함께 이을 때만 0이 아닙니다. 16강의 해법이 이 희소성을 활용합니다.`}),tex:a`H_{ab} = \textstyle\sum_{i \,:\, a, b \in X_i} J_{i,a}^\top \Sigma_i^{-1} J_{i,b}`}],example:(0,n.jsxs)(n.Fragment,{children:[`루프 하나가 있는 키프레임 다섯 개의 사슬: 사전 1 + IMU 4 + LiDAR 오도메트리 4 + 루프 1 = 팩터 10개. 포즈만 두면 미지수는 5 × 6 = 30개, 논문의 전체 상태라면 5 × 15 = 75개입니다. 가중치가 중요합니다. 0.05 m의 잔차는 σ = 0.1 m일 때 `,(0,n.jsx)(t,{children:a`\tfrac12 (0.05/0.1)^2 = 0.125`}),`, σ = 0.01 m일 때 `,(0,n.jsx)(t,{children:a`\tfrac12 (0.05/0.01)^2 = 12.5`}),`로 100배의 비용이 됩니다.`]}),paper:(0,n.jsx)(n.Fragment,{children:`LIO-SAM 논문은 팩터 종류 네 가지(IMU 사전적분, LiDAR 오도메트리, 선택적 GPS, 루프 클로저)로 하나의 팩터 그래프를 만들고 iSAM2로 점진적으로 풉니다. 저자 구현이 이 작업을 모듈 사이에 어떻게 나누는지는 확인하지 않았습니다. LIO-SAM 소스 코드가 배포 호스트에 없으므로, 이 사이트는 논문과 README에만 근거합니다.`}),site:(0,n.jsx)(n.Fragment,{children:`그림은 개념도이며 해법이 없습니다. Playground의 LIO-SAM 영감 모델은 2-D 포즈(x, y, θ)만 쓰고, 정보 행렬 diag(400, 400, 900)의 오도메트리 팩터가 IMU 사전적분을 대신합니다. 사전 팩터 대신 키프레임 0을 고정하며, GPS와 iSAM2는 없습니다.`}),dataset:(0,n.jsxs)(n.Fragment,{children:[`4F: LiDAR + IMU, `,(0,n.jsx)(`code`,{children:`loopClosureEnableFlag`}),` 켬, GPS 사용하지 않음, 0.5배속 재생, `,(0,n.jsx)(`code`,{children:`mappingProcessInterval`}),` 0.0. 루프 팩터 수와 전체 파라미터 파일은 기록되지 않았습니다. 출력은 포즈 4,013개의 궤적입니다.`]}),interactiveLink:(0,n.jsxs)(n.Fragment,{children:[`토글마다 팩터 종류 하나를 더하거나 뺍니다. 사전 = `,(0,n.jsx)(t,{children:a`\phi_0`}),`, IMU = `,(0,n.jsx)(t,{children:a`\phi^{\mathrm{IMU}}`}),`, LiDAR 오도메트리 = `,(0,n.jsx)(t,{children:a`\phi^{L}`}),`, 루프 = `,(0,n.jsx)(t,{children:a`\phi^{\mathrm{loop}}`}),`. 비활성 GPS 토글은 4F 주행에 없는 `,(0,n.jsx)(t,{children:a`\phi^{\mathrm{GPS}}`}),`입니다.`]}),check:{q:`사전 팩터를 없애고 상대 팩터만 모두 남기면 최소제곱 문제는 어떻게 될까요?`,options:[`여전히 해가 하나로 정해진다`,`모든 키프레임을 함께 옮겨도 비용이 같으므로 정규 방정식이 특이해진다`,`루프 팩터만으로 전역 위치가 고정된다`],answer:1,explain:(0,n.jsxs)(n.Fragment,{children:[`상대 팩터(오도메트리, IMU, 루프)는 상태 사이의 차이만 구속합니다. 절대 팩터가 없으면 전역 강체 변환을 관측할 수 없고(게이지 자유도), `,(0,n.jsx)(t,{children:a`H`}),`에 영공간이 생깁니다.`]})}}},{beginner:{question:(0,n.jsx)(n.Fragment,{children:`측정들이 서로 어긋날 때 최적화기는 누구를 믿을지 어떻게 정하고, 그 답은 얼마나 확실할까요?`}),analogy:(0,n.jsx)(n.Fragment,{children:`두 친구가 같은 거리를 잽니다. 한 명은 레이저 줄자로, 다른 한 명은 걸음 수로. 여러분은 걸음 수를 무시하지 않으면서도 레이저 줄자 쪽으로 기울고, 합친 추정은 어느 한쪽보다 낫습니다. 이 비유는 정직함에서 한계가 있습니다. 각 친구의 정확도를 올바로 밝혔을 때만 통합니다. “레이저 줄자”가 잘못 보정되어 있다면, 자신 있게 합친 결과는 자신 있게 틀린 답이 됩니다.`}),story:[(0,n.jsxs)(n.Fragment,{children:[`모든 팩터는 표준편차 σ로 쓰는 불확실성을 가집니다. 최적화기는 이것을 1/σ²의 `,(0,n.jsx)(`strong`,{children:`가중치`}),`로 바꿉니다. 따라서 σ를 절반으로 줄이면 가중치는 네 배가 되어, 정밀한 측정이 거친 측정보다 해를 더 세게 당깁니다.`]}),(0,n.jsxs)(n.Fragment,{children:[`가장 단순한 경우는 한 위치에 대한 두 측정 `,(0,n.jsx)(t,{children:a`x_1`}),`과 `,(0,n.jsx)(t,{children:a`x_2`}),`입니다. 최선의 추정은 가중 평균이고, 그 불확실성은 두 σ 어느 것보다도 작습니다. 독립적인 정보 두 개를 합치면 항상 도움이 됩니다.`]}),(0,n.jsx)(n.Fragment,{children:`실제 그래프에는 잔차가 수천 개 있고, 회전 때문에 비선형입니다. 가우스–뉴턴 방법은 이를 여러 번에 나누어 다룹니다. 현재 추정 주변에서 각 잔차를 직선으로 펴고(선형화), 보정량에 대한 선형 시스템 하나를 풀고, 보정을 적용한 뒤, 보정량이 아주 작아질 때까지 반복합니다.`}),(0,n.jsxs)(n.Fragment,{children:[`매 단계에서 푸는 행렬이 `,(0,n.jsx)(`strong`,{children:`정보 행렬`}),`입니다. 이를 역행렬로 바꾸면 결과의 근사 공분산을 얻어 각 포즈가 얼마나 확실한지 알 수 있습니다. 다만 가정한 잡음 모델이 옳은 범위 안에서만 그렇습니다.`]}),(0,n.jsx)(n.Fragment,{children:`LIO-SAM은 키프레임마다 그래프 전체를 다시 풀 여유가 없습니다. 백엔드인 iSAM2는 이전 해를 유지하고, 새 팩터가 영향을 주는 부분만 다시 처리합니다. 그래서 최적화가 실시간에 충분할 만큼 빠릅니다.`})],tryIt:(0,n.jsxs)(n.Fragment,{children:[`σ₁ = σ₂로 두면 결합 추정은 가운데에 오고 σ는 √2배 줄어듭니다. 이어서 σ₂를 훨씬 작게 하면 추정이 `,(0,n.jsx)(t,{children:a`x_2`}),` 쪽으로 움직이고 결합 σ는 σ₂에 가까워집니다. 결합 곡선이 항상 두 입력 곡선보다 좁다는 점에 주목하세요.`]}),misconception:(0,n.jsx)(n.Fragment,{children:`“최적화는 참 포즈를 찾는다.” 팩터와 가정한 잡음에 가장 일관된 포즈를 찾을 뿐이며, 불확실성 추정도 그 가정만큼만 믿을 수 있습니다.`}),summary:[(0,n.jsx)(n.Fragment,{children:`각 팩터는 분산의 역수로 가중되므로 정밀한 측정이 더 크게 반영됩니다.`}),(0,n.jsx)(n.Fragment,{children:`가우스–뉴턴은 선형화·풀이·갱신을 반복하고, 정보 행렬의 역행렬이 결과의 불확실성을 근사합니다.`}),(0,n.jsx)(n.Fragment,{children:`iSAM2는 이를 점진적으로 만들어 새 팩터가 영향을 주는 부분만 다시 풉니다.`})]},advanced:{objectives:[(0,n.jsx)(n.Fragment,{children:`다양체 위 가우스–뉴턴 한 단계의 정규 방정식을 유도한다.`}),(0,n.jsx)(n.Fragment,{children:`정보 가중 결합을 특수한 경우로 얻고 손으로 계산한다.`}),(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t,{children:a`H^{-1}`}),`가 의미 있는 공분산이 되는 조건과, 상관되었거나 잘못된 잡음 모델이 과신을 만드는 이유를 말한다.`]})],model:[[`문제`,(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t,{children:a`X^\ast = \arg\min_X \sum_i \lVert r_i(X) \rVert^2_{\Sigma_i^{-1}}`}),`. 잔차는 각 팩터 고유의 단위(m, rad, m/s)를 가집니다.`]})],[`선형화`,(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t,{children:a`r_i(\bar X \boxplus \delta) \approx r_i(\bar X) + J_i \delta`}),`. `,(0,n.jsx)(t,{children:a`\delta`}),`는 접공간에 있고 `,(0,n.jsx)(t,{children:a`\boxplus`}),`는 다양체로의 리트랙션입니다.`]})],[`잡음`,(0,n.jsxs)(n.Fragment,{children:[`팩터 사이에 독립인 가우시안 `,(0,n.jsx)(t,{children:a`\Sigma_i`}),`. 단순 제곱 비용은 이상치를 낮게 가중하지 않으므로, σ가 작은 잘못된 팩터 하나가 해를 왜곡할 수 있습니다.`]})],[`공분산`,(0,n.jsxs)(n.Fragment,{children:[`최적점에서의 라플라스 근사: `,(0,n.jsx)(t,{children:a`\mathrm{Cov}(X^\ast) \approx H^{-1}`}),`. 최적점 근처에서, 그리고 잡음 모델이 옳을 때만 유효합니다.`]})],[`게이지`,(0,n.jsxs)(n.Fragment,{children:[`사전 팩터로 고정합니다(15강). 그렇지 않으면 `,(0,n.jsx)(t,{children:`H`}),`가 특이합니다.`]})]],steps:[{title:`입력`,text:(0,n.jsxs)(n.Fragment,{children:[`15강의 그래프와 선형화 지점 `,(0,n.jsx)(t,{children:a`\bar X`}),`(현재 추정).`]})},{title:`선형화`,text:(0,n.jsx)(n.Fragment,{children:`모든 잔차와 야코비안을 쌓습니다.`}),tex:a`r(\bar X \boxplus \delta) \approx r(\bar X) + J\delta`},{title:`정규 방정식`,text:(0,n.jsxs)(n.Fragment,{children:[`선형화한 비용을 최소화합니다. 왼쪽 행렬이 정보 행렬 `,(0,n.jsx)(t,{children:`H`}),`입니다.`]}),tex:a`\big(J^\top \Sigma^{-1} J\big)\,\delta = -J^\top \Sigma^{-1} r`},{title:`갱신과 반복`,text:(0,n.jsx)(n.Fragment,{children:`증분을 적용하고 작아질 때까지 반복합니다.`}),tex:a`\bar X \leftarrow \bar X \boxplus \delta,\qquad \text{stop when } \lVert \delta \rVert < \varepsilon`},{title:`불확실성`,text:(0,n.jsx)(n.Fragment,{children:`수렴하면 정보 행렬의 역행렬이 공분산을 근사합니다.`}),tex:a`\mathrm{Cov}(X^\ast) \approx H^{-1},\qquad H = J^\top \Sigma^{-1} J`},{title:`점진적 갱신(iSAM2)`,text:(0,n.jsxs)(n.Fragment,{children:[`새 팩터는 `,(0,n.jsx)(t,{children:`H`}),`에 항 하나를 더합니다. iSAM2는 베이즈 트리에서 영향을 받는 클리크만 다시 소거하고, 추정이 충분히 움직인 변수만 다시 선형화합니다.`]}),tex:a`H \leftarrow H + J_{\text{new}}^\top \Sigma_{\text{new}}^{-1} J_{\text{new}}`}],example:(0,n.jsxs)(n.Fragment,{children:[`그림의 기본값: `,(0,n.jsx)(t,{children:a`x_1 = 2`}),` m(σ₁ = 0.4 m), `,(0,n.jsx)(t,{children:a`x_2 = 3`}),` m(σ₂ = 0.2 m). 가중치는 1/0.16 = 6.25와 1/0.04 = 25이므로 `,(0,n.jsx)(t,{children:a`x^\ast = (2 \cdot 6.25 + 3 \cdot 25)/31.25 = 87.5/31.25 = 2.80`}),` m, `,(0,n.jsx)(t,{children:a`\sigma^\ast = \sqrt{1/31.25} \approx 0.179`}),` m입니다. `,(0,n.jsx)(t,{children:a`\bar x = 0`}),`에서 가우스–뉴턴 한 단계로도 같은 결과가 나옵니다. `,(0,n.jsx)(t,{children:a`J = [1, 1]^\top`}),`, `,(0,n.jsx)(t,{children:a`r = [-2, -3]^\top`}),`, `,(0,n.jsx)(t,{children:a`H = 6.25 + 25 = 31.25`}),`, `,(0,n.jsx)(t,{children:a`-J^\top \Sigma^{-1} r = 12.5 + 75 = 87.5`}),`이므로 `,(0,n.jsx)(t,{children:a`\delta = 2.80`}),`입니다. 문제가 선형이라 한 단계로 정확하며, `,(0,n.jsx)(t,{children:a`H^{-1} = 0.032`}),` m²가 σ*²입니다.`]}),paper:(0,n.jsx)(n.Fragment,{children:`iSAM2(Kaess 등)는 인수분해한 정보 행렬을 베이즈 트리로 표현하고, 점진적으로 갱신하며 선택적으로 다시 선형화합니다(“fluid relinearisation”). LIO-SAM은 그래프를 iSAM2로 풉니다.`}),site:(0,n.jsxs)(n.Fragment,{children:[`그림은 정확한 1-D 결합을 가우시안 곡선으로 그린 것입니다. Playground의 그래프 모델은 SE(2) 위에서 해석적 야코비안과 조밀 숄레스키 풀이로 가우스–뉴턴을 최대 8회 반복하며, 키프레임 0을 고정합니다. 점진적이 아닌 일괄 방식이고 공분산은 표시하지 않습니다. 필터 모델은 같은 생각을 순차적으로 적용합니다: `,(0,n.jsx)(t,{children:a`P \leftarrow (H + P^{-1})^{-1}`}),`.`]}),dataset:(0,n.jsx)(n.Fragment,{children:`4F 포즈는 최적화기의 출력이지만, 그 공분산도 주행의 팩터 잡음 모델도 저장되지 않았으므로 이 사이트는 어떤 4F 포즈의 불확실성도 밝힐 수 없습니다.`}),interactiveLink:(0,n.jsxs)(n.Fragment,{children:[`슬라이더는 σ₁과 σ₂, 곧 `,(0,n.jsx)(t,{children:a`\Sigma = \mathrm{diag}(\sigma_1^2, \sigma_2^2)`}),`를 정합니다. 표시되는 결합값과 그 σ는 결합 공식의 `,(0,n.jsx)(t,{children:a`x^\ast`}),`와 `,(0,n.jsx)(t,{children:a`\sigma^\ast`}),`이고, 곡선은 `,(0,n.jsx)(t,{children:a`\mathcal{N}(x_i, \sigma_i^2)`}),`와 `,(0,n.jsx)(t,{children:a`\mathcal{N}(x^\ast, \sigma^{\ast 2})`}),`입니다.`]}),check:{q:`두 측정의 σ가 모두 0.2 m입니다. 서로 독립이면 결합 σ는 얼마이고, 실제로는 완전히 상관되어 있다면(예: 같은 오차 원인) 어떻게 될까요?`,options:[`두 경우 모두 0.141 m`,`독립이면 0.141 m, 완전히 상관되어 있으면 여전히 0.2 m`,`독립이면 0.1 m`],answer:1,explain:(0,n.jsxs)(n.Fragment,{children:[`독립 측정이면 `,(0,n.jsx)(t,{children:a`0.2/\sqrt{2} \approx 0.141`}),` m입니다. 완전히 상관된 두 번째 측정은 정보를 더하지 않으며, 이를 독립으로 취급하면 결과가 과신하게 됩니다.`]})}}},{beginner:{question:(0,n.jsx)(n.Fragment,{children:`로봇이 전에 본 장소로 돌아왔을 때, 그 재방문 한 번이 어떻게 루프 전체의 누적 오차를 고치고, 어떻게 속지 않을까요?`}),analogy:(0,n.jsx)(n.Fragment,{children:`걸음 수를 세며 한 블록을 돌아 우리 집 현관에 도착했는데, 걸음 수로는 현관을 3 m 지나쳤다고 나옵니다. 현관에 있다는 것을 알기 때문에, 끝에서 한 번에 뛰어 맞추는 대신 3 m 보정을 걸어온 길 전체에 나눕니다. 이 비유는 똑같이 생긴 문에서 한계가 있습니다. 이웃집의 똑같은 문을 우리 집 문으로 착각하면, “보정”을 나누는 일이 오히려 경로 전체를 잘못 휘게 만듭니다. 그래서 재방문은 반드시 검증해야 합니다.`}),story:[(0,n.jsxs)(n.Fragment,{children:[`오도메트리 오차는 경로를 따라 쌓이며, 이를 `,(0,n.jsx)(`strong`,{children:`드리프트`}),`라고 합니다. 루프를 한 바퀴 돌고 나면, 로봇은 실제로 출발점에 돌아왔는데도 추정 끝점은 시작점과 만나지 않습니다. 필터는 과거 포즈가 더 이상 변수가 아니므로 이것을 고칠 수 없지만, 그래프는 고칠 수 있습니다.`]}),(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(`strong`,{children:`검출.`}),` LIO-SAM 참조 구현은 현재 키 포즈에서 탐색 반경 안에 있고 시간적으로 충분히 오래된 이전 키 포즈를 찾습니다. 이런 후보는 추측일 뿐입니다. 두 복도가 비슷해 보일 수 있고, 현재 추정 자체도 드리프트했기 때문입니다.`]}),(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(`strong`,{children:`검증.`}),` 스캔 정합(ICP, iterative closest point)으로 현재 키프레임의 스캔을 옛 키프레임 주변 지도에 맞춥니다. 정렬이 잘 맞을 때만 후보를 받아들이고, 그렇지 않으면 버립니다.`]}),(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(`strong`,{children:`구속과 최적화.`}),` 측정한 상대 포즈는 시간상 멀리 떨어진 두 키프레임 사이의 `,(0,n.jsx)(`strong`,{children:`루프 팩터`}),`가 됩니다. 최적화기는 쌓인 오차를 루프 전체에 다시 나누고, 보정된 포즈로 지도를 다시 만듭니다.`]}),(0,n.jsx)(n.Fragment,{children:`4F에서 LIO-SAM 궤적의 시작과 끝은 약 0.317 m 떨어져 있고, 같은 데이터에서 FAST-LIO는 27.77 m 떨어져 끝납니다. 루프 클로저는 켜져 있었지만 루프 팩터 수가 기록되지 않았으므로, 작은 차이는 루프 클로저와 들어맞을 뿐 그것을 증명하지는 않습니다.`})],tryIt:(0,n.jsx)(n.Fragment,{children:`그림에서 네 단계(검출, 검증, 팩터 추가, 최적화)를 차례로 진행하며 드리프트한 경로가 보정된 경로로 바뀌는 모습을 보세요. Playground의 “루프 클로저” 실험에서는 모든 시도와 그것이 채택되거나 거부된 이유가 기록에 나옵니다.`}),misconception:(0,n.jsx)(n.Fragment,{children:`“시작–끝 거리가 작으면 루프 클로저가 성공했다는 증거다.” 좋은 오도메트리만으로도 시작점 가까이에서 끝날 수 있고, 잘못된 루프는 경로 가운데를 왜곡하면서도 작은 차이를 만들 수 있습니다.`}),summary:[(0,n.jsx)(n.Fragment,{children:`루프 클로저는 검증된 재방문을 시간상 멀리 떨어진 두 키프레임 사이의 구속으로 바꿉니다.`}),(0,n.jsx)(n.Fragment,{children:`최적화기는 끝만 고치는 대신 누적된 드리프트를 루프 전체에 나눕니다.`}),(0,n.jsx)(n.Fragment,{children:`잘못된 루프는 지도 전체를 휘게 하므로 후보를 검증해야 하며, 4F의 0.317 m 폐합은 루프 클로저와 들어맞지만 증거는 아닙니다.`})]},advanced:{objectives:[(0,n.jsx)(n.Fragment,{children:`Log 사상을 써서 SE(3) 위의 루프 잔차를 쓴다.`}),(0,n.jsx)(n.Fragment,{children:`후보 탐색과 기하학적 검증, 그 임계값을 설명한다.`}),(0,n.jsx)(n.Fragment,{children:`루프가 사슬 위에 오차를 어떻게 나누는지 계산하고, 제곱 비용에서 잘못된 루프가 왜 그토록 해로운지 설명한다.`})],model:[[`변수`,(0,n.jsxs)(n.Fragment,{children:[`월드 좌표계의 키프레임 포즈 `,(0,n.jsx)(t,{children:a`T_i \in SE(3)`}),`.`]})],[`측정`,(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t,{children:a`\hat T_{ij}`}),`: 키프레임 `,(0,n.jsx)(t,{children:`j`}),`의 스캔을 키프레임 `,(0,n.jsx)(t,{children:`i`}),` 주변 국소 지도에 정합해 얻은 상대 포즈로, `,(0,n.jsx)(t,{children:`i`}),`의 좌표계로 표현합니다.`]})],[`검출`,(0,n.jsx)(n.Fragment,{children:`키 포즈 위치에 대한 반경 탐색과 최소 시간 간격(참조 구현). 4F 주행의 값은 기록되지 않았습니다.`})],[`검증`,(0,n.jsx)(n.Fragment,{children:`참조 구현은 ICP 적합도 임계값을 쓰고, Playground는 아래의 명시적 규칙을 씁니다.`})],[`잡음`,(0,n.jsxs)(n.Fragment,{children:[`가우시안 루프 공분산 `,(0,n.jsx)(t,{children:a`\Sigma_{\text{loop}}`}),`. 비용이 이차식이므로 잘못된 루프가 낮게 가중되지 않으며, 검증이 주된 방어입니다.`]})]],steps:[{title:`후보`,text:(0,n.jsxs)(n.Fragment,{children:[`현재 위치 `,(0,n.jsx)(t,{children:a`p_j`}),`(추정) 근처에 있고 최소 `,(0,n.jsx)(t,{children:a`\tau`}),`만큼 오래된 이전 키프레임.`]}),tex:a`\mathcal{C}_j = \{\, i : \lVert p_i - p_j \rVert < \rho,\ \ t_j - t_i > \tau \,\}`},{title:`검증`,text:(0,n.jsxs)(n.Fragment,{children:[`스캔 점 `,(0,n.jsx)(t,{children:a`q_k`}),`를 후보 주변 지도 점 `,(0,n.jsx)(t,{children:a`m_k`}),`에 정합하고, 잘 맞을 때만 받아들입니다.`]}),tex:a`\hat T_{ij} = \arg\min_T \textstyle\sum_k \lVert T q_k - m_k \rVert^2,\qquad \text{accept if fitness} < s_{\max}`},{title:`잔차`,text:(0,n.jsx)(n.Fragment,{children:`현재 포즈가 측정한 상대 포즈와 일치하면 0입니다. Log는 포즈 오차를 6-벡터(회전 rad, 이동 m)로 보냅니다.`}),tex:a`r_{\mathrm{loop}} = \mathrm{Log}\big(\hat T_{ij}^{-1}\; T_i^{-1}\, T_j\big)`},{title:`최적화`,text:(0,n.jsx)(n.Fragment,{children:`팩터를 더하고 그래프 전체를 다시 풉니다(16강).`}),tex:a`X^\ast = \arg\min_X \textstyle\sum_{\text{seq}} \lVert r \rVert^2_{\Sigma^{-1}} + \lVert r_{\mathrm{loop}} \rVert^2_{\Sigma_{\text{loop}}^{-1}}`},{title:`출력`,text:(0,n.jsx)(n.Fragment,{children:`보정된 포즈. 지도는 이 포즈로 다시 투영합니다(0강).`}),tex:a`M = \textstyle\bigcup_i T_i^\ast\, S_i`}],example:(0,n.jsxs)(n.Fragment,{children:[`1-D 사슬: `,(0,n.jsx)(t,{children:a`x_0 = 0`}),` 고정, 오도메트리는 `,(0,n.jsx)(t,{children:a`x_1 - x_0 = 1.0`}),`, `,(0,n.jsx)(t,{children:a`x_2 - x_1 = 1.0`}),` m, 루프 측정은 `,(0,n.jsx)(t,{children:a`x_2 - x_0 = 1.9`}),` m이며 σ는 모두 같습니다. 도함수를 0으로 두면 `,(0,n.jsx)(t,{children:a`2x_1 - x_2 = 0`}),`, `,(0,n.jsx)(t,{children:a`2x_2 - x_1 = 2.9`}),`이므로 `,(0,n.jsx)(t,{children:a`x_1 \approx 0.967`}),`, `,(0,n.jsx)(t,{children:a`x_2 \approx 1.933`}),` m입니다. 0.1 m의 불일치가 똑같이 나뉘어 각 잔차는 ±0.033 m입니다. 루프 팩터의 정보가 100배라면(σ가 10분의 1) `,(0,n.jsx)(t,{children:a`x_2 = 191/100.5 \approx 1.9005`}),`, `,(0,n.jsx)(t,{children:a`x_1 \approx 0.950`}),` m로, 보정의 거의 전부가 오도메트리 팩터로 갑니다.`]}),paper:(0,n.jsx)(n.Fragment,{children:`LIO-SAM은 루프 클로저를 그래프의 팩터로 추가합니다. 저자 README에 따르면 참조 구현의 루프 클로저는 ICP 기반이며 LeGO-LOAM에서 가져왔습니다. 4F 주행에 쓴 탐색 반경, 시간 간격, 적합도 임계값은 기록되지 않았습니다.`}),site:(0,n.jsx)(n.Fragment,{children:`그림은 합성 경로를 단계별로 보여 줍니다. Playground의 그래프 모델은 현재 추정에서 2.5 m 안에 있고 최소 15 키프레임 이전인 가장 가까운 키프레임을 골라, 그 키프레임 ± 이웃 3개와 정합(최대 15회 반복)하고, 수렴했고 점의 50 % 이상이 대응되었으며 RMS < 0.06 m이고 보정량 < 2 m일 때만 받아들입니다. 모든 시도와 그 이유를 기록한 뒤, 조밀 가우스–뉴턴으로 그래프를 다시 최적화합니다.`}),dataset:(0,n.jsx)(n.Fragment,{children:`4F: 루프 클로저 켬, 루프 팩터 수 미상. 약 343.3 m, 약 401.2 s 경로에서 시작–끝 거리 약 0.317 m. 루프 클로저가 없는 FAST-LIO는 같은 데이터에서 27.77 m. 이는 시작–끝 거리만 비교한 것이며, 4F 결과를 루프 클로저만의 효과로 돌리지 않습니다.`}),interactiveLink:(0,n.jsxs)(n.Fragment,{children:[`그림의 네 단계는 `,(0,n.jsx)(t,{children:a`\mathcal{C}_j`}),`, `,(0,n.jsx)(t,{children:a`\hat T_{ij}`}),`, `,(0,n.jsx)(t,{children:a`r_{\mathrm{loop}}`}),`, `,(0,n.jsx)(t,{children:a`X^\ast`}),`입니다. Playground에서는 2.5 m 탐색 반경이 `,(0,n.jsx)(t,{children:a`\rho`}),`, 15 키프레임 간격이 `,(0,n.jsx)(t,{children:a`\tau`}),`의 역할을 하고, RMS와 대응 비율 규칙이 `,(0,n.jsx)(t,{children:a`s_{\max}`}),`입니다.`]}),check:{q:`σ가 작은 잘못된 루프 팩터가 3 m 떨어진 비슷한 두 복도 사이에 추가되었습니다. 단순 최소제곱 비용에서는 무슨 일이 일어날까요?`,options:[`오도메트리와 어긋나므로 최적화기가 무시한다`,`두 복도를 끌어당겨 궤적을 휘게 한다`,`이 팩터가 잇는 두 키프레임만 움직인다`],answer:1,explain:(0,n.jsx)(n.Fragment,{children:`자신 있는 팩터의 제곱 비용은 빠르게 커지므로, 최적화기는 이를 만족시키려고 많은 오도메트리 팩터를 조금씩 변형합니다. 검증, 강건 커널, 전환 가능한 구속(switchable constraints)이 방어 수단입니다.`})}}},{beginner:{question:(0,n.jsx)(n.Fragment,{children:`공개된 지도에서 두 파이프라인에 대해 정직하게 배울 수 있는 것은 무엇이고, 배울 수 없는 것은 무엇일까요?`}),analogy:(0,n.jsx)(n.Fragment,{children:`날씨가 다른 날 서로 다른 건물을 찍은 사진으로 두 사진가를 평가한다고 상상해 보세요. 각 사진에 대해서는 많은 것을 알 수 있지만, 누가 더 나은 사진가인지는 알 수 없습니다. 이 비유는 기록에서 한계가 있습니다. 대부분의 사진과 달리, 여기의 모든 지도에는 무엇을 확인할 수 있고 없는지 정확히 알려 주는 출처 기록이 붙어 있습니다.`}),story:[(0,n.jsxs)(n.Fragment,{children:[`먼저 무엇이 있는지 봅시다. 2F, 3F, 6F, 8F는 FAST-LIO로 처리·정리한 지도로, 점마다 x y z만 있고 궤적은 없습니다. 4F는 LIO-SAM 정본 지도로, `,(0,n.jsx)(`code`,{children:`x y z r g b t zg`}),`를 가진 점 26,000,000개와 포즈 4,013개의 궤적이 있습니다.`]}),(0,n.jsxs)(n.Fragment,{children:[`필드를 주의해서 읽으세요. 4F의 `,(0,n.jsx)(`code`,{children:`r g b`}),`는 카메라 색이 아니라 처리 과정에서 입힌 높이 무지개색입니다. `,(0,n.jsx)(`code`,{children:`t`}),`는 그 점을 정합한 LIO-SAM 스캔의 시각으로, 첫 포즈부터 잰 값입니다. 개별 점이 발사된 순간이 아닙니다. `,(0,n.jsx)(`code`,{children:`zg`}),`는 그 시각 로봇 포즈를 기준으로 한 높이입니다.`]}),(0,n.jsx)(n.Fragment,{children:`뷰어는 항상 전체 지도가 아니라 솎아 낸 상세 단계를 보여 줍니다. 3F는 77,963, 179,605, 818,961점(마지막이 전체)이고, 4F는 2,600만 점 중 130,736, 889,798, 2,877,039점을 보여 줍니다. 따라서 층이 얼마나 촘촘해 보이는지는 고른 상세 단계에도 일부 달려 있습니다.`}),(0,n.jsx)(n.Fragment,{children:`측정 도구는 웹 미리보기에서 작동합니다. 정확도는 미리보기 점의 정확도이며, 비교할 참값은 없습니다. 4F의 희미한 줄무늬 일부는 지나간 사람의 잔상일 수 있습니다. 자동 정리 방법을 평가하고 있지만 승인되지 않았으므로, 공개 지도는 바뀌지 않았습니다.`}),(0,n.jsx)(n.Fragment,{children:`층들은 서로 다른 장소이고, 서로 다른 파이프라인으로 만들었으며, 서로 정합되어 있지 않고 참값도 없습니다. 그래서 뷰어로는 알고리즘의 순위를 매길 수 없습니다. 같은 데이터로 비교한 것은 4F 궤적 한 쌍뿐이고(시작–끝 LIO-SAM 0.317 m 대 FAST-LIO 27.77 m), 그것조차 정확도 지표가 아닙니다.`})],tryIt:(0,n.jsx)(n.Fragment,{children:`다섯 과제를 차례로 해 보세요. 3F를 높음 상세로 열어 벽 두께를 보고, 4F를 열어 궤적을 켜고, 복도 폭을 재고, 낮음·중간·높음을 바꾸며 실제 점 수를 읽고, 다운로드 안내를 엽니다. 과제마다 결론 내릴 수 있는 것 한 문장과 내릴 수 없는 것 한 문장을 적어 보세요.`}),misconception:(0,n.jsx)(n.Fragment,{children:`“4F(LIO-SAM)가 3F(FAST-LIO)보다 선명해 보이니 LIO-SAM이 더 정확하다.” 두 층은 서로 다른 장소이고, 점 수와 후처리가 다르며, 참값도 없습니다.`}),summary:[(0,n.jsx)(n.Fragment,{children:`공개된 모든 지도에는 출처, 곧 어떤 파이프라인·어떤 필드·어떤 후처리를 거쳤는지가 함께 있습니다.`}),(0,n.jsxs)(n.Fragment,{children:[`필드의 의미가 중요합니다. 4F 색은 높이 무지개색이고, `,(0,n.jsx)(`code`,{children:`t`}),`는 정합한 스캔의 시각입니다.`]}),(0,n.jsx)(n.Fragment,{children:`같은 데이터와 기준이 없으면 지도만으로는 어느 알고리즘이 더 정확한지 알 수 없습니다.`})]},advanced:{objectives:[(0,n.jsx)(n.Fragment,{children:`모든 관찰을 출처(파이프라인, 필드, 좌표계, 후처리)에 연결한다.`}),(0,n.jsx)(n.Fragment,{children:`상세 단계 솎아 내기와 시작–끝 거리를 수치로 나타내고 그 한계를 밝힌다.`}),(0,n.jsx)(n.Fragment,{children:`정확도 비교를 가능하게 하는 실험을 설계한다.`})],model:[[`데이터`,(0,n.jsxs)(n.Fragment,{children:[`2F/3F/6F/8F: FAST-LIO 처리·정리, `,(0,n.jsx)(`code`,{children:`x y z`}),`, 궤적 없음. 4F: LIO-SAM 정본, 26,000,000 × `,(0,n.jsx)(`code`,{children:`x y z r g b t zg`}),`, 포즈 4,013개. 4F FAST-LIO 포즈는 비교용 데이터일 뿐입니다.`]})],[`좌표계`,(0,n.jsx)(n.Fragment,{children:`층마다 고유한 지도 좌표계를 가집니다(FAST-LIO 층: 바닥 z = 0, +z 위, 반전 없음). 층끼리는 정합되어 있지 않습니다. 4F 포즈는 LiDAR 좌표계입니다(쿼터니언 순서 x y z w).`})],[`필드`,(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(`code`,{children:`t`}),` = 첫 포즈 기준 정합 스캔 시각(서로 다른 값 4,013개), `,(0,n.jsx)(t,{children:a`z - z_g`}),`는 `,(0,n.jsx)(`code`,{children:`t`}),` 시각의 포즈 높이와 같음, `,(0,n.jsx)(`code`,{children:`r g b`}),`는 입힌 높이 색.`]})],[`후처리`,(0,n.jsx)(n.Fragment,{children:`4F 지도는 매핑 후 필터링했으며, 스윕마다 약 20 %가 남았습니다. 각 FAST-LIO 층을 만든 설정은 기록되지 않았습니다.`})],[`없는 것`,(0,n.jsx)(n.Fragment,{children:`참값 없음, FAST-LIO 층의 원본 기록은 배포 호스트에 없음, 전체 LIO-SAM 파라미터 파일 없음. 4F 잔상 정리 후보는 NEEDS_REVIEW이며 공개 데이터에 포함되지 않습니다.`})]],steps:[{title:`출처`,text:(0,n.jsxs)(n.Fragment,{children:[`보이는 것을 해석하기 전에 `,(0,n.jsx)(`code`,{children:`floors.json`}),`에서 층마다 알고리즘, 출처, 상태를 읽습니다.`]})},{title:`상세 단계`,text:(0,n.jsx)(n.Fragment,{children:`뷰어가 그리는 정본 점의 비율. 4F 높음은 약 11.1 %, 3F 중간은 약 21.9 %입니다.`}),tex:a`\rho = \frac{N_{\text{LOD}}}{N_{\text{canonical}}},\qquad \frac{2{,}877{,}039}{26{,}000{,}000} \approx 0.111,\qquad \frac{179{,}605}{818{,}961} \approx 0.219`},{title:`측정`,text:(0,n.jsx)(n.Fragment,{children:`고른 미리보기 점 두 개 사이의 거리. 불확실성에는 선택한 상세 단계의 점 간격이 포함됩니다.`}),tex:a`d = \lVert p_a - p_b \rVert`},{title:`궤적`,text:(0,n.jsx)(n.Fragment,{children:`4F LIO-SAM 궤적의 시작–끝 거리와 경로 길이.`}),tex:a`d_{\text{close}} = \lVert p_N - p_0 \rVert \approx 0.317\ \text{m},\qquad L = \textstyle\sum_k \lVert p_{k+1} - p_k \rVert \approx 343.3\ \text{m}`},{title:`공정한 비교(여기서는 불가능)`,text:(0,n.jsx)(n.Fragment,{children:`같은 기록을 두 파이프라인으로 처리하고, 기준 궤적을 두고, 좌표계를 맞춘 뒤(2강) ATE를 계산합니다.`}),tex:a`\mathrm{ATE} = \sqrt{\tfrac1N \textstyle\sum_k \lVert \hat p_k - (R\, p_k^{\mathrm{ref}} + t) \rVert^2}`}],example:(0,n.jsxs)(n.Fragment,{children:[`경로 길이에 대한 4F 폐합 비율은 `,(0,n.jsx)(t,{children:a`0.317 / 343.3 \approx 0.00092`}),`, 약 0.09 %입니다. 이는 끝이 시작 가까이로 돌아왔다는 뜻일 뿐, 더 클 수도 있는 경로 중간의 오차에 상한을 주지 않습니다. 점 수 비율은 층 사이 시각적 차이의 일부를 설명합니다. 4F 높음은 약 아홉 점 중 하나, 3F 중간은 약 다섯 점 중 하나를 그립니다.`]}),paper:(0,n.jsx)(n.Fragment,{children:`FAST-LIO2(Xu 등)는 루프 클로저 없는 필터이고, LIO-SAM(Shan 등)은 루프 클로저가 있는 스무더입니다. 두 논문은 참값이 있는 자체 데이터셋에서 정확도를 보고하며, 그 수치는 이 층들에 옮겨 쓸 수 없습니다.`}),site:(0,n.jsx)(n.Fragment,{children:`각 실습 과제는 미리 정한 층, 상세 단계, 색 모드, 레이어로 뷰어를 엽니다. Playground는 참값이 있는 합성 장면에서 FAST-LIO 영감 모델과 LIO-SAM 영감 모델을 비교하며, 그 ATE는 시뮬레이션 안에서만 의미가 있고 시드에 따라 달라집니다.`}),dataset:(0,n.jsx)(n.Fragment,{children:`사실: 점 수, 필드, 4F 궤적(포즈 4,013개, 약 401.2 s), 4F 폐합(약 0.317 m), 같은 데이터의 FAST-LIO 비교(27.77 m). 미상: 각 FAST-LIO 층의 설정, 4F 루프 팩터 수, 전체 파라미터 파일. 미공개: 4F 잔상 후보(v1, v2 모두 NEEDS_REVIEW).`}),interactiveLink:(0,n.jsxs)(n.Fragment,{children:[`과제 버튼은 층, 상세 단계(`,(0,n.jsx)(t,{children:a`N_{\text{LOD}}`}),`), 색 모드, 궤적 레이어(포즈 `,(0,n.jsx)(t,{children:a`p_k`}),`)를 정하고, 측정 도구가 `,(0,n.jsx)(t,{children:`d`}),`를 줍니다.`]}),check:{q:`FAST-LIO와 LIO-SAM의 정확도를 실제로 비교할 수 있게 해 주는 실험은 무엇일까요?`,options:[`뷰어에서 3F(FAST-LIO)와 4F(LIO-SAM)의 벽 두께를 비교한다`,`4F 시작–끝 거리 0.317 m와 27.77 m를 비교한다`,`같은 기록을 두 방법으로 처리하고 기준 궤적과 좌표계를 맞춘 뒤 ATE를 계산한다`],answer:2,explain:(0,n.jsx)(n.Fragment,{children:`같은 입력 데이터와 독립적인 기준이 있어야 오차를 잴 수 있습니다. 시작–끝 거리는 경로의 한 지점에서 얻은 숫자 하나이고, 서로 다른 층은 서로 다른 장면입니다.`})}}}],s=[...r,...i,...o];export{s as DEPTH_KO};